const RESEARCH_BY_ID = Object.fromEntries(RESEARCH_NODES.map(n => [n.id, n]));

// tool kind -> node that unlocks it. Any tool NOT in this map (zones, Select, and anything a
// future agent adds without touching this file) is ungated by default -- fail-open, so a new
// buildable never becomes silently unplaceable just because nobody remembered research.js.
const RESEARCH_GATE_BY_TOOL = (() => {
  const m = {};
  for (const n of RESEARCH_NODES) for (const t of n.unlocks) m[t] = n.id;
  return m;
})();

function createResearchState() {
  const unlocked = {};
  for (const n of RESEARCH_NODES) if (n.startsUnlocked) unlocked[n.id] = true;
  return { points: 0, unlocked };
}

function isNodeUnlocked(state, nodeId) {
  return !!(state && state.unlocked && state.unlocked[nodeId]);
}

/** The gating node for a build tool, or null if the tool is ungated. */
function researchNodeForTool(tool) {
  const id = RESEARCH_GATE_BY_TOOL[tool];
  return id ? RESEARCH_BY_ID[id] : null;
}

/** Fail-open: unknown/ungated tools are always placeable. */
function isToolUnlocked(state, tool) {
  if (!tool) return true;
  const id = RESEARCH_GATE_BY_TOOL[tool];
  if (!id) return true;
  return isNodeUnlocked(state, id);
}

function researchPrereqsMet(state, node) {
  return node.requires.every(r => isNodeUnlocked(state, r));
}

/** Why a node can't be researched right now, or null if it can. */
function researchBlockedReason(state, node) {
  if (isNodeUnlocked(state, node.id)) return 'Already researched';
  if (!researchPrereqsMet(state, node)) {
    const missing = node.requires.filter(r => !isNodeUnlocked(state, r)).map(r => RESEARCH_BY_ID[r].name);
    return `Requires ${missing.join(' + ')}`;
  }
  if (state.points < node.cost) return `Needs ${Math.ceil(node.cost - state.points)} more points`;
  return null;
}

/** Spend points to unlock a node. Returns { ok, reason }. */
function tryResearch(state, nodeId) {
  const node = RESEARCH_BY_ID[nodeId];
  if (!node) return { ok: false, reason: 'No such research' };
  const blocked = researchBlockedReason(state, node);
  if (blocked) return { ok: false, reason: blocked };
  state.points -= node.cost;
  state.unlocked[node.id] = true;
  return { ok: true, node };
}

/** Passive accrual. Called once per world tick from world.js's tick(). */
function tickResearch(world) {
  let alive = 0;
  for (let i = 0; i < world.citizens.count; i++) if (world.citizens.isAliveAt(i)) alive++;
  world.research.points += alive * RESEARCH_PER_CITIZEN_TICK;
}

function serializeResearch(state) {
  return { points: state.points, unlocked: Object.keys(state.unlocked).filter(k => state.unlocked[k]) };
}

function deserializeResearch(json) {
  const state = createResearchState();
  if (!json) return state;
  state.points = json.points || 0;
  for (const id of json.unlocked || []) if (RESEARCH_BY_ID[id]) state.unlocked[id] = true;
  return state;
}


// ---- resources.js ----
// Scrap deposits scattered across the map -- the "harvest materials" loop that was missing
// (scrap only came from combat kills before). Citizens with no urgent need or job walk to the
// nearest node and harvest it over time, matching RimWorld's "colonists gather raw resources"
// loop rather than Prison Architect's pure-cash-purchase model (which still exists too: scrap
// from kills/recycling is the "it gets bought for you" side of the same resource).
class ResourceNode {
  constructor(x, y, amount) {
    this.x = x; this.y = y;
    this.amount = amount;
    this.maxAmount = amount;
    this.depleted = false;
  }
}

const NODE_MIN = 40, NODE_MAX = 90;

function scatterNodes(grid, rng, count, avoidRadius, avoidX, avoidY) {
  const nodes = [];
  let tries = 0;
  while (nodes.length < count && tries < count * 30) {
    tries++;
    const x = Math.floor(rng() * grid.width);
    const y = Math.floor(rng() * grid.height);
    if (Math.hypot(x - avoidX, y - avoidY) < avoidRadius) continue;
    if (grid.isBlocked(x, y)) continue;
    nodes.push(new ResourceNode(x + 0.5, y + 0.5, NODE_MIN + rng() * (NODE_MAX - NODE_MIN)));
  }
  return nodes;
}

// Occasionally drops a fresh node somewhere on the map so the economy doesn't dry up over a
// long session -- soak-testing the first version of this game showed scrap flow stalling hard
// once kill-rewards were the only source and the player wasn't actively harvesting.
function maybeSpawnNode(nodes, grid, rng, currentTick, avoidX, avoidY) {
  if (currentTick % 400 !== 0) return;
  if (nodes.filter(n => !n.depleted).length > 14) return;
  const spawned = scatterNodes(grid, rng, 1, 10, avoidX, avoidY);
  nodes.push(...spawned);
}


// ---- vehicles.js ----
// Vehicles, the Super Energy Apocalypse: Recycled side of the mashup -- garbage/recycling
// trucks. Unlike the first pass, these don't spawn on their own: a citizen has to build the
// garage (blueprint, same construction pipeline as everything else) and then a citizen has to
// drive it. An undriven truck just sits parked at its garage.

const VEHICLE_SPEED = 0.11;
const GARBAGE_BONUS_MIN = 15, GARBAGE_BONUS_MAX = 40;
const DRIVER_ENTER_RANGE = 0.5;
const BASE_WORK_TIMER = 20;

// SEA:R's truck fuel-type tradeoff (see FEATURE_RESEARCH.md): each truck picks one of four
// fuels at garage-build time (garage variant, see economy.js/input.js), a genuine tradeoff
// rather than a strict-best choice:
//  - fossil: cheapest garage, but the dirtiest -- every haul cycle belches real exhaust
//    pollution on top of whatever the haul itself does.
//  - gas: the "best all-around" middle ground -- moderate cost, low exhaust.
//  - ethanol: clean exhaust, but it's brewed from the settlement's food surplus -- completing
//    a haul temporarily saps the Food zone's refill rate (there's no bulk food-stockpile
//    resource in this codebase to drain directly, so this is the most honest portable stand-in).
//  - electric: cleanest exhaust of all, but energy-hungry -- a haul only runs at full speed if
//    the garage is actually powered (world.isPowered, same connected-power-graph turrets use);
//    unpowered, the work phase drags on far longer.
const FUEL_TYPES = Object.freeze({
  fossil:   { label: 'Fossil Fuel', costMult: 0.75, exhaustPollution: 3.5,  ethanolPenalty: false, requiresPower: false },
  gas:      { label: 'Natural Gas', costMult: 1.0,  exhaustPollution: 1.0,  ethanolPenalty: false, requiresPower: false },
  ethanol:  { label: 'Ethanol',     costMult: 1.15, exhaustPollution: 0.3,  ethanolPenalty: true,   requiresPower: false },
  electric: { label: 'Electric',    costMult: 1.4,  exhaustPollution: 0.05, ethanolPenalty: false, requiresPower: true },
});
const DEFAULT_FUEL_TYPE = 'gas';
const ETHANOL_PENALTY_TICKS = 150; // ~15s at the 10Hz tick rate -- Food zone refill roughly halved meanwhile
const UNPOWERED_ELECTRIC_WORK_MULT = 2.5; // an electric truck with no generator feeding its garage crawls

// Garage build-toolbar kinds are 'garage_<recycling|garbage>_<fuel>' (plus the original bare
// 'garage_recycling'/'garage_garbage' kept working as a 'gas' default for save-compat and for
// any other in-flight work still referencing the un-suffixed kind). Centralized here so
// world.js's structure-filter pass and input.js's toolbar stay in sync off one source of truth.
function parseGarageKind(kind) {
  if (kind === 'garage_recycling') return { truckKind: 'recycling', fuelType: DEFAULT_FUEL_TYPE };
  if (kind === 'garage_garbage') return { truckKind: 'garbage', fuelType: DEFAULT_FUEL_TYPE };
  const m = /^garage_(recycling|garbage)_(fossil|gas|ethanol|electric)$/.exec(kind);
  return m ? { truckKind: m[1], fuelType: m[2] } : null;
}

class Vehicle {
  constructor(kind, garageX, garageY, fuelType = DEFAULT_FUEL_TYPE) {
    this.kind = kind; // 'recycling' | 'garbage'
    this.fuelType = fuelType; // 'fossil' | 'gas' | 'ethanol' | 'electric', see FUEL_TYPES above
    this.garageX = garageX; this.garageY = garageY;
    this.x = garageX; this.y = garageY;
    this.driverId = null;
    this.phase = 'parked'; // parked -> inbound -> working -> outbound -> parked
    this.workTimer = 0;
    this.targetNode = null;
  }
}

// Called when a garage blueprint finishes construction (see world.js) -- one vehicle per
// garage, parked and waiting for a driver.
function spawnParkedVehicle(world, kind, x, y, fuelType = DEFAULT_FUEL_TYPE) {
  world.vehicles.push(new Vehicle(kind, x, y, fuelType));
}

function findUndrivenVehicle(vehicles, x, y) {
  let best = null, bestDist = Infinity;
  for (const v of vehicles) {
    if (v.driverId != null || v.phase !== 'parked') continue;
    const d = Math.hypot(v.x - x, v.y - y);
    if (d < bestDist) { bestDist = d; best = v; }
  }
  return best;
}

// Called by jobs.js once a citizen has walked up to a parked vehicle -- hands over the wheel
// and kicks off one haul cycle.
function boardVehicle(world, vehicle, citizenId) {
  vehicle.driverId = citizenId;
  if (vehicle.kind === 'recycling') {
    const candidates = world.resourceNodes.filter(n => !n.depleted && n.amount > 10);
    vehicle.targetNode = candidates.length ? candidates[Math.floor(world.rng() * candidates.length)] : null;
    if (!vehicle.targetNode) { vehicle.phase = 'outbound'; vehicle.targetX = vehicle.garageX; vehicle.targetY = vehicle.garageY; return; }
  } else {
    vehicle.targetX = world.width / 2 + (world.rng() - 0.5) * 6;
    vehicle.targetY = world.height / 2 + (world.rng() - 0.5) * 6;
  }
  vehicle.phase = 'inbound';
}

function tickVehicles(world) {
  for (const v of world.vehicles) {
    if (v.driverId == null) continue; // parked, waiting for a driver -- nothing to do

    if (v.phase === 'inbound') {
      const tx = v.kind === 'recycling' ? v.targetNode?.x : v.targetX;
      const ty = v.kind === 'recycling' ? v.targetNode?.y : v.targetY;
      if (tx == null || (v.kind === 'recycling' && v.targetNode.depleted)) {
        v.phase = 'outbound'; v.targetX = v.garageX; v.targetY = v.garageY; continue;
      }
      const dx = tx - v.x, dy = ty - v.y;
      const dist = Math.hypot(dx, dy);
      if (dist < 0.6) {
        v.phase = 'working';
        const fuel = FUEL_TYPES[v.fuelType] || FUEL_TYPES[DEFAULT_FUEL_TYPE];
        // Electric's "energy-hungry" bite: without a generator actually feeding the garage,
        // the haul takes far longer -- the same connected-power-graph check turrets use, not a
        // fake stat.
        v.workTimer = (fuel.requiresPower && !isPowered(world.structures, v.garageX, v.garageY))
          ? BASE_WORK_TIMER * UNPOWERED_ELECTRIC_WORK_MULT : BASE_WORK_TIMER;
      }
      else { v.x += (dx / dist) * VEHICLE_SPEED; v.y += (dy / dist) * VEHICLE_SPEED; }
      continue;
    }

    if (v.phase === 'working') {
      v.workTimer--;
      if (v.workTimer <= 0) {
        const fuel = FUEL_TYPES[v.fuelType] || FUEL_TYPES[DEFAULT_FUEL_TYPE];
        // Every completed haul burns fuel regardless of what the haul itself does -- fossil
        // trucks visibly dirty the air as they work, gas trucks a little, ethanol/electric
        // almost none. This is on top of (not instead of) the garbage truck's own
        // pollution-reduction below, so a cheap fossil garbage truck is a real net-worse
        // cleaner than a gas or electric one despite costing less to build.
        world.pollution = Math.max(0, world.pollution + fuel.exhaustPollution);
        if (fuel.ethanolPenalty) world.ethanolPenaltyTimer = ETHANOL_PENALTY_TICKS;
        if (v.kind === 'recycling' && v.targetNode && !v.targetNode.depleted) {
          world.addScrap(Math.round(v.targetNode.amount), 'haul');
          v.targetNode.amount = 0;
          v.targetNode.depleted = true;
        } else {
          // Garbage trucks haul off waste rather than scrap -- SEA:R's actual mechanic (see
          // FEATURE_RESEARCH.md): a real pollution reduction plus a small scrap side-benefit
          // from whatever's recoverable, not primarily a scrap-generation vehicle.
          world.pollution = Math.max(0, world.pollution - (25 + world.rng() * 20));
          world.addScrap(GARBAGE_BONUS_MIN + Math.floor(world.rng() * (GARBAGE_BONUS_MAX - GARBAGE_BONUS_MIN)), 'haul');
        }
        v.targetX = v.garageX; v.targetY = v.garageY;
        v.phase = 'outbound';
      }
      continue;
    }

    if (v.phase === 'outbound') {
      const dx = v.targetX - v.x, dy = v.targetY - v.y;
      const dist = Math.hypot(dx, dy);
      if (dist < 0.6) {
        // Back home -- release the driver (jobs.js clears their Driving state next tick when
        // it sees driverId no longer matches them) and park until someone boards again.
        v.driverId = null;
        v.phase = 'parked';
        v.x = v.garageX; v.y = v.garageY;
        continue;
      }
      v.x += (dx / dist) * VEHICLE_SPEED; v.y += (dy / dist) * VEHICLE_SPEED;
    }
  }
}


// ---- rooms.js ----
// Room detection via flood-fill, condensed from Prison Architect/RimWorld (see
// FEATURE_RESEARCH.md): a "room" is a connected passable area that does NOT touch the map
// edge -- i.e., it's actually enclosed by walls, not just open ground. Recomputed only when
// the wall layout changes (rare), not every tick.
// clamp01 is core.js's exported helper -- reused here (rather than a second local copy) so this
// file and core.js don't both declare a same-named top-level binding once build.py flattens
// everything into one classic script (import lines are stripped there, but the identifier still
// has to resolve to something real).


const NEIGHBORS = [[1, 0], [-1, 0], [0, 1], [0, -1]];
const MIN_ROOM_SIZE = 2;
const MAX_ROOM_SIZE = 400; // discourage "the whole map" from ever counting as one room

function detectRooms(grid) {
  const visited = new Uint8Array(grid.width * grid.height);
  const rooms = [];

  for (let y = 0; y < grid.height; y++) {
    for (let x = 0; x < grid.width; x++) {
      const idx = grid.index(x, y);
      if (visited[idx] || grid.wallThingId[idx] !== 0) continue;

      const cells = [];
      const queue = [[x, y]];
      visited[idx] = 1;
      let touchesEdge = (x === 0 || y === 0 || x === grid.width - 1 || y === grid.height - 1);

      while (queue.length) {
        const [cx, cy] = queue.pop();
        cells.push(grid.index(cx, cy));
        for (const [dx, dy] of NEIGHBORS) {
          const nx = cx + dx, ny = cy + dy;
          if (!grid.inBounds(nx, ny)) continue;
          const nidx = grid.index(nx, ny);
          if (visited[nidx] || grid.wallThingId[nidx] !== 0) continue;
          visited[nidx] = 1;
          if (nx === 0 || ny === 0 || nx === grid.width - 1 || ny === grid.height - 1) touchesEdge = true;
          queue.push([nx, ny]);
        }
      }

      if (!touchesEdge && cells.length >= MIN_ROOM_SIZE && cells.length <= MAX_ROOM_SIZE) {
        rooms.push({ cells: new Set(cells), size: cells.length });
      }
    }
  }
  return rooms;
}

function roomContaining(rooms, grid, x, y) {
  const idx = grid.index(Math.floor(x), Math.floor(y));
  for (const room of rooms) if (room.cells.has(idx)) return room;
  return null;
}

// Room stats (RimWorld-style beauty/cleanliness/impressiveness, see FEATURE_RESEARCH.md's
// "Room detection + room roles/stats" priority item). Deliberately kept separate from
// detectRooms above: detectRooms only re-runs when the *wall layout* changes (rare), but a
// room's contents (furniture built/destroyed, a fire breaking out, pollution drifting) change
// far more often, so computeRoomStats is meant to be called every tick against whatever `rooms`
// currently holds -- it mutates each room object in place rather than rebuilding the list.
//
// Beauty contribution per Structure kind (see siege.js's Structure class for the full kind
// list). Positive = "nice"/intentional furniture, negative = utilitarian/industrial/hazardous
// equipment that reads as ugly sitting inside a room a citizen actually lives in. Values are
// judgment calls, not ported from any single source game's exact numbers.
const BEAUTY_BY_KIND = {
  table: 2.5,      // sit-down furniture -- the clearest "nice" signal
  bed: 1.5,        // functional but still a deliberate furnishing choice
  door: 0.5,       // mild positive -- a room with a proper door reads as "finished"
  wire: -0.5,      // exposed wiring, mildly utilitarian
  turret: -2,      // a gun bolted to the floor of your room is not cozy
  fence: -1,
  trap: -2,
  tesla: -2,       // arcing electrical hazard
  floodlight: -1,  // stark industrial lighting
  watchtower: -1.5,
  camera: -0.5,
  monitor_station: -0.5,
  recycling_center: -2, // waste-processing machinery
  generator: -3,        // loud, utilitarian power equipment
  generator_nuclear: -6, // as above, worse -- also the nuclearWaste hazard below
  generator_coal: -4,    // dirtier than the plain generator, reads as worse to have indoors too
  generator_wind: -1,    // a turbine outdoors is far less obtrusive than boxy generator housing
  generator_solar: -1,   // same -- a panel array reads as mild infrastructure, not an eyesore
  waste_storage: -4,     // hazardous-waste containment, definitionally ugly
};

const CLEANLINESS_POLLUTION_DIVISOR = 20; // world.pollution this high alone fully tanks cleanliness
const CLEANLINESS_NUCLEAR_DIVISOR = 10;   // world.nuclearWaste this high alone fully tanks cleanliness
const CLEANLINESS_FIRE_PENALTY = 0.6;     // any structure actively on fire inside the room

// ---------------------------------------------------------------------------------------------
// Room roles (Prison Architect-style): an enclosed room only counts as a specific *role* -- and
// only feeds the jobs.js room-refill bonus for the matching need -- if it's both zoned right
// (zones.js's ZoneKind, same zone-painting system jobs.js already sends citizens to) AND
// furnished right (siege.js's Structure kinds). A room can be enclosed with no matching zone at
// all -- that's just generic "Unroofed Area"-style filler, same as PA's own unlabeled rooms.
//
// Requirement design notes (see task doc / FEATURE_RESEARCH.md for the broader room-roles ask):
//  - Bedroom: needs a Bedroom zone AND at least 1 bed. No fixed occupancy count is enforced here
//    -- jobs.js's zones.nearestOfKind(ZoneKind.Bedroom, ...) just walks a citizen to the nearest
//    Bedroom-zoned tile regardless of which/how many beds are in the room, there's no per-bed
//    reservation system to hook a capacity cap into. So "capacity" is reported for the UI
//    (bedCount) but isn't itself a validity gate -- 1 bed is enough to validate, more beds just
//    means more citizens can plausibly rest there at once without the mood/refill bonus lying.
//  - Dining Room: needs a Food zone AND at least 1 table.
//  - Recreation Room: needs a Recreation zone. No furniture requirement -- Recreation zones
//    don't have a canonical "furniture" kind the way beds/tables do (siege.js has no rec-room
//    Structure kind), so gating it on zone presence alone matches how jobs.js already treats it.
const RoomRole = Object.freeze({
  None: 'none',
  Bedroom: 'bedroom',
  DiningRoom: 'dining',
  RecreationRoom: 'recreation',
});

const ROOM_ROLE_LABEL = {
  [RoomRole.None]: 'Unroofed Area',
  [RoomRole.Bedroom]: 'Bedroom',
  [RoomRole.DiningRoom]: 'Dining Room',
  [RoomRole.RecreationRoom]: 'Recreation Room',
};

const BED_MIN = 1;
const TABLE_MIN = 1;

// Which zone kind implies which candidate role, checked in this priority order when a room
// happens to have more than one zone kind painted inside it (rare, but painting tools don't
// stop a player from mixing zones in one enclosed space) -- Bedroom first since an unmade bed
// is the highest-stakes miss (a citizen sleeping in the open loses the mood/refill bonus every
// night), then Food, then Recreation.
const ZONE_TO_ROLE = [
  [ZoneKind.Bedroom, RoomRole.Bedroom],
  [ZoneKind.Food, RoomRole.DiningRoom],
  [ZoneKind.Recreation, RoomRole.RecreationRoom],
];

// Which need (jobs.js's JobState-adjacent "what is this citizen here to refill") a validated
// role serves. Exported so jobs.js can gate ROOM_REFILL_BONUS by matching the citizen's current
// activity to the room they're standing in, rather than "any enclosed room" as before.
const ROLE_FOR_NEED = Object.freeze({
  hunger: RoomRole.DiningRoom,
  rest: RoomRole.Bedroom,
  social: RoomRole.RecreationRoom,
});

// Counts which ZoneKind cells appear inside a room. Small map, but a room can be large -- this
// is O(room.size), fine at the "only recompute when structures/zones change" cadence below.
function zoneCellCounts(room, grid, zones) {
  const counts = { [ZoneKind.Bedroom]: 0, [ZoneKind.Food]: 0, [ZoneKind.Recreation]: 0 };
  for (const idx of room.cells) {
    const kind = zones.kind[idx];
    if (kind === ZoneKind.Bedroom || kind === ZoneKind.Food || kind === ZoneKind.Recreation) counts[kind]++;
  }
  return counts;
}

// Classifies a single room's role given its zone coverage + furniture counts (bedCount/
// tableCount, tallied by computeRoomStats below while it's already walking structures for
// beauty). Returns { role, roleValid, missingRequirements }.
function classifyRoomRole(room, grid, zones, bedCount, tableCount) {
  const zoneCounts = zoneCellCounts(room, grid, zones);
  for (const [zoneKind, role] of ZONE_TO_ROLE) {
    if (zoneCounts[zoneKind] === 0) continue;
    if (role === RoomRole.Bedroom) {
      const valid = bedCount >= BED_MIN;
      return { role, roleValid: valid, missingRequirements: valid ? [] : ['a bed'], bedCount };
    }
    if (role === RoomRole.DiningRoom) {
      const valid = tableCount >= TABLE_MIN;
      return { role, roleValid: valid, missingRequirements: valid ? [] : ['a table'], tableCount };
    }
    if (role === RoomRole.RecreationRoom) {
      return { role, roleValid: true, missingRequirements: [] };
    }
  }
  return { role: RoomRole.None, roleValid: false, missingRequirements: [] };
}

// Call once per tick (world.js) with the *current* rooms/grid/structures/world state. Mutates
// each room with .beauty (raw sum, informational), .cleanliness, .impressiveness, and the
// combined .quality score (0..1) that citizens.js's tickNeedsAndMood reads to nudge mood. Also
// mutates .role/.roleValid/.missingRequirements (see classifyRoomRole above) -- zones is
// world.zones (zones.js's ZoneGrid), same grid dimensions/indexing as `grid` itself.
function computeRoomStats(rooms, grid, structures, world, zones) {
  for (const room of rooms) {
    let beauty = 0;
    let niceCount = 0;
    let onFireInside = false;
    let bedCount = 0;
    let tableCount = 0;

    for (const s of structures) {
      if (s.destroyed || s.underConstruction) continue;
      const sx = Math.floor(s.x), sy = Math.floor(s.y);
      if (!grid.inBounds(sx, sy)) continue;
      if (!room.cells.has(grid.index(sx, sy))) continue;

      const contribution = BEAUTY_BY_KIND[s.kind] ?? 0;
      beauty += contribution;
      if (contribution > 0) niceCount++;
      if (s.onFire) onFireInside = true;
      if (s.kind === 'bed') bedCount++;
      if (s.kind === 'table') tableCount++;
    }

    const pollution = world?.pollution ?? 0;
    const nuclearWaste = world?.nuclearWaste ?? 0;
    let cleanliness = 1 - pollution / CLEANLINESS_POLLUTION_DIVISOR - nuclearWaste / CLEANLINESS_NUCLEAR_DIVISOR;
    if (onFireInside) cleanliness -= CLEANLINESS_FIRE_PENALTY;
    cleanliness = clamp01(cleanliness);

    // Impressiveness: RimWorld's third room stat, driven by sheer scale + amount of positive
    // ("nice") furniture rather than the beauty/ugly balance -- a big hall full of tables reads
    // as impressive even before accounting for any ugly equipment dragging beauty down.
    const impressiveness = clamp01(room.size / MAX_ROOM_SIZE * 0.4 + niceCount * 0.1);

    room.beauty = beauty;
    room.cleanliness = cleanliness;
    room.impressiveness = impressiveness;
    room.quality = clamp01(0.5 + beauty * 0.05 + (impressiveness - 0.5) * 0.2) * cleanliness;

    if (zones) {
      const classified = classifyRoomRole(room, grid, zones, bedCount, tableCount);
      room.role = classified.role;
      room.roleValid = classified.roleValid;
      room.missingRequirements = classified.missingRequirements;
      room.bedCount = bedCount;
      room.tableCount = tableCount;
    } else {
      room.role = RoomRole.None;
      room.roleValid = false;
      room.missingRequirements = [];
    }
  }
}


// ---- power.js ----
// Power as a real connected wire graph, ported from Prison Architect's utilities grid (see
// FEATURE_RESEARCH.md: "Power/water as a real wired-graph network"). PA runs power from a
// station out along wire conduits; anything not physically on the wire run gets nothing, no
// matter how close it is. That connectivity rule is the part worth porting -- this replaces
// the old "any generator within POWER_RANGE" radius stub, which made adjacency irrelevant.
//
// The graph is a flood-fill over orthogonally-adjacent conductor tiles (generators + wires),
// same shape as rooms.js's detectRooms, and is recomputed only when the conductor layout
// actually changes -- mirroring the _roomsWallSignature check in world.js's tick().
const POWER_NEIGHBORS = [[1, 0], [-1, 0], [0, 1], [0, -1]];
const TILE_STRIDE = 100000; // packs (tx, ty) into one integer key; maps are far smaller than this

function powerTileKey(x, y) {
  return Math.floor(x) * TILE_STRIDE + Math.floor(y);
}

// SEA:R multi-source power economy (FEATURE_RESEARCH.md): coal is a straight cost/pollution
// tradeoff (see economy.js/world.js) and plugs into the grid exactly like a plain generator --
// no siting condition. Wind and solar DO carry a real siting condition though, and this codebase
// has no elevation or roof/indoor concept to check against (see grid.js's TerrainKind -- just
// Bare/Soil/Rock/Water -- and rooms.js's enclosed-room flood-fill, which is the closest thing to
// "indoors" that exists). Rather than invent fake elevation/roof data, each substitutes the
// honest nearest equivalent already in the sim:
//   - Wind ("needs high ground"): substituted with "needs open, unobstructed ground" -- no other
//     structure within WIND_CLEARANCE_RADIUS (wires/pipes excluded, since a turbine still needs a
//     wire run out to actually deliver anywhere; it's other buildings crowding the site that
//     count as the obstruction). Sited badly, it simply doesn't act as a power source at all this
//     tick -- a stark but honest and easily-verified stand-in for "reduced output", given this
//     engine's power model is a binary source/no-source graph (power.js has no notion of partial
//     wattage to reduce).
//   - Solar ("needs open sky"): substituted with "not built inside a detected enclosed room" (see
//     rooms.js's detectRooms -- a room is by definition walled-in on every side, the closest
//     analog to "roofed/indoors" this codebase has). world.js's tick() stamps s._openSky onto
//     every generator_solar structure each tick (mirroring the s._staffed pattern already used
//     for monitor_station); isSource below just reads it back. Same binary source/no-source
//     tradeoff as wind above, for the same reason.
const WIND_CLEARANCE_RADIUS = 2.5;

// Exported (rather than kept private like isSource/isConductor) so world.js's tick() can stamp
// s._windSited onto each generator_wind structure purely for render.js to read back and tint the
// turbine blades -- the power graph itself (isSource below) always recomputes this live and never
// depends on the stamped flag, so there's no lag in what actually gets powered, only in the paint.
function isWindSited(s, structures) {
  for (const other of structures) {
    if (other === s || other.kind === 'wire' || other.kind === 'pipe' || other.destroyed) continue;
    if (Math.hypot(other.x - s.x, other.y - s.y) <= WIND_CLEARANCE_RADIUS) return false;
  }
  return true;
}

// Any generator variant counts as a source (plain 'generator', 'generator_nuclear', ...) so new
// generator types plug into the grid without needing to be listed here -- except wind/solar,
// which are only sources when their siting condition (above) actually holds.
function isSource(s, structures) {
  if (s.kind === 'generator_wind') return isWindSited(s, structures);
  if (s.kind === 'generator_solar') return s._openSky !== false; // see world.js's tick(), defaults true until the first room pass
  return s.kind === 'generator' || s.kind.startsWith('generator_');
}

function isConductor(s, structures) {
  return (s.kind === 'wire' || isSource(s, structures)) && !s.destroyed && !s.underConstruction;
}

// Cheap order-sensitive hash of every live conductor's tile+kind, so the O(n) rebuild only runs
// when a wire/generator is built, finished, or destroyed -- not every tick for every turret. Also
// changes whenever a wind/solar generator's siting eligibility flips (isSource reads live state
// for those two), so a turbine losing its clearance or a solar array losing open sky correctly
// triggers a recompute instead of coasting on a stale cached graph.
function layoutSignature(structures) {
  let h = 17;
  for (let i = 0; i < structures.length; i++) {
    const s = structures[i];
    if (!isConductor(s, structures)) continue;
    h = (Math.imul(h, 31) + powerTileKey(s.x, s.y) + (isSource(s, structures) ? 7 : 3)) | 0;
  }
  return h;
}

let _cachedSignature = null;
let _cachedEnergized = new Set();

function computeEnergized(structures) {
  const conductors = new Set();
  const sources = [];
  for (const s of structures) {
    if (!isConductor(s, structures)) continue;
    const k = powerTileKey(s.x, s.y);
    conductors.add(k);
    if (isSource(s, structures)) sources.push(k);
  }

  const energized = new Set();
  const queue = [];
  for (const k of sources) {
    if (energized.has(k)) continue;
    energized.add(k);
    queue.push(k);
  }
  while (queue.length) {
    const k = queue.pop();
    const tx = Math.floor(k / TILE_STRIDE);
    const ty = k - tx * TILE_STRIDE;
    for (const [dx, dy] of POWER_NEIGHBORS) {
      const nk = (tx + dx) * TILE_STRIDE + (ty + dy);
      if (energized.has(nk) || !conductors.has(nk)) continue;
      energized.add(nk);
      queue.push(nk);
    }
  }
  return energized;
}

// Set of tile keys that are actually carrying power right now: every generator, plus every wire
// with an unbroken wire path back to one. Cut the chain and the far half goes dark.
function energizedTiles(structures) {
  const sig = layoutSignature(structures);
  if (sig !== _cachedSignature) {
    _cachedSignature = sig;
    _cachedEnergized = computeEnergized(structures);
  }
  return _cachedEnergized;
}

// True if this tile is itself energized (i.e. it holds a live wire/generator).
function isTileEnergized(structures, x, y) {
  return energizedTiles(structures).has(powerTileKey(x, y));
}

// Nuclear generator's reward half (see siege.js's NUCLEAR_HAZARD_* comment for the risk half):
// it energizes everything within a short radius directly, no wire run required, unlike a plain
// generator which only reaches through the conductor graph above. That's the "significantly more
// power" payoff for the waste-containment risk it carries.
const NUCLEAR_WIRELESS_RADIUS = 3;

function isNearActiveNuclearGenerator(structures, x, y) {
  for (const s of structures) {
    if (s.kind !== 'generator_nuclear' || s.destroyed || s.underConstruction) continue;
    if (Math.hypot(s.x - x, s.y - y) <= NUCLEAR_WIRELESS_RADIUS) return true;
  }
  return false;
}

// A consumer draws power if it sits on, or orthogonally touches, an energized tile -- so a
// turret can either hug the generator directly or be fed by a wire run from across the map --
// or if it's simply within a nuclear generator's wireless radius (no wire needed at all).
function isPoweredAt(structures, x, y) {
  if (isNearActiveNuclearGenerator(structures, x, y)) return true;
  const energized = energizedTiles(structures);
  if (energized.size === 0) return false;
  const tx = Math.floor(x), ty = Math.floor(y);
  if (energized.has(tx * TILE_STRIDE + ty)) return true;
  for (const [dx, dy] of POWER_NEIGHBORS) {
    if (energized.has((tx + dx) * TILE_STRIDE + (ty + dy))) return true;
  }
  return false;
}

// ---------------------------------------------------------------------------------------------
// Overload risk (Prison Architect's power-grid overload mechanic). PA lets you wire too many
// powered fixtures onto too few/weak generators; the grid strains and eventually something pops.
// This ports the same idea onto the connected-graph model above: every generator variant
// contributes a fixed capacity to whichever segment (connected component of wire+generator
// tiles) it feeds, every powered consumer draws a fixed load from the segment it's fed by, and a
// segment whose total load exceeds its capacity is "overloaded" -- consumers on it lose the
// powered bonus (soft, always-correct, immediately visible) and, while it stays overloaded, its
// conductor tiles carry a small per-tick chance to catch fire (rare, escalating stakes -- reuses
// fire.js's igniteStructure/tickFire directly rather than a parallel damage system).
//
// Capacities are tiered the same way the real thing is: nuclear and coal are the "big steady
// baseload" sources and get the highest capacity, the plain generator sits in the middle, and
// wind/solar -- both already able to drop to zero output entirely on bad siting (isSource above)
// -- carry the lowest capacity, same intermittent-renewable tradeoff as their real-world
// counterparts, independent of their scrap cost in economy.js.
const GENERATOR_CAPACITY = {
  generator: 5,
  generator_coal: 6,
  generator_nuclear: 14,
  generator_wind: 2.5,
  generator_solar: 2.5,
};

// Load each powered consumer draws once it's actually receiving the powered bonus (siege.js's
// POWERED_DAMAGE_MULT/POWERED_RANGE_MULT, world.js's watchtower warning-window boost). Tesla
// draws more than a plain turret -- it chains to every attacker in range on every activation
// (siege.js's TESLA_RANGE/TESLA_COOLDOWN_TICKS comment), the power-hungry crowd-control pick.
// Anything else that ever starts consuming the powered bonus defaults to a flat 1 rather than
// silently drawing nothing.
const CONSUMER_LOAD = { turret: 1, tesla: 1.5, watchtower: 1 };
const POWERED_CONSUMER_KINDS = new Set(Object.keys(CONSUMER_LOAD));
function consumerLoad(kind) {
  return CONSUMER_LOAD[kind] ?? 1;
}

// Rare, occasional threat, same tuning philosophy as fire.js's own ignition constants (see that
// file's header) -- but rolled per overloaded conductor tile per tick, and deliberately higher
// than a healthy generator's baseline spark chance (fire.js's IGNITION_CHANCE_PER_GENERATOR)
// since overload is itself an avoidable, player-caused condition, not ambient risk.
const OVERLOAD_FIRE_CHANCE_PER_TICK = 0.0004;

function findSegmentIdForConsumer(x, y, segIdOf) {
  const tx = Math.floor(x), ty = Math.floor(y);
  const selfKey = tx * TILE_STRIDE + ty;
  if (segIdOf.has(selfKey)) return segIdOf.get(selfKey);
  for (const [dx, dy] of POWER_NEIGHBORS) {
    const k = (tx + dx) * TILE_STRIDE + (ty + dy);
    if (segIdOf.has(k)) return segIdOf.get(k);
  }
  return null;
}

// Flood-fills the same conductor graph as computeEnergized, but keeps each connected component
// (segment) distinct instead of merging them into one big energized set, and sums the capacity
// of every source-eligible generator each segment actually contains.
function computeSegments(structures) {
  const conductors = new Map(); // tileKey -> structure
  for (const s of structures) {
    if (!isConductor(s, structures)) continue;
    conductors.set(powerTileKey(s.x, s.y), s);
  }

  const segIdOf = new Map(); // tileKey -> segment id
  const segments = []; // { id, capacity, load }
  for (const [startKey] of conductors) {
    if (segIdOf.has(startKey)) continue;
    const id = segments.length;
    let capacity = 0;
    const queue = [startKey];
    segIdOf.set(startKey, id);
    while (queue.length) {
      const k = queue.pop();
      const cs = conductors.get(k);
      if (cs && isSource(cs, structures)) capacity += GENERATOR_CAPACITY[cs.kind] ?? 0;
      const tx = Math.floor(k / TILE_STRIDE);
      const ty = k - tx * TILE_STRIDE;
      for (const [dx, dy] of POWER_NEIGHBORS) {
        const nk = (tx + dx) * TILE_STRIDE + (ty + dy);
        if (!conductors.has(nk) || segIdOf.has(nk)) continue;
        segIdOf.set(nk, id);
        queue.push(nk);
      }
    }
    segments.push({ id, capacity, load: 0 });
  }
  return { segments, segIdOf };
}

// Same cheap-hash-gated caching pattern as energizedTiles above, folded to also change whenever
// a powered-consumer structure (turret/tesla/watchtower) is built, finished, destroyed, or moves
// -- since consumer load, not just the conductor layout, determines overload state.
function overloadSignature(structures) {
  let h = layoutSignature(structures);
  for (const s of structures) {
    if (!POWERED_CONSUMER_KINDS.has(s.kind) || s.destroyed || s.underConstruction) continue;
    h = (Math.imul(h, 31) + powerTileKey(s.x, s.y) + 5) | 0;
  }
  return h;
}

function computeOverloadState(structures) {
  const { segments, segIdOf } = computeSegments(structures);
  const nuclearBuckets = new Map(); // nuclear generator tileKey -> wireless load fed to it
  const nuclearCapacity = GENERATOR_CAPACITY.generator_nuclear;

  for (const s of structures) {
    if (!POWERED_CONSUMER_KINDS.has(s.kind) || s.destroyed || s.underConstruction) continue;
    const load = consumerLoad(s.kind);

    // Nuclear's wireless radius takes precedence, matching isPoweredAt's own precedence above --
    // a consumer inside the radius draws from the reactor directly, not through the wire graph.
    let nuclearGen = null;
    for (const gen of structures) {
      if (gen.kind !== 'generator_nuclear' || gen.destroyed || gen.underConstruction) continue;
      if (Math.hypot(gen.x - s.x, gen.y - s.y) <= NUCLEAR_WIRELESS_RADIUS) { nuclearGen = gen; break; }
    }
    if (nuclearGen) {
      const key = powerTileKey(nuclearGen.x, nuclearGen.y);
      nuclearBuckets.set(key, (nuclearBuckets.get(key) ?? 0) + load);
      continue;
    }

    const segId = findSegmentIdForConsumer(s.x, s.y, segIdOf);
    if (segId != null) segments[segId].load += load;
  }

  return { segments, segIdOf, nuclearBuckets, nuclearCapacity };
}

let _cachedOverloadSignature = null;
let _cachedOverloadState = { segments: [], segIdOf: new Map(), nuclearBuckets: new Map(), nuclearCapacity: GENERATOR_CAPACITY.generator_nuclear };

function overloadState(structures) {
  const sig = overloadSignature(structures);
  if (sig !== _cachedOverloadSignature) {
    _cachedOverloadSignature = sig;
    _cachedOverloadState = computeOverloadState(structures);
  }
  return _cachedOverloadState;
}

// True if the segment (or nuclear wireless bucket) feeding this exact conductor tile (a wire or
// generator, not a consumer) is currently overloaded -- render.js uses this to tint the tile, and
// world.js's fire-risk roll and overload milestone log use it to find which tiles are at risk.
function isSegmentOverloadedAt(structures, x, y) {
  const { segments, segIdOf, nuclearBuckets, nuclearCapacity } = overloadState(structures);
  const key = powerTileKey(x, y);
  const segId = segIdOf.get(key);
  if (segId != null && segments[segId].load > segments[segId].capacity) return true;
  const nuclearLoad = nuclearBuckets.get(key);
  if (nuclearLoad != null && nuclearLoad > nuclearCapacity) return true;
  return false;
}

// True if the consumer at (x, y) is powered AND the specific segment/nuclear-radius feeding it
// isn't overloaded -- this is the gate siege.js's turret/tesla damage-and-range boost and
// world.js's watchtower warning-window boost should check instead of plain isPoweredAt, so the
// bonus silently stops applying (rather than the consumer losing power outright) the moment its
// supply is overloaded.
function hasPoweredBonus(structures, x, y) {
  if (!isPoweredAt(structures, x, y)) return false;
  const { segments, segIdOf, nuclearBuckets, nuclearCapacity } = overloadState(structures);

  let nuclearGen = null;
  for (const gen of structures) {
    if (gen.kind !== 'generator_nuclear' || gen.destroyed || gen.underConstruction) continue;
    if (Math.hypot(gen.x - x, gen.y - y) <= NUCLEAR_WIRELESS_RADIUS) { nuclearGen = gen; break; }
  }
  if (nuclearGen) {
    const load = nuclearBuckets.get(powerTileKey(nuclearGen.x, nuclearGen.y)) ?? 0;
    return load <= nuclearCapacity;
  }

  const segId = findSegmentIdForConsumer(x, y, segIdOf);
  if (segId == null) return true; // touching an energized tile with no tracked segment shouldn't happen, but fail open
  return segments[segId].load <= segments[segId].capacity;
}

// Set of stable string keys identifying every currently-overloaded segment/nuclear-bucket, for
// world.js's tick() to diff tick-over-tick and log a milestone only the first tick a given supply
// actually crosses into overload (not every tick it stays there).
function overloadedSupplyKeys(structures) {
  const { segments, nuclearBuckets, nuclearCapacity } = overloadState(structures);
  const keys = new Set();
  for (const seg of segments) if (seg.load > seg.capacity) keys.add('seg:' + seg.id);
  for (const [k, load] of nuclearBuckets) if (load > nuclearCapacity) keys.add('nuc:' + k);
  return keys;
}


// ---- water.js ----
// Water/plumbing as a real connected pipe graph, mirroring power.js's wire grid exactly (see
// FEATURE_RESEARCH.md: "Power/water as a real wired-graph network" -- power got built first,
// this is the water half). Same PA-derived rule: a pump pushes water out along pipe conduits,
// and anything not physically on the pipe run gets nothing no matter how close it is to the
// pump -- adjacency to the network, not proximity to the source, is what matters.
//
// The graph is a flood-fill over orthogonally-adjacent conductor tiles (pumps + pipes), same
// shape as power.js's energizedTiles/rooms.js's detectRooms, and is recomputed only when the
// conductor layout actually changes -- mirroring power.js's water_layoutSignature check.
const WATER_NEIGHBORS = [[1, 0], [-1, 0], [0, 1], [0, -1]];
const WATER_TILE_STRIDE = 100000; // packs (tx, ty) into one integer key; maps are far smaller than this

function waterTileKey(x, y) {
  return Math.floor(x) * WATER_TILE_STRIDE + Math.floor(y);
}

function water_isSource(s) {
  return s.kind === 'pump';
}

function water_isConductor(s) {
  return (s.kind === 'pipe' || water_isSource(s)) && !s.destroyed && !s.underConstruction;
}

// Cheap order-sensitive hash of every live conductor's tile+kind, so the O(n) rebuild only runs
// when a pipe/pump is built, finished, or destroyed -- not every tick for every zone/consumer.
function water_layoutSignature(structures) {
  let h = 19;
  for (let i = 0; i < structures.length; i++) {
    const s = structures[i];
    if (!water_isConductor(s)) continue;
    h = (Math.imul(h, 31) + waterTileKey(s.x, s.y) + (water_isSource(s) ? 11 : 5)) | 0;
  }
  return h;
}

let _water_cachedSignature = null;
let _cachedWatered = new Set();

function computeWatered(structures) {
  const conductors = new Set();
  const sources = [];
  for (const s of structures) {
    if (!water_isConductor(s)) continue;
    const k = waterTileKey(s.x, s.y);
    conductors.add(k);
    if (water_isSource(s)) sources.push(k);
  }

  const watered = new Set();
  const queue = [];
  for (const k of sources) {
    if (watered.has(k)) continue;
    watered.add(k);
    queue.push(k);
  }
  while (queue.length) {
    const k = queue.pop();
    const tx = Math.floor(k / WATER_TILE_STRIDE);
    const ty = k - tx * WATER_TILE_STRIDE;
    for (const [dx, dy] of WATER_NEIGHBORS) {
      const nk = (tx + dx) * WATER_TILE_STRIDE + (ty + dy);
      if (watered.has(nk) || !conductors.has(nk)) continue;
      watered.add(nk);
      queue.push(nk);
    }
  }
  return watered;
}

// Set of tile keys actually carrying water right now: every pump, plus every pipe with an
// unbroken pipe path back to one. Cut the chain and the far half runs dry.
function wateredTiles(structures) {
  const sig = water_layoutSignature(structures);
  if (sig !== _water_cachedSignature) {
    _water_cachedSignature = sig;
    _cachedWatered = computeWatered(structures);
  }
  return _cachedWatered;
}

// True if this tile is itself watered (i.e. it holds a live pipe/pump).
function isTileWatered(structures, x, y) {
  return wateredTiles(structures).has(waterTileKey(x, y));
}

// A consumer is watered if it sits on, or orthogonally touches, a watered tile -- so a Food/
// Recreation zone tile or the Recycling Center can either hug the pump directly or be fed by a
// pipe run from across the map. No wireless-radius exception here (unlike power.js's nuclear
// generator) -- water has no equivalent "riskier source, bigger payoff" building yet.
function isWateredAt(structures, x, y) {
  const watered = wateredTiles(structures);
  if (watered.size === 0) return false;
  const tx = Math.floor(x), ty = Math.floor(y);
  if (watered.has(tx * WATER_TILE_STRIDE + ty)) return true;
  for (const [dx, dy] of WATER_NEIGHBORS) {
    if (watered.has((tx + dx) * WATER_TILE_STRIDE + (ty + dy))) return true;
  }
  return false;
}


// ---- citizens.js ----
// Ported/condensed from SD.Sim (CitizenStore, NeedsDecaySystem, NeedsMoodBreakTickGroup,
// SocialInteractionSystem). Struct-of-arrays store, same shape as the C# CitizenStore.



const CitizenFlags = Object.freeze({
  None: 0,
  Dead: 1 << 0,
  OnBreak: 1 << 1,
  Downed: 1 << 2, // incapacitated but alive (RimWorld-style) -- see siege.js for the transition rules
});

const DOWNED_RECOVERY_RATE = 0.0015; // per tick, passive -- no dedicated first-aid job yet
const DOWNED_RECOVER_THRESHOLD = 0.3;

// Exported so weather.js can scale its extra Cold/Heatwave decay proportionally to these base
// rates rather than hardcoding a second copy of the numbers.
const HUNGER_DECAY = 0.0005;   // per tick (10 Hz), matches ARCHITECTURE.md "100ms/tick"
const REST_DECAY = 0.0003;
const SOCIAL_DECAY = 0.0002;
const ON_DUTY_SOCIAL_FULFILLMENT = 0.6; // guards/snipers get partial social fulfillment on duty
const BREAK_MOOD_THRESHOLD = 0.12;

// Room quality -> mood (rooms.js's computeRoomStats, RimWorld-style beauty/cleanliness/
// impressiveness -> a 0..1 "quality" score). 0.5 is the neutral "no room / average room"
// baseline, so this term is signed: a genuinely nice room (quality near 1) gives a steady small
// positive nudge each tick, a bare/ugly one (quality near 0) gives a steady small negative nudge.
// Kept deliberately gentle -- this should read as a slow trend over many ticks in a soak test,
// not something that swamps the existing hunger/rest/social-driven mood swing in one tick.
const ROOM_MOOD_INFLUENCE = 0.02;

class CitizenStore {
  constructor(capacity) {
    this.capacity = capacity;
    this.count = 0;
    this.id = new Uint32Array(capacity);
    this.name = new Array(capacity).fill('');
    this.x = new Float32Array(capacity);
    this.y = new Float32Array(capacity);
    this.targetX = new Float32Array(capacity);
    this.targetY = new Float32Array(capacity);
    this.hunger = new Float32Array(capacity).fill(1);
    this.rest = new Float32Array(capacity).fill(1);
    this.social = new Float32Array(capacity).fill(1);
    this.mood = new Float32Array(capacity).fill(1);
    this.health = new Float32Array(capacity).fill(1);
    this.flags = new Uint8Array(capacity);
    this.alive = new Uint8Array(capacity);
    this.jobState = new Uint8Array(capacity); // JobState from jobs.js
    this.skillCombat = new Float32Array(capacity);
    this.skillConstruction = new Float32Array(capacity);
    this._staffCooldown = new Float32Array(capacity); // used by siege.js tickStaffCombat
    this._jobRef = {}; // used by jobs.js: index -> blueprint/resource-node object currently targeted
    this.trait = new Array(capacity).fill(null);
    this.backstory = new Array(capacity).fill(null); // see backstories.js -- childhood/adult flavor pair + skill nudge
    this.passionCombat = new Uint8Array(capacity); // Passion tier (backstories.js), biases skillCombat gain rate
    this.passionConstruction = new Uint8Array(capacity); // Passion tier, biases skillConstruction gain rate

    // Work Priorities (RimWorld Work-tab-style, see jobs.js's WorkCategory/tickJobs). All four
    // default to 0 (Uint8Array zero-init), but 0 in workPriority* means "disabled" while 0 in
    // hasWorkPriorities means "no override at all" -- those are deliberately different questions,
    // so hasWorkPriorities gates whether the workPriority* arrays are consulted. A citizen nobody
    // has ever opened the Work Priorities panel for has hasWorkPriorities[i] === 0 and jobs.js's
    // Idle branch runs its original fixed-order ladder for them, completely untouched. Only once
    // a citizen has been customized (see main.js's Work Priorities panel) does hasWorkPriorities
    // flip to 1 and these four arrays start mattering: each cell is 0 (never do this job) or a
    // 1-3 priority tier, lower number = higher priority (RimWorld's inverted-number convention).
    this.hasWorkPriorities = new Uint8Array(capacity);
    this.workPriorityConstruction = new Uint8Array(capacity); // JobState SeekingBuild/Building
    this.workPriorityHauling = new Uint8Array(capacity); // JobState SeekingVehicle/Driving
    this.workPriorityHarvesting = new Uint8Array(capacity); // JobState SeekingScrap/Harvesting
    this.workPriorityAnimal = new Uint8Array(capacity); // JobState SeekingAnimal/Taming

    this._nextId = 1;
  }

  spawn(name, x, y, rng = Math.random) {
    if (this.count >= this.capacity) return -1;
    const i = this.count++;
    const id = this._nextId++;
    this.id[i] = id;
    this.name[i] = name;
    this.x[i] = x; this.y[i] = y;
    this.targetX[i] = x; this.targetY[i] = y;
    this.hunger[i] = 1; this.rest[i] = 1; this.social[i] = 1; this.mood[i] = 1; this.health[i] = 1;
    this.flags[i] = CitizenFlags.None;
    this.alive[i] = 1;
    this.trait[i] = randomTrait(rng);
    const backstory = randomBackstory(rng);
    this.backstory[i] = backstory;
    this.skillCombat[i] = backstory.skillCombatStart ?? 0;
    this.skillConstruction[i] = backstory.skillConstructionStart ?? 0;
    const passions = randomPassions(rng, backstory);
    this.passionCombat[i] = passions.combat;
    this.passionConstruction[i] = passions.construction;
    // Equal-tier defaults so that if the Work Priorities panel ever flips hasWorkPriorities on
    // without the player touching every cell, the untouched cells tie-break in jobs.js's fixed
    // array order (Construction, Hauling, Harvesting, Animal) -- the same order the legacy ladder
    // already uses, so "just enabled overrides, changed nothing yet" reads as unchanged behavior.
    this.hasWorkPriorities[i] = 0;
    this.workPriorityConstruction[i] = 1;
    this.workPriorityHauling[i] = 1;
    this.workPriorityHarvesting[i] = 1;
    this.workPriorityAnimal[i] = 1;
    return i;
  }

  isAliveAt(i) {
    return this.alive[i] === 1 && (this.flags[i] & CitizenFlags.Dead) === 0;
  }

  isDownedAt(i) {
    return (this.flags[i] & CitizenFlags.Downed) !== 0;
  }

  isOnBreakAt(i) {
    return (this.flags[i] & CitizenFlags.OnBreak) !== 0;
  }
}

// isStaffAt(i) -> bool, used to decide on-duty social fulfillment (guards/snipers don't
// need to be near others to stay socially fulfilled while working).
// world (optional, 5th arg) -- passed by world.js as `this` so a citizen's current room quality
// (rooms.js's roomContaining + computeRoomStats) can nudge their mood; omit it (e.g. in tests)
// and this term is simply skipped, matching the rest of this function's null-safe style.
function tickNeedsAndMood(store, isStaffAt, rng, world) {
  for (let i = 0; i < store.count; i++) {
    if (!store.isAliveAt(i)) continue;

    if (store.isDownedAt(i)) {
      // Incapacitated: needs don't spiral further while down, but health slowly recovers
      // (RimWorld-style "downed, not dead" reprieve -- no dedicated first-aid job yet, so
      // recovery is passive rather than requiring a medic to tend them).
      store.health[i] = Math.min(1, store.health[i] + DOWNED_RECOVERY_RATE);
      if (store.health[i] >= DOWNED_RECOVER_THRESHOLD) store.flags[i] &= ~CitizenFlags.Downed;
      continue;
    }

    const staffFulfillment = isStaffAt(i) ? ON_DUTY_SOCIAL_FULFILLMENT : 0;
    const trait = store.trait[i];

    store.hunger[i] = Math.max(0, store.hunger[i] - HUNGER_DECAY * (trait?.hungerMult ?? 1));
    store.rest[i] = Math.max(0, store.rest[i] - REST_DECAY * (trait?.restMult ?? 1));
    store.social[i] = Math.max(0, store.social[i] - SOCIAL_DECAY * (1 - staffFulfillment));

    const avgNeed = (store.hunger[i] + store.rest[i] + store.social[i]) / 3;
    // Mood eases toward the current need average rather than snapping, so a single bad tick
    // doesn't cause a break.
    store.mood[i] += (avgNeed - store.mood[i]) * 0.05;

    // Room quality (see ROOM_MOOD_INFLUENCE doc comment above): one roomContaining lookup per
    // citizen per tick, same cost/pattern as the ROOM_REFILL_BONUS lookups already done per
    // citizen per tick in jobs.js's Eating/Sleeping/Recreating states.
    if (world) {
      const room = roomContaining(world.rooms, world.grid, store.x[i], store.y[i]);
      if (room) store.mood[i] += (room.quality - 0.5) * ROOM_MOOD_INFLUENCE;
    }
    store.mood[i] = Math.min(1, Math.max(0, store.mood[i]));

    if (store.mood[i] < BREAK_MOOD_THRESHOLD) {
      store.flags[i] |= CitizenFlags.OnBreak;
    } else if (store.mood[i] > BREAK_MOOD_THRESHOLD + 0.1) {
      store.flags[i] &= ~CitizenFlags.OnBreak;
    }
  }
}

// Simple wander: citizens not on a job walk toward a random nearby point, matching the
// "idle wander" behavior visible in the Unity build's default scenario (no job system ported
// yet — this is deliberately simpler than SD.Sim's real Eat/Sleep job execution).
function tickWander(store, grid, rng, speed = 0.04, skipIf = null) {
  for (let i = 0; i < store.count; i++) {
    if (!store.isAliveAt(i)) continue;
    if (store.isDownedAt(i)) continue;
    if (skipIf && skipIf(i)) continue;

    const dx = store.targetX[i] - store.x[i];
    const dy = store.targetY[i] - store.y[i];
    const dist = Math.hypot(dx, dy);
    if (dist < 0.15) {
      let tx, ty, tries = 0;
      do {
        tx = Math.max(1, Math.min(grid.width - 2, store.x[i] + (rng() - 0.5) * 10));
        ty = Math.max(1, Math.min(grid.height - 2, store.y[i] + (rng() - 0.5) * 10));
        tries++;
      } while (grid.isBlocked(tx | 0, ty | 0) && tries < 8);
      store.targetX[i] = tx;
      store.targetY[i] = ty;
    } else {
      store.x[i] += (dx / dist) * speed;
      store.y[i] += (dy / dist) * speed;
    }
  }
}


// ---- security.js ----
// Ported/condensed from SD.Security (StaffRoster, guard/sniper/K9 AI + alert-level FSM).
// StaffRoleKind.Monitor (added for the CCTV feature, see world.js's wave-warning logic and
// FEATURE_RESEARCH.md's Prison Architect section) reuses this same roster/post plumbing --
// tickStaffDuty below already walks any assigned staff to their post regardless of role, so a
// Monitor just needs an assign(citizenId, StaffRoleKind.Monitor, {x, y}) at a Monitor Station's
// location; no combat behavior of its own, it's read passively by world.js's staffed-check.

// Damage-type plumbing lives in siege.js; K9 bites are Kinetic like a guard sidearm, so dogs are
// good at running down Skirmishers and poor at chewing through a Brute's plate.



const AlertLevel = Object.freeze({
  Calm: 0,
  Alert: 1,
  Combat: 2,
});

// Armory weapon tiers (FEATURE_RESEARCH.md's Prison Architect section): a civilian defense
// force issuing weapons from an armory needs no reframing at all, it's already the game's
// premise. Each tier is a multiplier on a role's baseline GUARD_*/SNIPER_* stats (siege.js) --
// Sidearm is exactly that baseline (1x everywhere), so a roster with no Armory built plays
// identically to the old flat-constant behavior. Rifle and Heavy are real tradeoffs, not strict
// upgrades: more damage costs range and/or cooldown, matching the turret/tesla and dog/guard
// tradeoff framing already used elsewhere in siege.js.
const WeaponTier = Object.freeze({
  Sidearm: 'Sidearm',
  Rifle: 'Rifle',
  Heavy: 'Heavy',
});

const WEAPON_TIERS = Object.freeze({
  [WeaponTier.Sidearm]: Object.freeze({ label: 'Sidearm', damageMult: 1,    rangeMult: 1,    cooldownMult: 1 }),
  [WeaponTier.Rifle]:   Object.freeze({ label: 'Rifle',   damageMult: 1.6,  rangeMult: 1.15, cooldownMult: 1.15 }),
  [WeaponTier.Heavy]:   Object.freeze({ label: 'Heavy',   damageMult: 2.4,  rangeMult: 0.8,  cooldownMult: 1.75 }),
});

// Weakest -> strongest; how far up this list a guard/sniper can be issued is gated by how many
// Armories the settlement has actually built (see tickArmoryIssuance).
const WEAPON_TIER_ORDER = [WeaponTier.Sidearm, WeaponTier.Rifle, WeaponTier.Heavy];

// Patrol routes + staff fatigue (FEATURE_RESEARCH.md's Prison Architect section): `post` may be
// a single {x, y} (static hold-position, unchanged behavior / old save-file shape) or an ordered
// array of 2-4 waypoints a guard/sniper/monitor cycles through, pausing briefly at each -- see
// tickStaffDuty. Staff also carry a real off-duty cycle: tickStaffOffDuty below flips
// roster.isOffDuty when a staff member's hunger/rest (same CitizenStore fields every citizen
// has) crosses a threshold, at which point tickStaffDuty stops walking them and jobs.js's normal
// Eat/Sleep job states take over for them, same as any off-shift citizen, until they recover.
const PATROL_PAUSE_TICKS = 15; // dwell at each waypoint so a patrol reads as a beat, not a jitter
const OFFDUTY_REST_THRESHOLD = 0.35; // fatigue this low sends staff off duty to recover
const OFFDUTY_HUNGER_THRESHOLD = 0.35;

class StaffRoster {
  constructor() {
    this._roleById = new Map(); // citizenId -> StaffRoleKind
    this._postById = new Map(); // citizenId -> array of 1-4 {x, y} waypoints (1 = static post)
    this._weaponById = new Map(); // citizenId -> WeaponTier, see tickArmoryIssuance
    this._patrolIndexById = new Map(); // citizenId -> index of the waypoint currently being walked to
    this._patrolPauseById = new Map(); // citizenId -> ticks spent paused at the current waypoint
    this._offDutyById = new Set(); // citizenId currently clocked off, recovering hunger/rest like a normal citizen
  }

  // post may be a single {x, y} (backward compat / old save shape) or an array of 2-4 {x, y}
  // points defining a patrol loop.
  assign(citizenId, kind, post) {
    this._roleById.set(citizenId, kind);
    if (post) {
      this._postById.set(citizenId, Array.isArray(post) ? post : [post]);
      this._patrolIndexById.set(citizenId, 0);
      this._patrolPauseById.set(citizenId, 0);
    }
  }

  isStaff(citizenId) {
    return this._roleById.has(citizenId);
  }

  kindOf(citizenId) {
    return this._roleById.get(citizenId) || StaffRoleKind.None;
  }

  // Full waypoint list assigned to this staff member (length 1 for a static post), or undefined.
  postOf(citizenId) {
    return this._postById.get(citizenId);
  }

  // The single waypoint tickStaffDuty is walking this staff member toward right now.
  currentWaypoint(citizenId) {
    const points = this._postById.get(citizenId);
    if (!points || points.length === 0) return null;
    const idx = this._patrolIndexById.get(citizenId) || 0;
    return points[idx % points.length];
  }

  advancePatrol(citizenId) {
    const points = this._postById.get(citizenId);
    if (!points || points.length <= 1) return; // static post, nothing to cycle
    const idx = (this._patrolIndexById.get(citizenId) || 0) + 1;
    this._patrolIndexById.set(citizenId, idx % points.length);
  }

  isOffDuty(citizenId) {
    return this._offDutyById.has(citizenId);
  }

  setOffDuty(citizenId, offDuty) {
    if (offDuty) this._offDutyById.add(citizenId);
    else this._offDutyById.delete(citizenId);
  }

  // Sidearm is the implicit default for any Guard/Sniper who hasn't been issued anything yet
  // (or ever will be, if no Armory gets built) -- never null, so siege.js's tickStaffCombat
  // always has real tier stats to read.
  weaponOf(citizenId) {
    return this._weaponById.get(citizenId) || WeaponTier.Sidearm;
  }

  equip(citizenId, tier) {
    this._weaponById.set(citizenId, tier);
  }
}

// Armory issuance (scoped version per FEATURE_RESEARCH.md: no per-citizen pick-a-tier UI --
// simply, once assigned to Guard/Sniper AND an Armory exists, they're equipped with whatever
// tier the settlement's Armory count supports). Every built (not destroyed/under-construction)
// Armory unlocks one more rung of WEAPON_TIER_ORDER, so a second Armory is a real strategic
// payoff, not just a cosmetic duplicate. Runs every tick (world.js) so a freshly-assigned guard
// or a freshly-completed Armory both propagate immediately, and a destroyed Armory correctly
// downgrades everyone back rather than leaving them permanently over-equipped.
function tickArmoryIssuance(roster, structures) {
  let armoryCount = 0;
  for (const s of structures) {
    if (s.kind === 'armory' && !s.destroyed && !s.underConstruction) armoryCount++;
  }
  const tierIndex = Math.min(WEAPON_TIER_ORDER.length - 1, armoryCount);
  const tier = WEAPON_TIER_ORDER[tierIndex];
  for (const [citizenId, kind] of roster._roleById.entries()) {
    if (kind !== StaffRoleKind.Guard && kind !== StaffRoleKind.Sniper) continue;
    roster.equip(citizenId, tier);
  }
}

// Guards/snipers/monitors walk their assigned route -- a single point holds position (matches
// the Unity build's "hold position" staff behavior); 2-4 points cycle as a patrol loop, pausing
// PATROL_PAUSE_TICKS at each stop before moving to the next. Off-duty staff (see
// tickStaffOffDuty) are skipped entirely -- jobs.js drives their Eat/Sleep trip that tick
// instead. Everyone else uses the general wander tick.
function tickStaffDuty(store, roster, idOf, speed = 0.05) {
  for (let i = 0; i < store.count; i++) {
    if (!store.isAliveAt(i)) continue;
    if (store.isDownedAt(i)) continue; // downed staff can't hold their post
    const id = idOf(i);
    if (!roster.isStaff(id)) continue;
    if (roster.isOffDuty(id)) continue; // clocked off recovering a need -- see tickStaffOffDuty

    const waypoint = roster.currentWaypoint(id);
    if (!waypoint) continue;

    const dx = waypoint.x - store.x[i];
    const dy = waypoint.y - store.y[i];
    const dist = Math.hypot(dx, dy);
    if (dist > 0.1) {
      store.x[i] += (dx / dist) * speed;
      store.y[i] += (dy / dist) * speed;
      roster._patrolPauseById.set(id, 0);
    } else {
      const pause = (roster._patrolPauseById.get(id) || 0) + 1;
      if (pause >= PATROL_PAUSE_TICKS) {
        roster.advancePatrol(id);
        roster._patrolPauseById.set(id, 0);
      } else {
        roster._patrolPauseById.set(id, pause);
      }
    }
    store.targetX[i] = store.x[i];
    store.targetY[i] = store.y[i];
  }
}

// Staff fatigue: guards/snipers/monitors carry the same hunger/rest fields as any citizen (see
// citizens.js tickNeedsAndMood, which decays them for staff same as everyone), but previously had
// no way to actually respond to it -- jobs.js's tickJobs unconditionally skips anyone
// roster.isStaff() covers, so staff would silently decay to 0 forever with zero recovery and zero
// gameplay consequence. This flips roster's off-duty flag when fatigue/hunger crosses a
// threshold and dispatches them straight to the nearest Food/Bedroom zone itself (see below);
// while off duty, world.js's staffOnDuty callback reports them as NOT on duty, so jobs.js's normal
// SeekingFood/Eating/SeekingBed/Sleeping state machine carries out that trip for them exactly
// like any citizen's, and tickStaffDuty (above) leaves them alone instead of walking them back to
// post.
//
// Dispatch is done directly here rather than just flipping the flag and letting jobs.js's own
// Idle branch notice the low need on its own: that branch's thresholds are deliberately narrowed
// during the Work schedule block (see jobs.js SCHEDULE_WORK_THRESHOLD_MULT) so a citizen mid-task
// doesn't break off for anything short of near-critical -- sensible for someone protecting an
// in-progress build/harvest job, but a guard/sniper has no such job to protect, just a post to
// leave, so that narrowing should never apply to them. Left to the generic Idle branch, an
// off-duty guard whose needs dipped moderately (not narrow-threshold-critical) would fall through
// past the food/bed checks entirely and pick up a blueprint/harvest job instead, wandering off
// indefinitely rather than taking the short break this feature intends -- caught in soak testing
// before this was changed to a direct dispatch.
// Sends citizen index i directly into jobs.js's SeekingFood/SeekingBed travel state, bypassing
// the Idle branch's own (schedule-narrowed) threshold checks entirely -- see the doc comment
// above. Returns false (and leaves the roster on-duty flag alone for the caller to reconsider) if
// no matching zone exists to send them to, so an off-duty citizen can't get stuck forever with
// nowhere to go.
function dispatchStaffToNeed(store, i, zones, wantFood) {
  const zone = zones.nearestOfKind(wantFood ? ZoneKind.Food : ZoneKind.Bedroom, store.x[i], store.y[i]);
  if (!zone) return false;
  store.jobState[i] = wantFood ? JobState.SeekingFood : JobState.SeekingBed;
  store.targetX[i] = zone.x; store.targetY[i] = zone.y;
  return true;
}

function tickStaffOffDuty(store, roster, idOf, zones) {
  for (let i = 0; i < store.count; i++) {
    if (!store.isAliveAt(i)) continue;
    if (store.isDownedAt(i)) continue;
    const id = idOf(i);
    if (!roster.isStaff(id)) continue;

    const needsFood = store.hunger[i] < OFFDUTY_HUNGER_THRESHOLD;
    const needsRest = store.rest[i] < OFFDUTY_REST_THRESHOLD;

    if (!roster.isOffDuty(id)) {
      if (needsFood || needsRest) {
        roster.setOffDuty(id, true);
        // Whichever need is more urgent (lower current value) wins the first trip; the other
        // gets a second trip below once the first one completes, if it's still low by then.
        const wantFood = needsFood && (!needsRest || store.hunger[i] <= store.rest[i]);
        if (!dispatchStaffToNeed(store, i, zones, wantFood)) roster.setOffDuty(id, false);
      }
    } else if (store.jobState[i] === JobState.Idle) {
      // jobs.js's Eating/Sleeping loop ran the trip we dispatched to completion -- if the other
      // need is also still low, send a second trip before fully resuming, same as a citizen
      // handling one need at a time; otherwise, back to post/patrol.
      if (needsFood) { if (!dispatchStaffToNeed(store, i, zones, true)) roster.setOffDuty(id, false); }
      else if (needsRest) { if (!dispatchStaffToNeed(store, i, zones, false)) roster.setOffDuty(id, false); }
      else roster.setOffDuty(id, false);
    }
  }
}

// Guard/sniper engagement range in grid cells, and simple alert-level derivation from
// visible attacker count (Calm -> Alert -> Combat), matching the FSM's broad shape.
function deriveAlertLevel(attackerAliveCount) {
  if (attackerAliveCount === 0) return AlertLevel.Calm;
  return AlertLevel.Combat;
}

const DOG_RANGE = 2.5; const DOG_DAMAGE = 0.08; const DOG_COOLDOWN = 3; const DOG_SPEED = 0.07;

// K9 units: each dog follows its handler loosely and bites the nearest attacker in range,
// fast and cheap per-hit compared to a guard's sidearm -- matches the GDD's non-carceral
// civil-protection-force framing ("guards/snipers/K9/CCTV", never inmates).
function tickDogs(dogs, citizens, roster, attackers, onScrap) {
  for (const dog of dogs) {
    const ownerIdx = findCitizenIndexById(citizens, dog.ownerId);
    if (ownerIdx < 0 || !citizens.isAliveAt(ownerIdx)) continue;

    const dx = citizens.x[ownerIdx] - dog.x;
    const dy = citizens.y[ownerIdx] - dog.y;
    const dist = Math.hypot(dx, dy);
    if (dist > 1.2) {
      dog.x += (dx / dist) * DOG_SPEED;
      dog.y += (dy / dist) * DOG_SPEED;
    }

    if (dog.cooldown > 0) { dog.cooldown--; continue; }
    let bestI = -1, bestDist = DOG_RANGE;
    for (let i = 0; i < attackers.count; i++) {
      if (!attackers.isAliveAt(i)) continue;
      const d = Math.hypot(attackers.x[i] - dog.x, attackers.y[i] - dog.y);
      if (d < bestDist) { bestDist = d; bestI = i; }
    }
    if (bestI >= 0) {
      dog.cooldown = DOG_COOLDOWN;
      if (damageAttacker(attackers, bestI, DOG_DAMAGE, DamageType.Kinetic)) onScrap?.(4);
    }
  }
}

function findCitizenIndexById(citizens, id) {
  for (let i = 0; i < citizens.count; i++) if (citizens.id[i] === id) return i;
  return -1;
}

// Wires a tamed/bred dog (already in world.dogs) to a citizen the same way the starting dog is
// wired in world.js's constructor -- both the roster assignment (so tickStaffDuty/UI treat them
// as K9Handler and walk them to a post) and the dog's own ownerId (so tickDogs above knows who
// to follow) are needed; the roster system itself needs no changes to support a second dog.
function assignDogHandler(roster, dog, citizenId, post) {
  roster.assign(citizenId, StaffRoleKind.K9Handler, post);
  dog.ownerId = citizenId;
}

// --- RimWorld-style taming/breeding (see FEATURE_RESEARCH.md's Animals section) ---
// A wild animal shares the dog's {x,y} shape but stays outside world.dogs (and outside the K9
// roster/combat loop entirely) until jobs.js's Taming job succeeds -- kept as a distinct array
// rather than a `tamed: false` flag on world.dogs, since dogs is specifically the
// roster-assignable/combat-ticked collection and a wild animal is neither of those things yet.
const WILD_ANIMAL_SPAWN_INTERVAL = 500; // ticks between spawn rolls -- cadence mirrors resources.js's maybeSpawnNode
const MAX_WILD_ANIMALS = 3; // concurrent untamed animals on the map at once
const WILD_ANIMAL_SPEED = 0.03;

function maybeSpawnWildAnimal(wildAnimals, grid, rng, currentTick, avoidX, avoidY) {
  if (currentTick % WILD_ANIMAL_SPAWN_INTERVAL !== 0) return;
  if (wildAnimals.length >= MAX_WILD_ANIMALS) return;
  let tries = 0;
  while (tries < 30) {
    tries++;
    const x = Math.floor(rng() * grid.width);
    const y = Math.floor(rng() * grid.height);
    if (Math.hypot(x - avoidX, y - avoidY) < 8) continue;
    if (grid.isBlocked(x, y)) continue;
    wildAnimals.push({ x: x + 0.5, y: y + 0.5, targetX: x + 0.5, targetY: y + 0.5, claimedBy: null, tameTicks: 0 });
    return;
  }
}

// Wild animals wander like an idle citizen (see citizens.js tickWander) but freeze in place while
// a citizen is actively taming them (claimedBy set) -- otherwise jobs.js's Taming job could never
// get a stable "arrived" check, since the target would keep drifting mid-approach.
function tickWildAnimals(wildAnimals, grid, rng, speed = WILD_ANIMAL_SPEED) {
  for (const animal of wildAnimals) {
    if (animal.claimedBy != null) continue;
    const dx = animal.targetX - animal.x;
    const dy = animal.targetY - animal.y;
    const dist = Math.hypot(dx, dy);
    if (dist < 0.15) {
      let tx, ty, tries = 0;
      do {
        tx = Math.max(1, Math.min(grid.width - 2, animal.x + (rng() - 0.5) * 6));
        ty = Math.max(1, Math.min(grid.height - 2, animal.y + (rng() - 0.5) * 6));
        tries++;
      } while (grid.isBlocked(tx | 0, ty | 0) && tries < 8);
      animal.targetX = tx; animal.targetY = ty;
    } else {
      animal.x += (dx / dist) * speed;
      animal.y += (dy / dist) * speed;
    }
  }
}

// Flat per-tick taming chance -- no dedicated "Animals" skill exists yet (FEATURE_RESEARCH.md
// explicitly says not to add one just for this), so this is the "just a flat rate" option it
// calls out as acceptable. TAME_MAX_TICKS bounds how long a citizen will stick with a no-luck
// animal before it flees, so a job can't get permanently stuck.
const TAME_CHANCE_PER_TICK = 0.004;
const TAME_MAX_TICKS = 400;

// Bounds total world.dogs population so neither breeding nor ongoing taming can spiral --
// jobs.js's Taming success check reads this too (not just tickDogBreeding below), since a long
// soak session can otherwise keep taming freshly-spawned wild animals past any breeding-only cap.
const DOG_POPULATION_CAP = 8;
const BREED_CHECK_INTERVAL = 300;
const BREED_CHANCE = 0.12;

// Two tamed animals occasionally produce a pup, no citizen action required beyond having tamed
// the initial pair -- deliberately simple (flat chance-per-check against a hard population cap)
// rather than a full needs/pregnancy model, matching the scope the task called for.
function tickDogBreeding(dogs, rng, currentTick) {
  if (currentTick % BREED_CHECK_INTERVAL !== 0) return;
  if (dogs.length < 2 || dogs.length >= DOG_POPULATION_CAP) return;
  if (rng() >= BREED_CHANCE) return;
  const aIdx = rngInt(rng, 0, dogs.length);
  let bIdx = rngInt(rng, 0, dogs.length);
  let tries = 0;
  while (bIdx === aIdx && tries < 5) { bIdx = rngInt(rng, 0, dogs.length); tries++; }
  const a = dogs[aIdx], b = dogs[bIdx];
  dogs.push({ ownerId: null, x: (a.x + b.x) / 2, y: (a.y + b.y) / 2, cooldown: 0 });
}


// ---- siege.js ----
// Ported/condensed from SD.Siege (wave spawner, AttackerStore, turret/fence/trap placement +
// combat resolution, scrap rewards).





// ---------------------------------------------------------------- enemy archetypes
// RimWorld/SEA:R-style raider roster: every attacker used to be identical except for a flat
// health multiplier scaled by wave number, so no defense layout was ever better or worse than
// another. Four archetypes with genuinely different stat shapes give waves texture and make the
// damage-type table below actually matter.
const AttackerKind = Object.freeze({
  Grunt: 0,
  Brute: 1,
  Skirmisher: 2,
  Boss: 3,
});

// healthMult/speedMult/damageMult multiply the baseline constants further down this file.
// contactRange: a Boss reaches further than everyone else, which (because tickAttackerVsCitizens
// damages EVERY citizen inside contact range) reads as a cleaving area attack rather than the
// single-target poke a Grunt makes -- that's the Boss's "unique attack".
//
// BALANCE-CRITICAL, soak-tested. A first pass at (Brute 2.6hp/0.5-kinetic, Boss 9.0hp, 12% boss
// roll) dropped hands-off survival ~28% below the same-build baseline and put a Boss in over half
// of all waves. These numbers were swept until three-seed mean survival matched the pre-archetype
// baseline of the same build almost exactly (21.0k vs 21.0k ticks). Retune only against a fresh
// A/B soak -- the effective toughness of a Brute is healthMult x its kinetic RESISTANCE below,
// not healthMult alone, so the two tables have to move together.
const ATTACKER_ARCHETYPES = Object.freeze([
  { name: 'Grunt',      healthMult: 1.0,  speedMult: 1.0, damageMult: 1.0, contactRange: 0.5 },
  { name: 'Brute',      healthMult: 1.8,  speedMult: 0.5, damageMult: 1.4, contactRange: 0.6 },
  { name: 'Skirmisher', healthMult: 0.45, speedMult: 1.9, damageMult: 0.7, contactRange: 0.5 },
  { name: 'Boss',       healthMult: 5.0,  speedMult: 0.7, damageMult: 2.2, contactRange: 1.3 },
]);

function archetypeOf(kind) {
  return ATTACKER_ARCHETYPES[kind] || ATTACKER_ARCHETYPES[AttackerKind.Grunt];
}

// ---------------------------------------------------------------- weapon / armor damage types
// RimWorld's weapon-vs-armor system, condensed to three legible types instead of RimWorld's full
// sharp/blunt/heat matrix. The point is a real rock-paper-scissors, not flat multipliers on
// everything: exactly one archetype is the intended answer for each damage type, and the Grunt is
// a deliberate all-1.0 baseline so the table stays readable.
//
//   Kinetic   -- turrets, guard sidearms, K9 bites (the bread-and-butter defense)
//   Explosive -- traps (one-shot burst placements)
//   Energy    -- tesla coils, sniper rifles (expensive/slow, but shreds heavy armor)
const DamageType = Object.freeze({
  Kinetic: 0,
  Explosive: 1,
  Energy: 2,
});

// [kind][damageType] -> incoming-damage multiplier. >1 = vulnerable, <1 = resistant.
// Brute: heavy plate shrugs off bullets, but it's slow and can't avoid a mine -> bring traps.
// Skirmisher: no armor at all so bullets tear it up, but it's fast enough to run out of blasts.
// Boss: the armor answer is energy weapons (tesla/snipers), not more turrets.
const RESISTANCE = Object.freeze([
  /* Grunt      */ Object.freeze([1.0,  1.0,  1.0]),
  /* Brute      */ Object.freeze([0.65, 1.75, 1.0]),
  /* Skirmisher */ Object.freeze([1.35, 0.6,  1.0]),
  /* Boss       */ Object.freeze([0.7,  0.9,  1.5]),
]);

function resistanceMult(kind, damageType) {
  const row = RESISTANCE[kind] || RESISTANCE[AttackerKind.Grunt];
  const m = row[damageType];
  return m === undefined ? 1 : m;
}

class AttackerStore {
  constructor(capacity) {
    this.capacity = capacity;
    this.count = 0;
    this.x = new Float32Array(capacity);
    this.y = new Float32Array(capacity);
    this.health = new Float32Array(capacity);
    this.alive = new Uint8Array(capacity);
    this.kind = new Uint8Array(capacity); // AttackerKind enum, same SoA style as the rest
  }

  // `health` is the wave-scaled base health; the archetype's own healthMult is applied here so
  // callers (WaveSpawner, tests, console pokes) never have to remember to do it themselves.
  spawn(x, y, health = 1, kind = AttackerKind.Grunt) {
    const hp = health * archetypeOf(kind).healthMult;
    if (this.count >= this.capacity) {
      // recycle a dead slot rather than growing, matches the fixed-capacity C# store
      for (let i = 0; i < this.count; i++) {
        if (!this.alive[i]) {
          this.x[i] = x; this.y[i] = y; this.health[i] = hp; this.alive[i] = 1; this.kind[i] = kind;
          return i;
        }
      }
      return -1;
    }
    const i = this.count++;
    this.x[i] = x; this.y[i] = y; this.health[i] = hp; this.alive[i] = 1; this.kind[i] = kind;
    return i;
  }

  isAliveAt(i) {
    return this.alive[i] === 1;
  }

  archetypeAt(i) {
    return archetypeOf(this.kind[i]);
  }
}

// Single choke point for every "something hurt an attacker" site in the codebase, so the
// resistance lookup can never be forgotten at one of them. Returns true if this hit killed.
function damageAttacker(attackers, i, amount, damageType = DamageType.Kinetic) {
  if (!attackers.isAliveAt(i)) return false;
  attackers.health[i] -= amount * resistanceMult(attackers.kind[i], damageType);
  if (attackers.health[i] <= 0) {
    attackers.alive[i] = 0;
    return true;
  }
  return false;
}

class Structure {
  constructor(kind, x, y, opts = {}) {
    this.kind = kind; // 'turret' | 'fence' | 'trap' | 'bed' | 'table' | 'door' | 'generator' | 'wire' | 'wall' |
                      // 'generator_nuclear' | 'waste_storage' | 'generator_coal' | 'generator_wind' |
                      // 'generator_solar' (SEA:R multi-source power economy, see power.js's isSource)
    this.x = x; this.y = y;
    this.health = kind === 'fence' ? 0.6 : 1;
    this.destroyed = false;
    this.cooldown = 0;
    this.triggered = false; // traps: single-use
    // Blueprint/construction pipeline (RimWorld-style: place an order, a citizen builds it over
    // time instead of it appearing instantly) -- opts.instant skips this for the wave-4-starter
    // turrets so a fresh colony isn't defenseless while nobody has built anything yet.
    this.underConstruction = !opts.instant;
    this.buildProgress = opts.instant ? 1 : 0;
    this.claimedBy = null;
    // Audio hook bookkeeping (world.js's structure-filter pass): tracks whether the
    // build-complete cue has already fired for this structure, so an instant/starter structure
    // (never actually "under construction") doesn't trigger it, and a real blueprint only
    // triggers it once, right when underConstruction flips false.
    this._builtNotified = !this.underConstruction;
  }
}

// RimWorld's raid "arrival methods": the same raid points spent a different way. Edge is the
// original walk-in-from-off-map behaviour; Tunnel drops the raiders straight into the settlement
// interior, bypassing the whole perimeter of fences/traps/turret kill-boxes.
const ArrivalMethod = Object.freeze({
  Edge: 0,
  Tunnel: 1,
});

// Roster-composition rates, soak-tested alongside ATTACKER_ARCHETYPES/RESISTANCE -- see the
// balance note on ATTACKER_ARCHETYPES before touching any of these.
const BRUTE_RATE = 0.15;
const SKIRMISHER_RATE = 0.35;
const BOSS_MIN_WAVE = 8;
const BOSS_WAVE_GAP = 5;   // minimum waves between two Bosses
const BOSS_CHANCE = 0.05;  // per-attacker roll, only once the two gates above pass

const TUNNEL_MIN_WAVE = 4;          // no burrowing before the colony has had a chance to build anything
const TUNNEL_BASE_CHANCE = 0.08;
const TUNNEL_MAX_CHANCE = 0.35;
const TUNNEL_CLUSTER_RADIUS = 2.2;  // how tightly the emerging group is packed around the mouth

class WaveSpawner {
  constructor(grid) {
    this.grid = grid;
    this.nextWaveTick = 300; // 30s at 10Hz, first wave grace period
    this.waveNumber = 0;
    this.strengthFactor = 1; // set by director.js each tick
    this.cycleMult = 1; // storyteller-personality breather-length multiplier
    this.doubleChance = 0.1; // odds of immediately queuing a second wave close behind
    this.lastArrival = ArrivalMethod.Edge; // for the event log / debug inspection
    this.lastTunnelPoint = null; // {x,y} of the most recent tunnel mouth, used by render.js
  }

  waveCount() {
    return Math.round((2 + Math.min(10, this.waveNumber * 1.5)) * this.strengthFactor);
  }

  waveBaseHealth() {
    return (1 + this.waveNumber * 0.1) * Math.max(0.7, this.strengthFactor);
  }

  // Roster composition by wave: pure Grunts early, Skirmishers join at wave 2, Brutes at 3, and a
  // single rare Boss becomes possible from wave 8 onward. Bosses are gated three ways -- at most
  // one per wave, a low per-attacker roll, AND a minimum gap of BOSS_WAVE_GAP waves since the last
  // one -- because with waves this frequent, "12% per attacker, one per wave" alone put a Boss in
  // over half of all waves in soak-testing. A Boss is meant to be an event.
  rollKind(rng, bossAllowed) {
    const bossReady = this.waveNumber >= BOSS_MIN_WAVE &&
      (this._lastBossWave == null || this.waveNumber - this._lastBossWave >= BOSS_WAVE_GAP);
    if (bossAllowed && bossReady && rng() < BOSS_CHANCE) {
      this._lastBossWave = this.waveNumber;
      return AttackerKind.Boss;
    }
    const r = rng();
    if (this.waveNumber >= 3 && r < BRUTE_RATE) return AttackerKind.Brute;
    if (this.waveNumber >= 2 && r < BRUTE_RATE + SKIRMISHER_RATE) return AttackerKind.Skirmisher;
    return AttackerKind.Grunt;
  }

  spawnOneWave(currentTick, attackers, rng) {
    this.waveNumber++;
    this.lastArrival = ArrivalMethod.Edge;
    const count = this.waveCount();
    const baseHealth = this.waveBaseHealth();
    let bossAllowed = true;
    for (let n = 0; n < count; n++) {
      const edge = Math.floor(rng() * 4);
      let x, y;
      if (edge === 0) { x = 0; y = rng() * this.grid.height; }
      else if (edge === 1) { x = this.grid.width - 1; y = rng() * this.grid.height; }
      else if (edge === 2) { x = rng() * this.grid.width; y = 0; }
      else { x = rng() * this.grid.width; y = this.grid.height - 1; }
      const kind = this.rollKind(rng, bossAllowed);
      if (kind === AttackerKind.Boss) bossAllowed = false;
      attackers.spawn(x, y, baseHealth, kind);
    }
  }

  // Picks an unblocked interior cell somewhere between the settlement core and the midpoint to
  // the map edge -- far enough in that the raiders are already past any perimeter line, but not
  // literally on top of the citizen huddle every single time.
  pickTunnelPoint(rng) {
    const cx = this.grid.width / 2, cy = this.grid.height / 2;
    const maxR = Math.min(this.grid.width, this.grid.height) * 0.28;
    for (let attempt = 0; attempt < 24; attempt++) {
      const ang = rng() * Math.PI * 2;
      const r = 2 + rng() * maxR;
      const x = cx + Math.cos(ang) * r;
      const y = cy + Math.sin(ang) * r;
      if (!this.grid.inBounds(Math.floor(x), Math.floor(y))) continue;
      if (this.grid.isBlocked(Math.floor(x), Math.floor(y))) continue;
      return { x, y };
    }
    return { x: cx, y: cy };
  }

  // Tunnel arrival: one mouth, one tight cluster, no perimeter to chew through. Slightly smaller
  // headcount than an equivalent edge wave because it skips every layer of defense on the way in.
  spawnTunnelWave(currentTick, attackers, rng) {
    this.waveNumber++;
    this.lastArrival = ArrivalMethod.Tunnel;
    const mouth = this.pickTunnelPoint(rng);
    this.lastTunnelPoint = mouth;
    const count = Math.max(2, Math.round(this.waveCount() * 0.7));
    const baseHealth = this.waveBaseHealth();
    let bossAllowed = true;
    for (let n = 0; n < count; n++) {
      const ang = rng() * Math.PI * 2;
      const r = rng() * TUNNEL_CLUSTER_RADIUS;
      const x = Math.max(0, Math.min(this.grid.width - 1, mouth.x + Math.cos(ang) * r));
      const y = Math.max(0, Math.min(this.grid.height - 1, mouth.y + Math.sin(ang) * r));
      const kind = this.rollKind(rng, bossAllowed);
      if (kind === AttackerKind.Boss) bossAllowed = false;
      attackers.spawn(x, y, baseHealth, kind);
    }
  }

  // Hazard-scaled tunnel odds, mirroring director.js's pollution-makes-waves-worse pattern
  // (read-only use of world.pollution/world.nuclearWaste -- colonyStrength() is untouched).
  tunnelChance(world) {
    if (this.waveNumber < TUNNEL_MIN_WAVE) return 0;
    const hazard = (world?.pollution || 0) + (world?.nuclearWaste || 0) * 2;
    return Math.min(TUNNEL_MAX_CHANCE, TUNNEL_BASE_CHANCE + hazard / 900);
  }

  _spawnWithArrival(currentTick, attackers, rng, world) {
    if (rng() < this.tunnelChance(world)) this.spawnTunnelWave(currentTick, attackers, rng);
    else this.spawnOneWave(currentTick, attackers, rng);
  }

  tick(currentTick, attackers, rng, world = null) {
    if (currentTick < this.nextWaveTick) return;
    this._spawnWithArrival(currentTick, attackers, rng, world);
    if (rng() < this.doubleChance) this._spawnWithArrival(currentTick, attackers, rng, world); // Cassandra-style back-to-back

    const delay = (600 - Math.min(300, this.waveNumber * 15)) * this.cycleMult;
    this.nextWaveTick = currentTick + Math.round(delay / this.strengthFactor);
  }
}

const TURRET_RANGE = 8;
const TURRET_COOLDOWN_TICKS = 8;
const TURRET_DAMAGE = 0.35;
const POWERED_DAMAGE_MULT = 1.5;
const POWERED_RANGE_MULT = 1.25;

// Real connected-graph power (power.js): a consumer is powered only if it touches a generator
// or a wire run that leads back to one. This replaced a radius stub where mere proximity to a
// generator was enough and wires didn't exist.
function isPowered(structures, x, y) {
  return isPoweredAt(structures, x, y);
}

// Overload-aware gate for the powered *bonus* specifically (power.js's overload mechanic): true
// only when this tile is powered AND the segment/nuclear-radius feeding it isn't overloaded.
// isPowered above stays a plain connectivity check (vehicles.js's electric-garage gate reads it
// as "is there power at all", which overload deliberately doesn't cut) -- this is strictly for
// consumer-side bonus decisions like the turret/tesla boost below and world.js's watchtower
// warning-window boost.
function isPoweredBonus(structures, x, y) {
  return hasPoweredBonus(structures, x, y);
}
const ATTACKER_SPEED = 0.03;
const ATTACKER_CITIZEN_DAMAGE = 0.008;
const ATTACKER_CONTACT_RANGE = 0.5;
const FENCE_CONTACT_RANGE = 0.7;
const FENCE_DAMAGE_PER_TICK = 0.015;
const TRAP_TRIGGER_RANGE = 0.5;
const TRAP_DAMAGE = 3; // instant-kill-ish burst
const GUARD_RANGE = 3.5; const GUARD_DAMAGE = 0.05; const GUARD_COOLDOWN = 4;
const SNIPER_RANGE = 9; const SNIPER_DAMAGE = 0.12; const SNIPER_COOLDOWN = 10;

// Tesla coil (SEA:R): weaker per-hit than a plain turret but chains to every attacker in range
// each activation -- a crowd-control pick over a single-target DPS pick, not a strict upgrade.
const TESLA_RANGE = 4.5; const TESLA_DAMAGE = 0.12; const TESLA_COOLDOWN_TICKS = 14;

// Floodlight (SEA:R's "soft wall" -- an area-denial light that slows rather than blocks, so it
// doesn't need its own health/destroy state like a fence does).
const FLOODLIGHT_RANGE = 3.5;
const FLOODLIGHT_SLOW_MULT = 0.35; // attacker speed multiplier while inside the radius

// Nuclear generator (SEA:R): the high-risk/high-reward power tier. Its reward is a wireless
// power-delivery radius -- consumers standing near it get powered without needing a wire run at
// all, unlike a plain generator which only reaches through the wire graph (power.js). Its risk is
// nuclear waste: a hazard resource distinct from world.pollution that, left uncontained, turns
// the ground around the generator into a damage-dealing zone (not just a visual tint like the
// smog haze). Building a `waste_storage` structure within NUCLEAR_CONTAINMENT_RADIUS neutralizes
// the hazard entirely -- no staffing requirement, per FEATURE_RESEARCH.md's simpler fallback.
const NUCLEAR_HAZARD_RADIUS = 4;
const NUCLEAR_CONTAINMENT_RADIUS = 5;
const NUCLEAR_WASTE_RATE = 0.06; // world.nuclearWaste gained per uncontained nuclear generator per tick
const NUCLEAR_HAZARD_CITIZEN_DAMAGE = 0.02; // per tick while standing in an uncontained hazard zone
const NUCLEAR_HAZARD_STRUCTURE_DAMAGE = 0.01;

function isNuclearContained(structures, gen) {
  return structures.some(s => s.kind === 'waste_storage' && !s.destroyed && !s.underConstruction &&
    Math.hypot(s.x - gen.x, s.y - gen.y) <= NUCLEAR_CONTAINMENT_RADIUS);
}

// Periodic hazard damage around any nuclear generator that isn't guarded by a nearby waste
// storage -- mirrors tickAttackerVsCitizens's downed-then-dead pattern for citizens, and the
// fence-damage/destroyed pattern (tickAttackers) for structures, so an unguarded reactor reads as
// a real threat rather than a stat debuff.
function tickNuclearHazard(structures, citizens) {
  for (const gen of structures) {
    if (gen.kind !== 'generator_nuclear' || gen.destroyed || gen.underConstruction) continue;
    if (isNuclearContained(structures, gen)) continue;

    for (let c = 0; c < citizens.count; c++) {
      if (!citizens.isAliveAt(c)) continue;
      if (Math.hypot(citizens.x[c] - gen.x, citizens.y[c] - gen.y) > NUCLEAR_HAZARD_RADIUS) continue;
      if (citizens.isDownedAt(c)) {
        citizens.flags[c] |= CitizenFlags.Dead;
        citizens.alive[c] = 0;
        continue;
      }
      const healthMult = citizens.trait[c]?.healthMult ?? 1;
      citizens.health[c] -= NUCLEAR_HAZARD_CITIZEN_DAMAGE / healthMult;
      if (citizens.health[c] <= 0) {
        citizens.health[c] = 0.05;
        citizens.flags[c] |= CitizenFlags.Downed;
      }
    }

    for (const s of structures) {
      if (s === gen || s.kind === 'waste_storage' || s.destroyed || s.underConstruction) continue;
      if (Math.hypot(s.x - gen.x, s.y - gen.y) > NUCLEAR_HAZARD_RADIUS) continue;
      s.health -= NUCLEAR_HAZARD_STRUCTURE_DAMAGE;
      if (s.health <= 0) s.destroyed = true;
    }
  }
}

function nearestLivingCitizen(citizens, x, y) {
  let bestI = -1, bestDist = Infinity;
  for (let c = 0; c < citizens.count; c++) {
    if (!citizens.isAliveAt(c)) continue;
    const d = Math.hypot(citizens.x[c] - x, citizens.y[c] - y);
    if (d < bestDist) { bestDist = d; bestI = c; }
  }
  return bestI;
}

// Attackers hunt the nearest living citizen (falling back to the settlement center if the
// colony is somehow empty) and are blocked by un-destroyed fences/walls in their way; they
// chip away at the blocking structure instead of walking through it.
function tickAttackers(attackers, structures, grid, centerX, centerY, citizens, onScrap, onKill) {
  for (let i = 0; i < attackers.count; i++) {
    if (!attackers.isAliveAt(i)) continue;

    const arch = attackers.archetypeAt(i);

    const blocker = findBlockingFence(structures, attackers.x[i], attackers.y[i]);
    if (blocker) {
      blocker.health -= FENCE_DAMAGE_PER_TICK * arch.damageMult; // a Brute tears through fencing
      if (blocker.health <= 0) blocker.destroyed = true;
      continue;
    }

    const targetC = citizens ? nearestLivingCitizen(citizens, attackers.x[i], attackers.y[i]) : -1;
    const tx = targetC >= 0 ? citizens.x[targetC] : centerX;
    const ty = targetC >= 0 ? citizens.y[targetC] : centerY;
    const dx = tx - attackers.x[i];
    const dy = ty - attackers.y[i];
    const dist = Math.hypot(dx, dy);
    if (dist > ATTACKER_CONTACT_RANGE * 0.6) {
      const inFloodlight = structures.some(s => s.kind === 'floodlight' && !s.destroyed && !s.underConstruction &&
        Math.hypot(attackers.x[i] - s.x, attackers.y[i] - s.y) <= FLOODLIGHT_RANGE);
      const speed = ATTACKER_SPEED * arch.speedMult * (inFloodlight ? FLOODLIGHT_SLOW_MULT : 1);
      attackers.x[i] += (dx / dist) * speed;
      attackers.y[i] += (dy / dist) * speed;
    }

    for (const t of structures) {
      if (t.kind !== 'trap' || t.triggered || t.underConstruction) continue;
      if (Math.hypot(attackers.x[i] - t.x, attackers.y[i] - t.y) < TRAP_TRIGGER_RANGE) {
        t.triggered = true; t.destroyed = true;
        // Traps are the game's Explosive source: the counter to armored Brutes, wasted on
        // Skirmishers (who mostly run clear of the blast).
        if (damageAttacker(attackers, i, TRAP_DAMAGE, DamageType.Explosive)) { onScrap?.(SCRAP_PER_KILL); onKill?.(); }
      }
    }
  }
}

function findBlockingFence(structures, x, y) {
  for (const s of structures) {
    if (s.kind !== 'fence' || s.destroyed || s.underConstruction) continue;
    if (Math.hypot(x - s.x, y - s.y) < FENCE_CONTACT_RANGE) return s;
  }
  return null;
}

function tickTurrets(structures, attackers, onScrap, onFire, onKill) {
  for (const s of structures) {
    if (s.kind !== 'turret' && s.kind !== 'tesla') continue;
    if (s.destroyed || s.underConstruction) continue;
    if (s.cooldown > 0) { s.cooldown--; continue; }

    const powered = isPoweredBonus(structures, s.x, s.y);
    const isTesla = s.kind === 'tesla';
    const range = (isTesla ? TESLA_RANGE : TURRET_RANGE) * (powered ? POWERED_RANGE_MULT : 1);
    const damage = (isTesla ? TESLA_DAMAGE : TURRET_DAMAGE) * (powered ? POWERED_DAMAGE_MULT : 1);
    // Tesla coils are the Energy source (armor-piercing, the answer to a Boss); plain turrets
    // are Kinetic (great against unarmored Skirmishers, poor against a Brute's plate).
    const dtype = isTesla ? DamageType.Energy : DamageType.Kinetic;

    if (isTesla) {
      // Chains to every attacker in range instead of picking one -- Tesla's SEA:R niche is
      // crowd control, not single-target DPS (that's what plain turrets are for).
      let hitAny = false;
      for (let i = 0; i < attackers.count; i++) {
        if (!attackers.isAliveAt(i)) continue;
        if (Math.hypot(attackers.x[i] - s.x, attackers.y[i] - s.y) > range) continue;
        hitAny = true;
        if (damageAttacker(attackers, i, damage, dtype)) { onScrap?.(SCRAP_PER_KILL); onKill?.(); }
      }
      if (hitAny) { s.cooldown = TESLA_COOLDOWN_TICKS; onFire?.(s); }
      continue;
    }

    const bestI = nearestAliveAttacker(attackers, s.x, s.y, range);
    if (bestI >= 0) {
      if (damageAttacker(attackers, bestI, damage, dtype)) { onScrap?.(SCRAP_PER_KILL); onKill?.(); }
      s.cooldown = TURRET_COOLDOWN_TICKS;
      onFire?.(s);
    }
  }
}

function nearestAliveAttacker(attackers, x, y, maxRange) {
  let bestI = -1, bestDist = maxRange;
  for (let i = 0; i < attackers.count; i++) {
    if (!attackers.isAliveAt(i)) continue;
    const d = Math.hypot(attackers.x[i] - x, attackers.y[i] - y);
    if (d < bestDist) { bestDist = d; bestI = i; }
  }
  return bestI;
}

// Attackers in contact range of a living citizen deal damage each tick; citizen dies (Dead
// flag, permadeath per the RimWorld-style design) at 0 health.
// Downed-not-dead (RimWorld pattern, see FEATURE_RESEARCH.md): the first time a citizen's
// health hits 0 they go down but survive; if an attacker lands another hit on them while
// already down, that's when they actually die. Gives a real reprieve instead of instant
// permadeath on the first unlucky contact tick.
function tickAttackerVsCitizens(attackers, citizens, onDowned) {
  for (let i = 0; i < attackers.count; i++) {
    if (!attackers.isAliveAt(i)) continue;
    // Per-archetype reach: a Boss's contactRange is wide enough that it hits every citizen in a
    // small area each tick (this loop damages everyone in range), which is its cleave attack.
    const arch = attackers.archetypeAt(i);
    const reach = arch.contactRange ?? ATTACKER_CONTACT_RANGE;
    for (let c = 0; c < citizens.count; c++) {
      if (!citizens.isAliveAt(c)) continue;
      if (Math.hypot(attackers.x[i] - citizens.x[c], attackers.y[i] - citizens.y[c]) > reach) continue;

      if (citizens.isDownedAt(c)) {
        citizens.flags[c] |= CitizenFlags.Dead;
        citizens.alive[c] = 0;
        onDowned?.();
        continue;
      }

      const healthMult = citizens.trait[c]?.healthMult ?? 1;
      citizens.health[c] -= (ATTACKER_CITIZEN_DAMAGE * arch.damageMult) / healthMult;
      if (citizens.health[c] <= 0) {
        citizens.health[c] = 0.05;
        citizens.flags[c] |= CitizenFlags.Downed;
        onDowned?.();
      }
    }
  }
}

// Guards/snipers fight back with their personal weapon (short/long range respectively),
// separate from turret coverage. Gains combat skill on a confirmed kill.
function tickStaffCombat(citizens, roster, idOf, attackers, onScrap, onKill) {
  for (let i = 0; i < citizens.count; i++) {
    if (!citizens.isAliveAt(i)) continue;
    if (citizens.isDownedAt(i)) continue; // downed guards/snipers can't fight back
    const kind = roster.kindOf(idOf(i));
    if (kind !== 'Guard' && kind !== 'Sniper') continue;

    if (citizens._staffCooldown[i] > 0) { citizens._staffCooldown[i]--; continue; }

    // Armory-issued weapon tier (security.js WEAPON_TIERS/tickArmoryIssuance) multiplies the
    // role's baseline stats -- Sidearm is 1x everywhere (identical to the old flat constants) for
    // any guard/sniper nobody's built an Armory for yet.
    const tier = WEAPON_TIERS[roster.weaponOf(idOf(i))] || WEAPON_TIERS.Sidearm;
    const range = (kind === 'Sniper' ? SNIPER_RANGE : GUARD_RANGE) * tier.rangeMult;
    const damage = (kind === 'Sniper' ? SNIPER_DAMAGE : GUARD_DAMAGE) * tier.damageMult;
    const cooldown = Math.round((kind === 'Sniper' ? SNIPER_COOLDOWN : GUARD_COOLDOWN) * tier.cooldownMult);
    // Guards carry conventional sidearms (Kinetic); snipers carry the long-range armor-piercing
    // rifle (Energy), so a sniper line is the personnel answer to Brutes/Bosses.
    const dtype = kind === 'Sniper' ? DamageType.Energy : DamageType.Kinetic;

    const targetI = nearestAliveAttacker(attackers, citizens.x[i], citizens.y[i], range);
    if (targetI >= 0) {
      citizens._staffCooldown[i] = cooldown;
      if (damageAttacker(attackers, targetI, damage, dtype)) {
        citizens.skillCombat[i] += 0.05 * PASSION_GAIN_MULT[citizens.passionCombat[i]];
        onScrap?.(SCRAP_PER_KILL);
        onKill?.();
      }
    }
  }
}


// ---- relationships.js ----
// Condensed from SD.Sim's relationship web: nearby citizens slowly build friendship, crossing
// a threshold logs a social event for the HUD feed.
const PROXIMITY = 1.6;
const GROW_RATE = 0.004;
const FRIEND_THRESHOLD = 0.6;

class RelationshipWeb {
  constructor() {
    this.friendship = new Map(); // "idA:idB" (idA<idB) -> value
    this.events = []; // rolling log of {tick, text}
  }

  _key(a, b) { return a < b ? `${a}:${b}` : `${b}:${a}`; }

  tick(store, idOf, currentTick) {
    for (let i = 0; i < store.count; i++) {
      if (!store.isAliveAt(i)) continue;
      for (let j = i + 1; j < store.count; j++) {
        if (!store.isAliveAt(j)) continue;
        const d = Math.hypot(store.x[i] - store.x[j], store.y[i] - store.y[j]);
        if (d > PROXIMITY) continue;

        const key = this._key(idOf(i), idOf(j));
        const before = this.friendship.get(key) || 0;
        const after = Math.min(1, before + GROW_RATE);
        this.friendship.set(key, after);

        if (before < FRIEND_THRESHOLD && after >= FRIEND_THRESHOLD) {
          this.events.push({ tick: currentTick, text: `${store.name[i]} and ${store.name[j]} became friends` });
          if (this.events.length > 20) this.events.shift();
        }
      }
    }
  }
}


// ---- director.js ----
// Condensed from RimWorld's AI Storyteller pattern (see FEATURE_RESEARCH.md): the three
// personalities are just different parameter sets over one scheduler, not three separate
// systems. Also folds in SEA:R's signature mechanic -- unmanaged pollution makes waves worse,
// a player-controlled difficulty input distinct from RimWorld's wealth-based one.
function colonyStrength(world) {
  let aliveCitizens = 0;
  for (let i = 0; i < world.citizens.count; i++) if (world.citizens.isAliveAt(i)) aliveCitizens++;

  let structureHealth = 0;
  for (const s of world.structures) if (!s.destroyed && !s.underConstruction) structureHealth += s.health;

  // Scrap uses sqrt rather than a linear term. Idle citizens auto-harvest resource nodes even in
  // a completely hands-off colony (jobs.js's idle-fallback), so scrap keeps growing forever with
  // zero player action or actual defensive investment -- a linear term let banked scrap alone
  // saturate strengthFactor to its cap within a few thousand ticks (the root cause of a real
  // regression: hands-off survival time dropping from ~22-36k ticks to ~7-10k ticks, caught in
  // soak-testing). Sqrt keeps scrap a meaningful wealth signal without letting passive
  // accumulation alone drive difficulty as hard as actually-built defense/population.
  return aliveCitizens * 2 + structureHealth * 3 + Math.sqrt(world.scrap) * 1.5;
}

const AGGRESSION_MULTIPLIER = { Calm: 0.75, Standard: 1, Aggressive: 1.35 };

// cycleMult: multiplies the base wave-delay formula (bigger = longer breathers).
// doubleChance: odds a wave, once due, immediately schedules a second one close behind.
// strengthWeight: how much colony strength (vs. flat randomness) drives wave size/timing --
// Randy ignores it almost entirely, matching "no curve at all" in the source game.
// cycleMult tuned relative to 1.0 = the original pre-storyteller baseline (soak-tested at
// ~22-36 min hands-off survival); Cassandra sits AT that baseline rather than below it --
// "least forgiving of the three" should mean "no bonus breathing room", not "actively worse
// than the game was before storytellers existed". First-pass numbers here made ALL three
// personalities collapse a hands-off colony in ~12-17 min, a real regression caught in
// soak-testing -- these are the corrected values, re-verify after any further tuning.
const STORYTELLERS = {
  Cassandra: { cycleMult: 1.0, doubleChance: 0.12, strengthWeight: 1.0 },
  Phoebe: { cycleMult: 1.8, doubleChance: 0.02, strengthWeight: 0.75 },
  Randy: { cycleMultMin: 0.7, cycleMultMax: 1.6, doubleChance: 0.08, strengthWeight: 0.15 }, // randomized per-wave, not fixed -- "no curve at all"
};

function directWaveSpawner(world) {
  const strength = colonyStrength(world);
  const mult = AGGRESSION_MULTIPLIER[world.aggression] ?? 1;
  const teller = STORYTELLERS[world.storyteller] || STORYTELLERS.Cassandra;

  const strengthTerm = (strength / 120) * mult;
  const randomTerm = 0.7 + world.rng() * 0.9; // Randy leans almost entirely on this
  const blended = strengthTerm * teller.strengthWeight + randomTerm * (1 - teller.strengthWeight);

  // Pollution scales the danger multiplier upward -- mismanaged waste literally makes the
  // siege worse, independent of the storyteller's own curve.
  const pollutionTerm = 1 + Math.min(1.2, (world.pollution || 0) / 200);

  world.waveSpawner.strengthFactor = Math.max(0.5, Math.min(1.8, blended * pollutionTerm));
  world.waveSpawner.cycleMult = teller.cycleMultMin != null
    ? teller.cycleMultMin + world.rng() * (teller.cycleMultMax - teller.cycleMultMin)
    : teller.cycleMult;
  world.waveSpawner.doubleChance = teller.doubleChance;
}


// ---- schedule.js ----
// Day/night "Duty Roster" scheduling -- genre-neutral cousin of Prison Architect's "Regime"
// (see FEATURE_RESEARCH.md's PA section): a global cycle of Sleep/Work/Recreation blocks that
// biases citizen behavior (jobs.js tickJobs) toward the "right" activity for the time of day,
// without overriding the needs-driven fallback -- a starving/exhausted citizen still breaks
// schedule to eat/sleep, see the CRITICAL_* overrides in jobs.js.

const ScheduleBlock = Object.freeze({
  Sleep: 0,
  Work: 1,
  Recreation: 2,
});

// Full day/night cycle length in ticks. At 10Hz that's 240s (4 minutes) real time -- picked to
// be a handful of siege.js WaveSpawner intervals (30-60s each, see WaveSpawner.tick's `delay`)
// so a siege can plausibly land at any point in the cycle, including squarely at night, rather
// than the two systems drifting completely out of sync with each other.
const DAY_NIGHT_CYCLE_TICKS = 2400;

// Default global regime -- every citizen follows this until per-citizen overrides exist (see
// FEATURE_RESEARCH.md stretch goal). Expressed as fractions of the cycle, matching
// SimWorld.timeOfDay's 0-1 range. Two Sleep blocks straddle midnight/cycle-wrap; two short
// Recreation blocks bookend the workday, PA-Regime-style.
const DEFAULT_SCHEDULE = [
  { start: 0.00, end: 0.22, block: ScheduleBlock.Sleep },
  { start: 0.22, end: 0.30, block: ScheduleBlock.Recreation },
  { start: 0.30, end: 0.80, block: ScheduleBlock.Work },
  { start: 0.80, end: 0.88, block: ScheduleBlock.Recreation },
  { start: 0.88, end: 1.00, block: ScheduleBlock.Sleep },
];

function getScheduleBlock(timeOfDay, schedule = DEFAULT_SCHEDULE) {
  const t = ((timeOfDay % 1) + 1) % 1; // defensive wrap, timeOfDay should already be in [0,1)
  for (const b of schedule) if (t >= b.start && t < b.end) return b.block;
  return ScheduleBlock.Work;
}

// Convenience for UI (main.js topbar indicator) -- "night" as the sun/moon icon cares about it,
// which is a bit wider than the strict Sleep block so dusk/dawn read visually as night too.
function isNight(timeOfDay) {
  const t = ((timeOfDay % 1) + 1) % 1;
  return t < 0.25 || t >= 0.85;
}


// ---- jobs.js ----
// Real Eat/Sleep/Harvest/Build job execution, condensed from SD.Sim's job-priority system:
// citizens with low hunger/rest walk to the nearest matching zone and refill there; citizens
// with nothing urgent pending instead work the colony's economy -- finishing player-placed
// blueprints first (Prison-Architect-style "you ordered it, someone builds it"), then
// harvesting scrap nodes when nothing needs building (RimWorld-style raw-material gathering).








const ROOM_REFILL_BONUS = 1.3; // RimWorld/PA-style: an actually-enclosed room works better than open ground
// Water grid payoff (water.js): a Food or Recreation zone tile fed by a pump/pipe run refills
// hunger/social faster, same "provisioned area works better" precedent as ROOM_REFILL_BONUS
// above -- running water on top of four walls stacks multiplicatively with it, it doesn't
// replace it. No Bedroom bonus: rest isn't naturally a "running water" need the way eating/
// recreating are, and power.js's turret/tesla/watchtower trio didn't need a bedroom analogue
// either -- every consumer type doesn't have to take every utility.
const WATER_REFILL_BONUS = 1.25;

const JobState = Object.freeze({
  Idle: 0,
  SeekingFood: 1,
  Eating: 2,
  SeekingBed: 3,
  Sleeping: 4,
  SeekingRec: 5,
  Recreating: 6,
  SeekingBuild: 7,
  Building: 8,
  SeekingScrap: 9,
  Harvesting: 10,
  SeekingVehicle: 11,
  Driving: 12,
  SeekingAnimal: 13, // RimWorld-style taming, see security.js's wild-animal helpers and FEATURE_RESEARCH.md
  Taming: 14,
});

// Work Priorities (RimWorld Work-tab-style, see citizens.js's hasWorkPriorities/workPriority*
// fields and main.js's Work Priorities panel). One category per non-needs JobState pair below --
// deliberately no categories without a corresponding behavior. Order here doubles as the
// legacy/default fixed priority ladder's order (Construction > Hauling > Harvesting > Animal),
// so equal-priority ties in a citizen's custom order break the same way the untouched ladder
// already does.
const WorkCategory = Object.freeze({
  Construction: 0, // SeekingBuild / Building
  Hauling: 1,       // SeekingVehicle / Driving
  Harvesting: 2,    // SeekingScrap / Harvesting
  Animal: 3,        // SeekingAnimal / Taming
});
const WORK_CATEGORY_ORDER = [
  WorkCategory.Construction, WorkCategory.Hauling, WorkCategory.Harvesting, WorkCategory.Animal,
];
const WORK_CATEGORY_LABELS = {
  [WorkCategory.Construction]: 'Construction',
  [WorkCategory.Hauling]: 'Hauling',
  [WorkCategory.Harvesting]: 'Harvesting',
  [WorkCategory.Animal]: 'Animal Handling',
};
// Per-citizen priority field name for each category, matching citizens.js's CitizenStore fields.
const WORK_CATEGORY_FIELD = {
  [WorkCategory.Construction]: 'workPriorityConstruction',
  [WorkCategory.Hauling]: 'workPriorityHauling',
  [WorkCategory.Harvesting]: 'workPriorityHarvesting',
  [WorkCategory.Animal]: 'workPriorityAnimal',
};

const SEEK_SOCIAL_THRESHOLD = 0.35;
const SEEK_HUNGER_THRESHOLD = 0.45;
const SEEK_REST_THRESHOLD = 0.4;
const SATISFIED_THRESHOLD = 0.85;

// Duty Roster scheduling (see schedule.js) biases which need-thresholds apply this tick --
// it never removes the fallback, it just widens/narrows the window before a citizen breaks off
// to handle a need. CRITICAL_* floors guarantee a citizen always eats/rests before the need
// actually bottoms out, even deep in a Work block (PA's Regime can starve inmates who skip
// mealtime; this deliberately can't).
const CRITICAL_HUNGER_OVERRIDE = 0.18;
const CRITICAL_REST_OVERRIDE = 0.12;
const SCHEDULE_SLEEP_REST_SEEK = 0.75; // during the Sleep block, head to bed well before exhausted
const SCHEDULE_RECREATION_SOCIAL_SEEK = 0.7; // during the Recreation block, socialize proactively
const SCHEDULE_WORK_THRESHOLD_MULT = 0.4; // during the Work block, only break for a need that's fairly urgent
const NIGHT_INTERRUPT_REST_THRESHOLD = 0.6; // Sleep block will pull a not-yet-exhausted citizen off a work task
const REFILL_RATE = 0.05; // per tick while occupying the zone
const ETHANOL_FOOD_REFILL_MULT = 0.5; // Food zone refill halved while world.ethanolPenaltyTimer counts down, see vehicles.js
const ARRIVE_DIST = 0.35;
const JOB_SPEED = 0.09; // citizens hustle to zones -- travel time was the dominant cost in the needs loop

const BUILD_RATE = 0.012; // per tick, scaled by construction skill below
const BUILD_SKILL_GAIN = 0.02;
const HARVEST_RATE = 3; // scrap per tick pulled from a node
const HARVEST_SKILL_GAIN = 0.01;
const ON_BREAK_RATE_MULT = 0.5; // low-mood citizens work/harvest/build/travel at half speed
// Unrest (world.js's UNREST_* constants/world.unrestActive -- Prison Architect's riot
// state-machine reframed genre-neutral, see world.js's doc comment for the trigger/resolve
// design): a COLONY-WIDE penalty distinct from ON_BREAK_RATE_MULT above -- applies to every
// citizen's work/build/harvest/travel rate while world.unrestActive is true, not just the
// citizens who happen to already be individually OnBreak. Stacks multiplicatively with
// ON_BREAK_RATE_MULT for a citizen who's both (0.5 * 0.7 = 0.35x), which is intentional --
// unrest hits hardest on top of an already-struggling citizen. Deliberately milder than the
// per-citizen break penalty (0.7 vs 0.5) since this is colony-wide and stacks on top of it.
const UNREST_RATE_MULT = 0.7;

function isOnJob(store, i) {
  return store.jobState[i] !== JobState.Idle;
}

// One try-to-claim helper per WorkCategory, each doing exactly what the original inline Idle-
// branch code did for that job type (see the git history of tickJobs below) -- factored out so
// both the legacy fixed-order ladder and a citizen's custom Work Priorities order can call the
// same claim logic instead of drifting apart. Returns true (and mutates store/jobState/_jobRef)
// only if a job of that category was actually available and claimed this tick.
function tryClaimConstruction(store, i, structures, idOf) {
  const blueprint = findNearestBlueprint(structures, store.x[i], store.y[i], idOf(i));
  if (!blueprint) return false;
  blueprint.claimedBy = idOf(i);
  store.jobState[i] = JobState.SeekingBuild;
  store.targetX[i] = blueprint.x; store.targetY[i] = blueprint.y;
  store._jobRef[i] = blueprint;
  return true;
}

function tryClaimHauling(store, i, world) {
  const vehicle = findUndrivenVehicle(world.vehicles, store.x[i], store.y[i]);
  if (!vehicle) return false;
  store.jobState[i] = JobState.SeekingVehicle;
  store.targetX[i] = vehicle.x; store.targetY[i] = vehicle.y;
  store._jobRef[i] = vehicle;
  return true;
}

function tryClaimHarvesting(store, i, resourceNodes) {
  const node = findNearestNode(resourceNodes, store.x[i], store.y[i]);
  if (!node) return false;
  store.jobState[i] = JobState.SeekingScrap;
  store.targetX[i] = node.x; store.targetY[i] = node.y;
  store._jobRef[i] = node;
  return true;
}

function tryClaimAnimal(store, i, world, idOf) {
  const animal = findNearestTameableAnimal(world.wildAnimals || [], store.x[i], store.y[i]);
  if (!animal) return false;
  animal.claimedBy = idOf(i);
  store.jobState[i] = JobState.SeekingAnimal;
  store.targetX[i] = animal.x; store.targetY[i] = animal.y;
  store._jobRef[i] = animal;
  return true;
}

const WORK_CATEGORY_CLAIM = {
  [WorkCategory.Construction]: (store, i, structures, resourceNodes, world, idOf) => tryClaimConstruction(store, i, structures, idOf),
  [WorkCategory.Hauling]: (store, i, structures, resourceNodes, world, idOf) => tryClaimHauling(store, i, world),
  [WorkCategory.Harvesting]: (store, i, structures, resourceNodes, world, idOf) => tryClaimHarvesting(store, i, resourceNodes),
  [WorkCategory.Animal]: (store, i, structures, resourceNodes, world, idOf) => tryClaimAnimal(store, i, world, idOf),
};

function findNearestBlueprint(structures, x, y, excludeClaimedBy) {
  let best = null, bestDist = Infinity;
  for (const s of structures) {
    if (!s.underConstruction || s.destroyed) continue;
    if (s.claimedBy != null && s.claimedBy !== excludeClaimedBy) continue;
    const d = Math.hypot(s.x - x, s.y - y);
    if (d < bestDist) { bestDist = d; best = s; }
  }
  return best;
}

function findNearestNode(nodes, x, y) {
  let best = null, bestDist = Infinity;
  for (const n of nodes) {
    if (n.depleted) continue;
    const d = Math.hypot(n.x - x, n.y - y);
    if (d < bestDist) { bestDist = d; best = n; }
  }
  return best;
}

function findNearestTameableAnimal(wildAnimals, x, y) {
  let best = null, bestDist = Infinity;
  for (const a of wildAnimals) {
    if (a.claimedBy != null) continue; // someone's already taming this one
    const d = Math.hypot(a.x - x, a.y - y);
    if (d < bestDist) { bestDist = d; best = a; }
  }
  return best;
}

function tickJobs(store, zones, staffOnDuty, structures, resourceNodes, idOf, onScrapGain, world) {
  for (let i = 0; i < store.count; i++) {
    if (!store.isAliveAt(i)) continue;
    if (store.isDownedAt(i)) continue; // incapacitated, can't work until recovered
    if (staffOnDuty(i)) continue; // guards/snipers hold their post, no eat/sleep/work jobs

    // Duty Roster: a citizen deep in a work/harvest task at scheduled sleep-time gets pulled off
    // it to go find a bed, same as PA staff clearing a Regime block -- but only if they aren't
    // already close to exhausted (that path is handled below via the normal Idle/SeekingBed
    // branch regardless of schedule) and only for interruptible states; Driving and the
    // short Eating/Sleeping/Recreating fulfillment states are left to finish.
    const scheduleBlock = world ? getScheduleBlock(world.timeOfDay) : ScheduleBlock.Work;
    if (scheduleBlock === ScheduleBlock.Sleep && store.rest[i] < NIGHT_INTERRUPT_REST_THRESHOLD) {
      const interruptible = store.jobState[i];
      if (interruptible === JobState.Building || interruptible === JobState.SeekingBuild) {
        const bp = store._jobRef?.[i];
        if (bp) bp.claimedBy = null;
        store.jobState[i] = JobState.Idle;
      } else if (interruptible === JobState.Harvesting || interruptible === JobState.SeekingScrap
        || interruptible === JobState.SeekingVehicle) {
        store.jobState[i] = JobState.Idle;
      } else if (interruptible === JobState.SeekingAnimal || interruptible === JobState.Taming) {
        const animal = store._jobRef?.[i];
        if (animal) animal.claimedBy = null; // release it so someone else (or the same citizen later) can try again
        store.jobState[i] = JobState.Idle;
      }
    }

    const state = store.jobState[i];

    if (state === JobState.Idle) {
      // Schedule-biased thresholds -- Sleep block seeks a bed well before rest bottoms out,
      // Recreation block seeks company proactively, Work block narrows all three so a citizen
      // doesn't wander off mid-shift for anything short of a real need, and the CRITICAL_*
      // floors below stop that narrowing from ever becoming "never eats/sleeps at all".
      let restThreshold = SEEK_REST_THRESHOLD;
      let hungerThreshold = SEEK_HUNGER_THRESHOLD;
      let socialThreshold = SEEK_SOCIAL_THRESHOLD;
      if (scheduleBlock === ScheduleBlock.Sleep) {
        restThreshold = SCHEDULE_SLEEP_REST_SEEK;
      } else if (scheduleBlock === ScheduleBlock.Recreation) {
        socialThreshold = SCHEDULE_RECREATION_SOCIAL_SEEK;
      } else if (scheduleBlock === ScheduleBlock.Work) {
        restThreshold = Math.max(CRITICAL_REST_OVERRIDE, SEEK_REST_THRESHOLD * SCHEDULE_WORK_THRESHOLD_MULT);
        hungerThreshold = Math.max(CRITICAL_HUNGER_OVERRIDE, SEEK_HUNGER_THRESHOLD * SCHEDULE_WORK_THRESHOLD_MULT);
        socialThreshold = SEEK_SOCIAL_THRESHOLD * SCHEDULE_WORK_THRESHOLD_MULT;
      }

      // Starvation always wins the tie against a Sleep-block bed trip, regardless of check
      // order below -- a citizen shouldn't be walked past food to a bed because it's night.
      if (store.hunger[i] < CRITICAL_HUNGER_OVERRIDE) {
        const food = zones.nearestOfKind(ZoneKind.Food, store.x[i], store.y[i]);
        if (food) { store.jobState[i] = JobState.SeekingFood; store.targetX[i] = food.x; store.targetY[i] = food.y; continue; }
      }
      if (store.rest[i] < restThreshold) {
        const bed = zones.nearestOfKind(ZoneKind.Bedroom, store.x[i], store.y[i]);
        if (bed) { store.jobState[i] = JobState.SeekingBed; store.targetX[i] = bed.x; store.targetY[i] = bed.y; continue; }
      }
      if (store.hunger[i] < hungerThreshold) {
        const food = zones.nearestOfKind(ZoneKind.Food, store.x[i], store.y[i]);
        if (food) { store.jobState[i] = JobState.SeekingFood; store.targetX[i] = food.x; store.targetY[i] = food.y; continue; }
      }
      if (store.social[i] < socialThreshold) {
        const rec = zones.nearestOfKind(ZoneKind.Recreation, store.x[i], store.y[i]);
        if (rec) { store.jobState[i] = JobState.SeekingRec; store.targetX[i] = rec.x; store.targetY[i] = rec.y; continue; }
      }

      // Work Priorities override (RimWorld Work-tab-style, see citizens.js's hasWorkPriorities/
      // workPriority* fields and main.js's Work Priorities panel). Only a citizen the player has
      // actually opened that panel for takes this branch; everyone else falls through to the
      // original fixed ladder below completely untouched. Enabled categories (priority > 0) are
      // tried in ascending priority-number order (lower = higher priority, ties broken by
      // WORK_CATEGORY_ORDER, which is the same order the legacy ladder below uses), and a
      // category set to 0 is skipped entirely -- that citizen will never claim that kind of job,
      // even if it's the only thing available.
      if (store.hasWorkPriorities[i]) {
        const order = WORK_CATEGORY_ORDER
          .filter(cat => store[WORK_CATEGORY_FIELD[cat]][i] > 0)
          .sort((a, b) => store[WORK_CATEGORY_FIELD[a]][i] - store[WORK_CATEGORY_FIELD[b]][i]);
        for (const cat of order) {
          if (WORK_CATEGORY_CLAIM[cat](store, i, structures, resourceNodes, world, idOf)) break;
        }
        continue;
      }

      const blueprint = findNearestBlueprint(structures, store.x[i], store.y[i], idOf(i));
      if (blueprint) {
        blueprint.claimedBy = idOf(i);
        store.jobState[i] = JobState.SeekingBuild;
        store.targetX[i] = blueprint.x; store.targetY[i] = blueprint.y;
        store._jobRef[i] = blueprint;
        continue;
      }

      // Driving a built truck is checked before manual harvesting -- one haul cycle moves far
      // more scrap than one citizen picking at a node by hand, so an idle truck should win the
      // idle-citizen's attention. With resource nodes almost always available, checking this
      // after harvesting meant no citizen ever reached it in testing -- a real bug, not a
      // priority nuance.
      const vehicle = findUndrivenVehicle(world.vehicles, store.x[i], store.y[i]);
      const node = findNearestNode(resourceNodes, store.x[i], store.y[i]);

      // Passion tie-break (RimWorld-style): only when there's a genuine choice -- both an idle
      // truck and a harvestable node are actually available this tick -- a citizen who burns for
      // construction-adjacent work (harvesting gains skillConstruction, see below) very slightly
      // prefers picking at the node over driving. Doesn't touch the needs-first checks above, and
      // doesn't apply when only one option exists (that's not a "choice").
      if (vehicle && node && store.passionConstruction[i] === Passion.Burning) {
        store.jobState[i] = JobState.SeekingScrap;
        store.targetX[i] = node.x; store.targetY[i] = node.y;
        store._jobRef[i] = node;
        continue;
      }

      if (vehicle) {
        store.jobState[i] = JobState.SeekingVehicle;
        store.targetX[i] = vehicle.x; store.targetY[i] = vehicle.y;
        store._jobRef[i] = vehicle;
        continue;
      }

      if (node) {
        store.jobState[i] = JobState.SeekingScrap;
        store.targetX[i] = node.x; store.targetY[i] = node.y;
        store._jobRef[i] = node;
        continue;
      }

      // Taming (RimWorld-style, see security.js and FEATURE_RESEARCH.md): lowest-priority of all
      // the idle-fallback jobs -- an idle wild animal to approach only matters once there's
      // nothing else productive to do, same reasoning as vehicle/node above but one rung further
      // down, since taming doesn't feed the scrap economy the way those two do.
      const animal = findNearestTameableAnimal(world.wildAnimals || [], store.x[i], store.y[i]);
      if (animal) {
        animal.claimedBy = idOf(i);
        store.jobState[i] = JobState.SeekingAnimal;
        store.targetX[i] = animal.x; store.targetY[i] = animal.y;
        store._jobRef[i] = animal;
        continue;
      }
      continue;
    }

    if (state === JobState.SeekingFood || state === JobState.SeekingBed || state === JobState.SeekingRec
      || state === JobState.SeekingBuild || state === JobState.SeekingScrap || state === JobState.SeekingVehicle
      || state === JobState.SeekingAnimal) {
      const dx = store.targetX[i] - store.x[i];
      const dy = store.targetY[i] - store.y[i];
      const dist = Math.hypot(dx, dy);
      if (dist < ARRIVE_DIST) {
        if (state === JobState.SeekingVehicle) {
          const vehicle = store._jobRef[i];
          if (vehicle.driverId != null) { store.jobState[i] = JobState.Idle; continue; } // beaten to it
          boardVehicle(world, vehicle, idOf(i));
          store.jobState[i] = JobState.Driving;
          continue;
        }
        if (state === JobState.SeekingAnimal) {
          store.jobState[i] = JobState.Taming;
          continue;
        }
        store.jobState[i] = state === JobState.SeekingFood ? JobState.Eating
          : state === JobState.SeekingBed ? JobState.Sleeping
          : state === JobState.SeekingRec ? JobState.Recreating
          : state === JobState.SeekingBuild ? JobState.Building
          : JobState.Harvesting;
      } else {
        const speed = JOB_SPEED * (store.trait[i]?.speedMult ?? 1) * (store.isOnBreakAt(i) ? ON_BREAK_RATE_MULT : 1)
          * (world?.unrestActive ? UNREST_RATE_MULT : 1);
        store.x[i] += (dx / dist) * speed;
        store.y[i] += (dy / dist) * speed;
      }
      continue;
    }

    if (state === JobState.Eating) {
      const eatRoom = roomContaining(world.rooms, world.grid, store.x[i], store.y[i]);
      // Room-role gate (rooms.js's computeRoomStats/classifyRoomRole): the enclosed-room bonus
      // only applies to a room actually validated as a Dining Room (Food zone + >=1 table) --
      // an enclosed space with a Food zone but no table (or no room at all) still refills at the
      // baseline rate, same as open ground, rather than getting the bonus for four walls alone.
      const roomBonus = (eatRoom && eatRoom.role === RoomRole.DiningRoom && eatRoom.roleValid) ? ROOM_REFILL_BONUS : 1;
      const waterBonus = isWateredAt(structures, store.x[i], store.y[i]) ? WATER_REFILL_BONUS : 1;
      // Ethanol-fuel trucks (vehicles.js FUEL_TYPES.ethanol) brew clean fuel out of the
      // settlement's food surplus -- there's no bulk food-stockpile resource in this codebase
      // to drain directly, so the honest portable stand-in is a temporary hit to how fast the
      // Food zone actually refills hunger after each ethanol haul completes.
      const ethanolMult = world.ethanolPenaltyTimer > 0 ? ETHANOL_FOOD_REFILL_MULT : 1;
      store.hunger[i] = Math.min(1, store.hunger[i] + REFILL_RATE * roomBonus * waterBonus * ethanolMult);
      if (store.hunger[i] >= SATISFIED_THRESHOLD) store.jobState[i] = JobState.Idle;
      continue;
    }

    if (state === JobState.Sleeping) {
      const sleepRoom = roomContaining(world.rooms, world.grid, store.x[i], store.y[i]);
      // Same role gate as Eating above: only a validated Bedroom (Bedroom zone + >=1 bed) gets
      // the enclosed-room refill bonus -- four walls around an empty Bedroom zone is not a bed.
      const roomBonus = (sleepRoom && sleepRoom.role === RoomRole.Bedroom && sleepRoom.roleValid) ? ROOM_REFILL_BONUS : 1;
      store.rest[i] = Math.min(1, store.rest[i] + REFILL_RATE * roomBonus);
      if (store.rest[i] >= SATISFIED_THRESHOLD) store.jobState[i] = JobState.Idle;
      continue;
    }

    if (state === JobState.Recreating) {
      const recRoom = roomContaining(world.rooms, world.grid, store.x[i], store.y[i]);
      // Same role gate as Eating/Sleeping above: Recreation Room only requires the zone (see
      // classifyRoomRole's doc comment -- no furniture kind exists for it), so this mostly just
      // excludes an enclosed room with no Recreation zone at all from getting the bonus.
      const roomBonus = (recRoom && recRoom.role === RoomRole.RecreationRoom && recRoom.roleValid) ? ROOM_REFILL_BONUS : 1;
      const waterBonus = isWateredAt(structures, store.x[i], store.y[i]) ? WATER_REFILL_BONUS : 1;
      store.social[i] = Math.min(1, store.social[i] + REFILL_RATE * roomBonus * waterBonus * (store.trait[i]?.socialGainMult ?? 1));
      if (store.social[i] >= SATISFIED_THRESHOLD) store.jobState[i] = JobState.Idle;
      continue;
    }

    if (state === JobState.Building) {
      const bp = store._jobRef?.[i];
      if (!bp || bp.destroyed || !bp.underConstruction) { store.jobState[i] = JobState.Idle; continue; }
      const buildRateMult = (store.isOnBreakAt(i) ? ON_BREAK_RATE_MULT : 1) * (world?.unrestActive ? UNREST_RATE_MULT : 1);
      bp.buildProgress = Math.min(1, (bp.buildProgress || 0) + BUILD_RATE * (1 + store.skillConstruction[i]) * buildRateMult);
      if (bp.buildProgress >= 1) {
        bp.underConstruction = false;
        bp.claimedBy = null;
        store.skillConstruction[i] += BUILD_SKILL_GAIN * PASSION_GAIN_MULT[store.passionConstruction[i]];
        store.jobState[i] = JobState.Idle;
      }
      continue;
    }

    if (state === JobState.Harvesting) {
      const node = store._jobRef?.[i];
      if (!node || node.depleted) { store.jobState[i] = JobState.Idle; continue; }
      const harvestRateMult = (store.isOnBreakAt(i) ? ON_BREAK_RATE_MULT : 1) * (world?.unrestActive ? UNREST_RATE_MULT : 1);
      const take = Math.min(HARVEST_RATE * harvestRateMult, node.amount);
      node.amount -= take;
      onScrapGain?.(take);
      store.skillConstruction[i] += HARVEST_SKILL_GAIN * 0.2 * PASSION_GAIN_MULT[store.passionConstruction[i]];
      if (node.amount <= 0) node.depleted = true;
      if (node.depleted) store.jobState[i] = JobState.Idle;
      continue;
    }

    if (state === JobState.Driving) {
      const vehicle = store._jobRef?.[i];
      // vehicles.js clears driverId itself once the haul cycle completes and it's back home --
      // that's the signal this citizen's shift is over, not a countdown tracked here.
      if (!vehicle || vehicle.driverId !== idOf(i)) {
        store.jobState[i] = JobState.Idle;
        if (vehicle) { store.x[i] = vehicle.garageX; store.y[i] = vehicle.garageY; store.targetX[i] = vehicle.garageX; store.targetY[i] = vehicle.garageY; }
        continue;
      }
      store.x[i] = vehicle.x; store.y[i] = vehicle.y; // riding along, hidden (render.js skips Driving citizens)
      continue;
    }

    if (state === JobState.Taming) {
      const animal = store._jobRef?.[i];
      if (!animal) { store.jobState[i] = JobState.Idle; continue; }
      animal.tameTicks = (animal.tameTicks || 0) + 1;
      // Flat per-tick roll (see security.js's TAME_CHANCE_PER_TICK doc comment for why this isn't
      // scaled by a skill -- no "Animals" skill exists and FEATURE_RESEARCH.md says not to add
      // one just for this). world.rng keeps this reproducible under the same seed as everything
      // else in the sim. Gated on the same DOG_POPULATION_CAP tickDogBreeding respects -- a long
      // soak session could otherwise keep taming freshly-spawned wild animals past the cap even
      // with zero breeding, which defeats the point of having one at all.
      if (world.dogs.length < DOG_POPULATION_CAP && world?.rng && world.rng() < TAME_CHANCE_PER_TICK) {
        const idx = world.wildAnimals.indexOf(animal);
        if (idx >= 0) world.wildAnimals.splice(idx, 1);
        // Joins world.dogs unowned -- exactly like a bred pup (security.js's tickDogBreeding),
        // it just sits until assigned to a K9Handler via the existing roster.assign() system,
        // same as the starting dog in world.js's constructor.
        world.dogs.push({ ownerId: null, x: animal.x, y: animal.y, cooldown: 0 });
        store.jobState[i] = JobState.Idle;
        // No milestone existed for a successful taming before this -- worth logging like every
        // other "something notable just happened" event (refugee arrivals, region control, etc.
        // in world.js/worldmap.js), and it's the natural event-driven hook point for
        // metaprogress.js's Beast Tamer achievement rather than polling world.dogs every tick.
        if (world?.milestoneLog) {
          world.milestoneLog.push({ tick: world.currentTick, text: `${store.name[i]} tames a wild animal` });
          if (world.milestoneLog.length > 20) world.milestoneLog.shift();
        }
        checkTameAchievement();
        continue;
      }
      if (animal.tameTicks >= TAME_MAX_TICKS) {
        // Gave up -- the animal flees rather than staying claimed (and tameable) forever.
        const idx = world.wildAnimals.indexOf(animal);
        if (idx >= 0) world.wildAnimals.splice(idx, 1);
        store.jobState[i] = JobState.Idle;
        continue;
      }
      continue;
    }
  }
}


// ---- worldmap.js ----
// World map / conquest layer -- the RimWorld-style planet map with a Helldivers-2-style
// per-region control meter, plus RimWorld's "settlements feed each other resources" idea.
//
// Design decision (deliberate scope control): there is exactly ONE live, ticking SimWorld at a
// time -- the "active" region. Every other region is just a small record (control %, owned flag,
// and a cheap summary snapshot of how that settlement looked when you left it). Running 16 live
// sims simultaneously would multiply every perf/serialization concern in the project by 16 for
// very little gameplay gain, and the ask ("take over one area, settlements give each other
// resources, a control meter per section") is satisfied without it.
//
// This module holds a single module-level `worldMap` singleton rather than hanging off SimWorld,
// because the map has to OUTLIVE any individual SimWorld -- expanding to a new region throws the
// old SimWorld away and constructs a fresh one, and the conquest progress must survive that.

const GRID_COLS = 4;
const GRID_ROWS = 4;

// 16 region names, wasteland-flavored, ordered row-major to match the 4x4 layout.
const REGION_NAMES = [
  'Ashfall Reach', 'Rustwater', 'The Cinder Flats', 'Kestrel Basin',
  'Slagmouth', 'Verdigris Hollow', 'Tannery Row', 'Dead Signal Ridge',
  'Coalpit Yards', 'Marrowfield', 'The Long Quiet', 'Saltbreak',
  'Ironvale', 'Hollow Cistern', 'Greyspur', 'Last Ferry',
];

// Tuning. CONTROL_BASE is per-tick; the multipliers below typically land the total gain around
// 0.015-0.03/tick in a healthy colony, i.e. a region flips to fully-owned in roughly 4-7k ticks
// (~7-12 min at 10Hz), comfortably inside the 22-36k-tick hands-off survival baseline the
// director is balanced around, so conquest is achievable without trivializing the siege loop.
const CONTROL_BASE = 0.006;
// Scrap each already-owned region trickles into whichever region is currently active, per tick.
// This is the "settlements giving each other resources" half of the ask.
const TRICKLE_PER_OWNED_REGION = 0.02;

class Region {
  constructor(id, name, col, row) {
    this.id = id;
    this.name = name;
    this.col = col;
    this.row = row;
    this.neighbors = [];   // region ids, 4-directional adjacency
    this.control = 0;      // 0-100, the Helldivers-2-style liberation meter
    this.owned = false;    // control hit 100 at some point
    this.visited = false;  // has ever been the active region
    this.snapshot = null;  // cheap summary of that settlement's last known state
  }
}

class WorldMap {
  constructor(cols = GRID_COLS, rows = GRID_ROWS) {
    this.cols = cols;
    this.rows = rows;
    this.regions = [];
    for (let row = 0; row < rows; row++) {
      for (let col = 0; col < cols; col++) {
        const id = row * cols + col;
        this.regions.push(new Region(id, REGION_NAMES[id] ?? `Region ${id}`, col, row));
      }
    }
    // 4-directional adjacency over the grid -- doesn't need to be real geography, it just needs
    // to make "expand to an adjacent region" a meaningful spatial choice.
    for (const r of this.regions) {
      for (const [dc, dr] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        const c = r.col + dc, rr = r.row + dr;
        if (c < 0 || rr < 0 || c >= cols || rr >= rows) continue;
        r.neighbors.push(rr * cols + c);
      }
    }
    // Start in the middle-ish of the map so there are neighbors in every direction.
    this.activeId = 5;
    this.regions[this.activeId].visited = true;
    this.expansionCount = 0;
  }

  get active() { return this.regions[this.activeId] ?? null; }
  byId(id) { return this.regions[id] ?? null; }

  ownedCount() { return this.regions.reduce((n, r) => n + (r.owned ? 1 : 0), 0); }

  /** Regions you may expand into: not the active one, not already owned, adjacent to a region
   *  you hold (owned) or are currently standing in. */
  isExpandable(id) {
    const r = this.byId(id);
    if (!r || r.owned || id === this.activeId) return false;
    return r.neighbors.some(nid => nid === this.activeId || this.regions[nid].owned);
  }

  expandableIds() { return this.regions.filter(r => this.isExpandable(r.id)).map(r => r.id); }

  /** Freeze what the active region looked like before we walk away from it. */
  bankActive(world) {
    const r = this.active;
    if (!r || !world) return;
    r.snapshot = summarize(world);
  }

  /** Move the operation. Caller is responsible for constructing the fresh SimWorld -- this
   *  module deliberately doesn't import world.js (would be a circular import, and world.js
   *  imports this). */
  setActive(id) {
    if (!this.isExpandable(id)) return false;
    this.activeId = id;
    this.regions[id].visited = true;
    this.expansionCount++;
    return true;
  }

  serialize() {
    return {
      cols: this.cols, rows: this.rows, activeId: this.activeId,
      expansionCount: this.expansionCount,
      regions: this.regions.map(r => ({
        id: r.id, control: r.control, owned: r.owned, visited: r.visited, snapshot: r.snapshot,
      })),
    };
  }

  deserialize(json) {
    if (!json || !Array.isArray(json.regions)) return;
    this.activeId = json.activeId ?? this.activeId;
    this.expansionCount = json.expansionCount ?? 0;
    for (const rec of json.regions) {
      const r = this.byId(rec.id);
      if (!r) continue;
      r.control = rec.control ?? 0;
      r.owned = !!rec.owned;
      r.visited = !!rec.visited;
      r.snapshot = rec.snapshot ?? null;
    }
  }
}

function summarize(world) {
  let alive = 0;
  for (let i = 0; i < world.citizens.count; i++) if (world.citizens.isAliveAt(i)) alive++;
  let built = 0;
  for (const s of world.structures) if (!s.destroyed && !s.underConstruction) built++;
  return {
    tick: world.currentTick,
    waves: world.waveSpawner?.waveNumber ?? 0,
    citizens: alive,
    scrap: Math.round(world.scrap),
    structures: built,
    fallen: !!world.gameOver,
  };
}

// The one live map instance. Flat-bundle friendly (build.py strips import/export, so this is a
// plain global in game.bundle.js and can be poked directly from the console for verification).
const worldMap = new WorldMap();

/**
 * Called once per SimWorld.tick(). Two jobs:
 *  1. Push the active region's control meter up based on how the settlement is actually doing.
 *  2. Trickle scrap in from every OTHER fully-owned region (the resource-sharing part of the ask).
 * Additive only -- it never replaces or gates the existing scrap economy.
 */
function tickWorldMap(world) {
  const wm = worldMap;
  const r = wm.active;
  if (!r || !world) return;

  let alive = 0;
  for (let i = 0; i < world.citizens.count; i++) if (world.citizens.isAliveAt(i)) alive++;
  const waves = world.waveSpawner?.waveNumber ?? 0;

  if (!r.owned) {
    // Same *signals* colonyStrength() reads (population, banked scrap) plus waves-survived,
    // recombined for a different purpose. Deliberately NOT calling colonyStrength() itself:
    // that function is balance-critical for the director and other work depends on it staying
    // stable, so this reads the raw world state instead of coupling to it.
    const popTerm = 0.3 + Math.min(1, alive / 12);           // 0.3 .. 1.3
    const waveTerm = 1 + waves * 0.2;                        // holding ground is the main driver
    const scrapTerm = 1 + Math.min(1, Math.sqrt(Math.max(0, world.scrap)) / 20); // 1 .. 2
    const gain = CONTROL_BASE * popTerm * waveTerm * scrapTerm;
    r.control = Math.min(100, r.control + gain);
    if (r.control >= 100) {
      r.owned = true;
      world.milestoneLog.push({ tick: world.currentTick, text: `${r.name} is fully under your control` });
      if (world.milestoneLog.length > 20) world.milestoneLog.shift();
      // metaprogress.js's Conquest achievements -- checked right here, the instant a region flips
      // to owned, rather than polled from tick().
      checkConquestAchievements(wm);
    }
  } else {
    r.control = 100;
  }

  // Supply lines: every other region you hold ships scrap to wherever you're currently standing.
  let others = 0;
  for (const o of wm.regions) if (o.owned && o.id !== r.id) others++;
  if (others > 0) world.addScrap(others * TRICKLE_PER_OWNED_REGION, 'conquest');

  // Keep the map's view of the active region fresh so the overlay shows live numbers.
  if ((world.currentTick & 15) === 0) r.snapshot = summarize(world);
}


// ---- fire.js ----
// Fire spread crisis event -- ported/condensed from Prison Architect and SEA:R (see
// FEATURE_RESEARCH.md, both flag fire as a good siege-game crisis event; the mechanism itself
// isn't carceral, it's genre-neutral building-fire simulation, same as room detection).
//
// Ignition trigger (design choice): generators can spark a fire. This ties into the existing
// "generators are a tradeoff" mechanic already in world.js (power/turret boost vs. pollution
// cost) -- a generator malfunctioning and igniting something nearby is the same flavor of
// tradeoff, not a bolted-on unrelated system. An attacker/explosion-triggered fire was
// considered (also genre-appropriate) but generators-cause-fires was picked as more
// thematically consistent with what's already built.
//
// Extinguish design (deliberately simple, documented per the task brief): no dedicated
// firefighting job or citizen mechanic. Fire is self-limiting -- it only spreads to unburned
// flammable neighbors within a short range, each burning structure is destroyed (fully
// consumed) once its health reaches 0, and a fire with no flammable, unburned neighbor left in
// range simply has nothing further to spread to. This keeps the system cheap and safe against
// runaway spread (see tuning constants below) without needing a new citizen job type; a
// citizen-firefighter mechanic would be a reasonable follow-up but isn't needed for a rare,
// occasional threat.

// Flammability rule: wood/cloth/paper-ish furniture and building material catches; stone/metal/
// electrical things (turrets, generators, tesla coils, floodlights, watchtowers, fences -- "wire"
// per the task brief) do not.
//
// 'wall' is deliberately excluded despite being wood-ish and named in the task brief: this
// codebase's wall Structure isn't a durable, ongoing entity -- world.js's tick() folds any
// non-under-construction 'wall' into permanent, health-less grid terrain and drops the
// Structure object the very tick after it finishes building (see the `this.structures =
// this.structures.filter(...)` block), regardless of health/destroyed/onFire. An ignited wall
// would just silently lose its onFire flag into the void the same tick, never visibly burning
// down -- confirmed via a manual browser repro before settling on this exclusion. Beds/tables/
// doors don't have that lifecycle quirk; they stay real Structure objects for their whole life.
const FLAMMABLE_KINDS = new Set(['bed', 'table', 'door']);

// Tuned conservatively per the task brief: "a rare, occasional threat is better than one that
// dominates every playthrough". Scaled per-generator (not a flat per-tick roll) so more
// generators genuinely mean more risk -- consistent with pollution also scaling per-generator
// in world.js tick(). At 10 Hz, one generator rolls roughly once every ~9 real-world minutes on
// average before it sparks, and even then only catches if something flammable is nearby.
const IGNITION_CHANCE_PER_GENERATOR = 0.00003;
// Coal (SEA:R multi-source power economy): combustion-based like the plain generator, but
// dirtier -- rolls at roughly double the plain generator's spark chance, consistent with it also
// producing roughly double the pollution-per-tick in world.js. Wind/solar have no combustion
// process at all and deliberately never appear in tickFireIgnition below.
const IGNITION_CHANCE_PER_COAL_GENERATOR = 0.00006;
const IGNITION_SEARCH_RADIUS = 4; // generator sparks something flammable within this range

const FIRE_DAMAGE_PER_TICK = 0.01; // burning structure's health drains at this rate until destroyed
const SPREAD_CHECK_INTERVAL = 30; // ticks between spread rolls -- "a few ticks per cell" pacing
const SPREAD_RADIUS = 1.6; // reaches orthogonal + diagonal neighbor cells
const SPREAD_CHANCE = 0.18; // per eligible unburned neighbor, per check

function isFlammable(kind) {
  return FLAMMABLE_KINDS.has(kind);
}

function igniteStructure(s) {
  s.onFire = true;
  s.fireTicks = 0;
}

// Natural trigger: active (built, undestroyed) generators can spark a nearby flammable
// structure. Call once per tick from SimWorld.tick().
function tickFireIgnition(structures, rng) {
  for (const g of structures) {
    if (g.kind !== 'generator' && g.kind !== 'generator_coal') continue;
    if (g.destroyed || g.underConstruction) continue;
    const chance = g.kind === 'generator_coal' ? IGNITION_CHANCE_PER_COAL_GENERATOR : IGNITION_CHANCE_PER_GENERATOR;
    if (rng() >= chance) continue;

    let target = null;
    let candidateCount = 0;
    for (const s of structures) {
      if (!isFlammable(s.kind) || s.destroyed || s.underConstruction || s.onFire) continue;
      if (Math.hypot(s.x - g.x, s.y - g.y) > IGNITION_SEARCH_RADIUS) continue;
      candidateCount++;
      // reservoir sampling of size 1 -- picks a uniformly random eligible candidate without
      // needing to materialize an array of them every ignition roll
      if (rng() < 1 / candidateCount) target = s;
    }
    if (target) igniteStructure(target);
  }
}

// Damages every burning structure each tick (destroying it once fully consumed) and, every
// SPREAD_CHECK_INTERVAL ticks, rolls to spread to nearby unburned flammable structures. Fire is
// purely self-limiting -- see file header for why there's no firefighting mechanic.
function tickFire(structures, rng) {
  for (const s of structures) {
    if (!s.onFire || s.destroyed) continue;

    s.fireTicks = (s.fireTicks || 0) + 1;
    s.health -= FIRE_DAMAGE_PER_TICK;
    if (s.health <= 0) {
      s.health = 0;
      s.destroyed = true;
      s.onFire = false; // fully consumed -- nothing left to burn
      continue;
    }

    if (s.fireTicks % SPREAD_CHECK_INTERVAL === 0) {
      for (const other of structures) {
        if (other === s || !isFlammable(other.kind)) continue;
        if (other.destroyed || other.underConstruction || other.onFire) continue;
        if (Math.hypot(other.x - s.x, other.y - s.y) > SPREAD_RADIUS) continue;
        if (rng() < SPREAD_CHANCE) igniteStructure(other);
      }
    }
  }
}


// ---- weather.js ----
// RimWorld-style weather + one-off random events (see FEATURE_RESEARCH.md's RimWorld section,
// "Events" category: weather, extreme weather, wanderers, blight, infestation -- all called out
// there as genre-neutral simulation tech, same "port the mechanism, not the flavor" framing as
// room detection/fire). Weather cycles on a simple weighted random timer; each state hooks into
// an existing numeric knob rather than adding a parallel system, same philosophy as fire.js's
// "modest, real, not dominating" tuning. Events are one-off rolls that post to
// world.milestoneLog (existing event log, see world.js) and fire world.onRandomEvent (the same
// optional-callback pattern as onBuildComplete/onWaveIncoming) so main.js can also surface them
// as a toast.


const WeatherKind = Object.freeze({
  Clear: 'Clear', Rain: 'Rain', Cold: 'Cold', Heatwave: 'Heatwave',
});

// Weighted so Clear is the common case -- weather is flavor + a modest modifier, not a constant
// stream of debuffs.
const WEATHER_WEIGHTS = [
  [WeatherKind.Clear, 5],
  [WeatherKind.Rain, 2],
  [WeatherKind.Cold, 1.5],
  [WeatherKind.Heatwave, 1.5],
];

const MIN_WEATHER_TICKS = 600;  // ~1 min at 10Hz
const MAX_WEATHER_TICKS = 1800; // ~3 min at 10Hz

function rollDuration(rng) {
  return MIN_WEATHER_TICKS + Math.floor(rng() * (MAX_WEATHER_TICKS - MIN_WEATHER_TICKS));
}

function pickWeather(rng, exclude) {
  const pool = WEATHER_WEIGHTS.filter(([k]) => k !== exclude);
  const total = pool.reduce((sum, [, w]) => sum + w, 0);
  let roll = rng() * total;
  for (const [k, w] of pool) {
    roll -= w;
    if (roll <= 0) return k;
  }
  return pool[pool.length - 1][0];
}

/** Call once from SimWorld's constructor to seed initial state. */
function initWeather(world) {
  world.weather = WeatherKind.Clear;
  world._weatherTimer = rollDuration(world.rng);
}

// Rain: citizens amble slower underfoot -- hooks into tickWander's existing speed parameter
// (world.js passes this straight through), rather than a parallel movement system.
const RAIN_WANDER_SPEED_MULT = 0.8;

function weatherWanderSpeedMult(weather) {
  return weather === WeatherKind.Rain ? RAIN_WANDER_SPEED_MULT : 1;
}

// Cold/Heatwave: modest *extra* need decay on top of whatever tickNeedsAndMood already applied
// this tick, asymmetric by axis (cold -> hungrier faster burning calories to stay warm; heat ->
// harder to rest) so the two extremes read as mechanically distinct, not just palette swaps of
// each other. Being indoors in any enclosed room (rooms.js flood-fill) cuts the penalty most of
// the way back to normal, same "shelter matters" logic either direction -- this is the promised
// "reduce it if citizens are indoors" behavior, extended symmetrically to heat since a roof is
// shelter from both extremes.
const COLD_HUNGER_EXTRA_OUTDOOR = 0.8; // fraction of HUNGER_DECAY added on top, outdoors
const COLD_HUNGER_EXTRA_INDOOR = 0.15;
const HEAT_REST_EXTRA_OUTDOOR = 0.8; // fraction of REST_DECAY added on top, outdoors
const HEAT_REST_EXTRA_INDOOR = 0.15;

function tickWeatherCitizenEffects(world) {
  const weather = world.weather;
  if (weather !== WeatherKind.Cold && weather !== WeatherKind.Heatwave) return;

  const store = world.citizens;
  for (let i = 0; i < store.count; i++) {
    if (!store.isAliveAt(i) || store.isDownedAt(i)) continue;
    const indoors = !!roomContaining(world.rooms, world.grid, store.x[i], store.y[i]);

    if (weather === WeatherKind.Cold) {
      const extra = HUNGER_DECAY * (indoors ? COLD_HUNGER_EXTRA_INDOOR : COLD_HUNGER_EXTRA_OUTDOOR);
      store.hunger[i] = Math.max(0, store.hunger[i] - extra);
    } else {
      const extra = REST_DECAY * (indoors ? HEAT_REST_EXTRA_INDOOR : HEAT_REST_EXTRA_OUTDOOR);
      store.rest[i] = Math.max(0, store.rest[i] - extra);
    }
  }
}

/** Advances the weather timer and, on expiry, rolls a new (different) weather state; then
 *  applies the current weather's per-tick citizen effect (every tick, not just on change --
 *  Cold/Heatwave's extra decay is a continuous effect for as long as that state holds). Call
 *  once per tick from SimWorld.tick(), same pattern as the other periodic systems there. */
function tickWeather(world) {
  if (world._weatherTimer == null) initWeather(world);
  world._weatherTimer--;
  if (world._weatherTimer <= 0) {
    const next = pickWeather(world.rng, world.weather);
    world.weather = next;
    world._weatherTimer = rollDuration(world.rng);
    const text = `Weather turns to ${next}`;
    world.milestoneLog.push({ tick: world.currentTick, text });
    if (world.milestoneLog.length > 20) world.milestoneLog.shift();
    world.onRandomEvent?.(text);
  }

  tickWeatherCitizenEffects(world);
}

// ---------------------------------------------------------------- one-off random events
// Wanderer-joins and blight, per FEATURE_RESEARCH.md's RimWorld "Events" list. Infestation's
// genre-neutral equivalent (a burst of wild resource-guarding creatures) was scoped out of this
// pass -- it would need a new attacker-adjacent entity type wired through siege.js/render.js,
// which is a much bigger surface than a numeric-knob event, and this pass prioritized doing a
// solid job on the other two over a half-built third. Left as a natural follow-up.

const EVENT_CHECK_INTERVAL = 500; // ticks between event rolls
const EVENT_CHANCE = 0.06; // odds per check that *some* event fires -- rare, not spammy
const EVENT_WEIGHTS = [
  ['wanderer', 1],
  ['blight', 1],
];

function tickRandomEvents(world) {
  if (world.currentTick % EVENT_CHECK_INTERVAL !== 0) return;
  if (world.rng() >= EVENT_CHANCE) return;

  const total = EVENT_WEIGHTS.reduce((sum, [, w]) => sum + w, 0);
  let roll = world.rng() * total;
  let kind = EVENT_WEIGHTS[0][0];
  for (const [k, w] of EVENT_WEIGHTS) {
    roll -= w;
    if (roll <= 0) { kind = k; break; }
  }

  if (kind === 'wanderer') tryWandererEvent(world);
  else tryBlightEvent(world);
}

/** Spawns a new citizen near the settlement center using an unused name from the shared name
 *  pool (world._namePool -- see world.js's STARTER_NAMES, extended with extra names beyond the
 *  starting 24 so a long soak test doesn't run out). Returns true if a wanderer actually joined. */
// Population cap, distinct from the raw CitizenStore capacity check below: this event was
// firing with no ceiling of its own and, stacked with world.js's separate Refugee Wagon
// mechanic (which IS gated, only replenishing losses back up to ~90% of starting population),
// drove hands-off soak tests from 24 to 40+ citizens in ~10k ticks with zero combat losses --
// a real regression, since colonyStrength() scales directly off alive citizen count and no
// other system was scaling up to match. Cap wanderers to keep a healthy colony from ballooning;
// Refugee Wagon remains the mechanism for recovering from actual losses.
const WANDERER_POPULATION_CAP_MULT = 1.15;

function tryWandererEvent(world) {
  const cap = (world.startingCitizenCount || 24) * WANDERER_POPULATION_CAP_MULT;
  if (world.citizens.count >= cap) return false;

  const pool = world._namePool || [];
  const used = new Set();
  for (let i = 0; i < world.citizens.count; i++) used.add(world.citizens.name[i]);
  const available = pool.filter(n => !used.has(n));
  if (available.length === 0) return false;

  const name = available[Math.floor(world.rng() * available.length)];
  const cx = Math.max(1, Math.min(world.width - 2, world.width / 2 + (world.rng() - 0.5) * 6));
  const cy = Math.max(1, Math.min(world.height - 2, world.height / 2 + (world.rng() - 0.5) * 6));
  const idx = world.citizens.spawn(name, cx, cy, world.rng);
  if (idx < 0) return false; // at capacity

  world._citizenIds.push(world.citizens.id[idx]);
  const text = `A wanderer named ${name} joins the settlement`;
  world.milestoneLog.push({ tick: world.currentTick, text });
  if (world.milestoneLog.length > 20) world.milestoneLog.shift();
  world.onRandomEvent?.(text);
  return true;
}

const BLIGHT_LOSS_MIN = 0.4; // fraction of remaining yield destroyed
const BLIGHT_LOSS_MAX = 0.7;

/** Picks a random non-depleted resource node and destroys a chunk of its remaining yield (can
 *  fully deplete it). Returns true if a node was actually hit. */
function tryBlightEvent(world) {
  const candidates = world.resourceNodes.filter(n => !n.depleted && n.amount > 0);
  if (candidates.length === 0) return false;

  const node = candidates[Math.floor(world.rng() * candidates.length)];
  const frac = BLIGHT_LOSS_MIN + world.rng() * (BLIGHT_LOSS_MAX - BLIGHT_LOSS_MIN);
  node.amount = Math.max(0, node.amount - node.amount * frac);
  if (node.amount < 1) { node.amount = 0; node.depleted = true; }

  const text = node.depleted
    ? 'Blight wipes out a resource node'
    : "Blight reduces a resource node's yield";
  world.milestoneLog.push({ tick: world.currentTick, text });
  if (world.milestoneLog.length > 20) world.milestoneLog.shift();
  world.onRandomEvent?.(text);
  return true;
}


// ---- grading.js ----
// Non-carceral reframe of Prison Architect's 4-axis Grading tab (Punishment/Reform/Security/
// Health), per FEATURE_RESEARCH.md's synthesis note: same aggregate-scoring pattern, axes
// renamed to fit a settlement that isn't a prison -- Safety/Wellbeing/Sustainability/Cohesion.
//
// Purely a read-only reporting layer: computed periodically (see GRADING_INTERVAL_TICKS) and
// stored on world.grading for the UI to read. Every axis is derived from state the sim already
// tracks elsewhere (citizens.js/siege.js/relationships.js/world.js) -- nothing new is simulated
// here. Never feeds back into director.js's colonyStrength()/wave difficulty; if you're tempted
// to read world.grading from director.js, don't -- that would make this a balance lever instead
// of a reporting layer.

const GRADING_INTERVAL_TICKS = 30; // ~3s at 10Hz -- feels live without recomputing every tick

const DEFENSE_KINDS = new Set(['turret', 'fence', 'trap']);
const RECENT_EVENT_WINDOW_TICKS = 3000; // ~5 min at 10Hz -- "recent" friendship-event frequency for Cohesion

function clampScore(v) {
  if (!Number.isFinite(v)) return 0;
  return Math.max(0, Math.min(100, v));
}

// Safety: functional defenses (turret/fence/trap, powered turrets count extra) offset by
// cumulative citizen losses, currently-downed citizens, and how many attackers are on the field
// right now -- the same signals siege.js/world.js already track, just recombined for reporting.
function computeSafety(world) {
  let functionalDefense = 0;
  for (const s of world.structures) {
    if (s.destroyed || s.underConstruction) continue;
    if (!DEFENSE_KINDS.has(s.kind)) continue;
    functionalDefense += isPowered(world.structures, s.x, s.y) ? 1.2 : 1;
  }
  const defenseCoverage = Math.min(1, functionalDefense / 10);

  let aliveCitizens = 0, downedCitizens = 0;
  for (let i = 0; i < world.citizens.count; i++) {
    if (!world.citizens.isAliveAt(i)) continue;
    aliveCitizens++;
    if (world.citizens.isDownedAt(i)) downedCitizens++;
  }
  const totalEver = Math.max(1, world.citizens.count);
  const deathRatio = Math.max(0, (totalEver - aliveCitizens) / totalEver);
  const downedRatio = aliveCitizens > 0 ? downedCitizens / aliveCitizens : 0;

  let aliveAttackers = 0;
  for (let i = 0; i < world.attackers.count; i++) if (world.attackers.isAliveAt(i)) aliveAttackers++;
  const attackerPenalty = Math.min(40, aliveAttackers * 3);

  return clampScore(45 * defenseCoverage + 35 * (1 - deathRatio) + 20 * (1 - downedRatio) - attackerPenalty);
}

// Wellbeing: straight average of hunger/rest/social/mood across the living population
// (citizens.js's CitizenStore fields) -- no derived signal needed, this is the axis the data
// most directly supports.
function computeWellbeing(world) {
  const c = world.citizens;
  let aliveCount = 0, sum = 0;
  for (let i = 0; i < c.count; i++) {
    if (!c.isAliveAt(i)) continue;
    aliveCount++;
    sum += (c.hunger[i] + c.rest[i] + c.social[i] + c.mood[i]) / 4;
  }
  if (aliveCount === 0) return 0;
  return clampScore((sum / aliveCount) * 100);
}

// Sustainability: world.pollution and world.nuclearWaste each mapped through a saturating curve
// (100 at 0, asymptoting toward 0 as the hazard grows without bound -- both accrue unboundedly
// per tick per siege.js/world.js, so a hard-clamped linear score would floor out almost
// immediately), blended with a banked-scrap trend term so a settlement whose economy is
// currently shrinking scores worse than one that's merely sitting still.
function computeSustainability(world) {
  const pollutionScore = 100 / (1 + world.pollution / 50);
  const nuclearScore = 100 / (1 + (world.nuclearWaste || 0) / 20);

  const prevScrap = world._gradingPrevScrap ?? world.scrap;
  const delta = world.scrap - prevScrap;
  world._gradingPrevScrap = world.scrap;
  const trendScore = clampScore(50 + delta);

  return clampScore(0.4 * pollutionScore + 0.3 * nuclearScore + 0.3 * trendScore);
}

// Cohesion: relationships.js's RelationshipWeb tracks a friendship value per proximate pair and
// logs an event when a pair crosses the "friends" threshold -- averaged here, plus how many such
// events landed recently. Blended with average social need (citizens.js) rather than gated
// behind a nonempty friendship map, so a brand-new colony (no friendships formed yet) still
// reports a meaningful score instead of a hard 0.
function computeCohesion(world, avgSocialNeed) {
  const web = world.relationships;
  let friendshipSum = 0, friendshipCount = 0;
  for (const v of web.friendship.values()) { friendshipSum += v; friendshipCount++; }
  const avgFriendship = friendshipCount > 0 ? friendshipSum / friendshipCount : 0;

  // events is append-ordered ascending by tick, so walking from the end and stopping at the
  // first too-old entry is enough -- no need to scan the whole log every time this runs.
  let recentEvents = 0;
  for (let i = web.events.length - 1; i >= 0; i--) {
    if (world.currentTick - web.events[i].tick > RECENT_EVENT_WINDOW_TICKS) break;
    recentEvents++;
  }
  const eventScore = Math.min(1, recentEvents / 6);

  return clampScore(40 * avgFriendship + 30 * eventScore + 30 * avgSocialNeed);
}

/** Recompute world.grading = {safety, wellbeing, sustainability, cohesion}, each 0-100. Called
 *  from world.js's tick() every GRADING_INTERVAL_TICKS -- cheap (single pass over citizens/
 *  structures/attackers, same cost class as the room-detection wall-signature gate) but still
 *  not worth doing every single tick for a number nothing else reads synchronously. */
function computeGrading(world) {
  const c = world.citizens;
  let aliveCount = 0, socialSum = 0;
  for (let i = 0; i < c.count; i++) {
    if (!c.isAliveAt(i)) continue;
    aliveCount++;
    socialSum += c.social[i];
  }
  const avgSocialNeed = aliveCount > 0 ? socialSum / aliveCount : 0;

  world.grading = {
    safety: computeSafety(world),
    wellbeing: computeWellbeing(world),
    sustainability: computeSustainability(world),
    cohesion: computeCohesion(world, avgSocialNeed),
  };
}


// ---- audio.js ----
// Procedural sound effects via the Web Audio API. No audio files anywhere in this project --
// every cue here is synthesized at runtime with oscillators/noise + gain envelopes, matching the
// hand-drawn-Canvas2D "no external assets" rule that also applies to art.
//
// Presentation-layer concern only: this module is never imported by the simulation modules
// (world.js/siege.js/jobs.js). Instead main.js wires SimWorld's onXxx callback hooks to the
// play* functions below, the same callback-injection pattern those modules already use for
// onScrap. That keeps the sim decoupled from anything audio/DOM-related.

let ctx = null;
let masterGain = null;
let muted = false;

// Continuous volume level (0..1), independent of the mute toggle -- the two combine as
// `muted ? 0 : volume` everywhere the master gain is set. Persisted to localStorage so it
// survives a reload; mute intentionally is NOT persisted (matches its previous session-only
// behaviour, and a silently-still-muted reload would be a confusing surprise).
const VOLUME_KEY = 'settlement-defense-volume';
let volume = 0.5;
try {
  const stored = Number.parseFloat(localStorage.getItem(VOLUME_KEY));
  if (Number.isFinite(stored)) volume = Math.max(0, Math.min(1, stored));
} catch { /* localStorage unavailable -- fall back to the 0.5 default */ }

// Browsers refuse to start an AudioContext (or keep it running) until a user gesture has
// happened on the page -- creating one before that is fine, it just starts 'suspended' and
// produces no sound until resumed. We lazily create on first play*() call and attempt a
// resume() on every subsequent user gesture (both are cheap/idempotent), so playback quietly
// "just works" the moment the browser allows it instead of the caller needing to know about
// AudioContext lifecycle at all.
function getCtx() {
  if (ctx) return ctx;
  const Ctor = window.AudioContext || window.webkitAudioContext;
  if (!Ctor) return null; // no Web Audio support -- degrade to silent, never throw
  try {
    ctx = new Ctor();
    masterGain = ctx.createGain();
    masterGain.gain.value = muted ? 0 : volume;
    masterGain.connect(ctx.destination);
  } catch {
    ctx = null;
  }
  return ctx;
}

function unlock() {
  const c = getCtx();
  if (!c) return;
  if (c.state === 'suspended') c.resume().catch(() => {});
}
// Any of these count as "a user gesture happened" -- attach once at module load so callers
// never have to think about unlocking explicitly.
['pointerdown', 'keydown'].forEach((evt) => window.addEventListener(evt, unlock, { passive: true }));

function isMuted() { return muted; }

function setMuted(value) {
  muted = value;
  if (masterGain) masterGain.gain.value = muted ? 0 : volume;
}

function toggleMute() {
  setMuted(!muted);
  return muted;
}

function getVolume() { return volume; }

/** Console/soak-test verification hook: the ACTUAL live GainNode value, not just the stored
 *  `volume` number -- lets a test confirm the master gain really was scaled, not merely that the
 *  setter ran. Returns null if no AudioContext exists yet (nothing has played a sound this
 *  session). */
function getMasterGainValue() { return masterGain ? masterGain.gain.value : null; }

/** Set the continuous volume level (0..1, clamped) and persist it. Does not touch `muted` --
 *  dragging the slider while muted updates the stored level but stays silent until unmuted,
 *  same as any normal OS volume slider. */
function setVolume(value) {
  volume = Math.max(0, Math.min(1, value));
  try { localStorage.setItem(VOLUME_KEY, String(volume)); } catch { /* best effort */ }
  if (masterGain && !muted) masterGain.gain.value = volume;
}

// ---------------------------------------------------------------- low-level synth helpers

function tone({ freq, freqEnd = null, start = 0, duration = 0.15, type = 'sine', peakGain = 0.22 }) {
  const c = getCtx();
  if (!c) return; // no Web Audio in this environment -- silently no-op
  try {
    const t0 = c.currentTime + start;
    const osc = c.createOscillator();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t0);
    if (freqEnd != null) osc.frequency.linearRampToValueAtTime(freqEnd, t0 + duration);
    const g = c.createGain();
    // Quick linear attack then exponential decay -- avoids the click/pop of a hard on/off edge.
    g.gain.setValueAtTime(0, t0);
    g.gain.linearRampToValueAtTime(peakGain, t0 + Math.min(0.01, duration * 0.3));
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + duration);
    osc.connect(g);
    g.connect(masterGain);
    osc.start(t0);
    osc.stop(t0 + duration + 0.03);
  } catch {
    // Never let a synthesis failure bubble into the game loop.
  }
}

function noiseBurst({ duration = 0.15, filterFreq = 1200, filterType = 'lowpass', peakGain = 0.25 }) {
  const c = getCtx();
  if (!c) return;
  try {
    const bufferSize = Math.max(1, Math.floor(c.sampleRate * duration));
    const buffer = c.createBuffer(1, bufferSize, c.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) data[i] = Math.random() * 2 - 1;
    const src = c.createBufferSource();
    src.buffer = buffer;
    const filter = c.createBiquadFilter();
    filter.type = filterType;
    filter.frequency.value = filterFreq;
    const g = c.createGain();
    const t0 = c.currentTime;
    g.gain.setValueAtTime(peakGain, t0);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + duration);
    src.connect(filter);
    filter.connect(g);
    g.connect(masterGain);
    src.start(t0);
    src.stop(t0 + duration + 0.03);
  } catch {
    // ditto
  }
}

// ---------------------------------------------------------------- debounce for high-frequency cues
// Turret fire and kills can both happen many times in the same tick during a big wave (several
// turrets/tesla chains/guards all resolving at once) -- without a cap that's a wall of noise, not
// a sound effect. A simple "don't replay within N ms" gate per cue is enough since ticks run at
// 10Hz (100ms apart) already.
const lastPlayed = { fire: 0, kill: 0, downed: 0 };
function throttled(key, minGapMs, fn) {
  const now = performance.now();
  if (now - lastPlayed[key] < minGapMs) return;
  lastPlayed[key] = now;
  fn();
}

// ---------------------------------------------------------------- public cues

// Blueprint finished construction: short cheerful two-note ascending blip.
function playBuildComplete() {
  tone({ freq: 660, duration: 0.09, type: 'sine', peakGain: 0.18 });
  tone({ freq: 880, duration: 0.14, type: 'sine', peakGain: 0.2, start: 0.09 });
}

// Turret/tesla firing -- cheap, throttled low blip so a full wave doesn't turn into static.
function playTurretFire() {
  throttled('fire', 90, () => {
    tone({ freq: 190, freqEnd: 110, duration: 0.06, type: 'square', peakGain: 0.14 });
  });
}

// Attacker killed -- a short descending "thud", noise + tone layered.
function playKill() {
  throttled('kill', 80, () => {
    noiseBurst({ duration: 0.1, filterFreq: 900, peakGain: 0.2 });
    tone({ freq: 300, freqEnd: 110, duration: 0.14, type: 'sawtooth', peakGain: 0.16 });
  });
}

// Wave incoming alert -- two low ominous pulses, not throttled (one push per wave already).
function playWaveAlert() {
  tone({ freq: 150, duration: 0.22, type: 'sawtooth', peakGain: 0.2 });
  tone({ freq: 165, duration: 0.28, type: 'sawtooth', peakGain: 0.2, start: 0.28 });
}

// Citizen downed/died -- a sad descending sweep, throttled since a bad tick can down/kill
// several citizens at once against a wave.
function playCitizenDowned() {
  throttled('downed', 120, () => {
    tone({ freq: 420, freqEnd: 160, duration: 0.32, type: 'sine', peakGain: 0.18 });
  });
}


// ---- metaprogress.js ----
// Cross-run meta-progression -- lifetime stats and achievements that survive every restart,
// game-over, and "Quit to Title", independent of any single settlement's save data.
//
// This is deliberately a FOURTH, independent localStorage key (META_KEY below), alongside
// main.js's SAVE_KEY / AUTOSAVE_KEY / SLOTS_KEY -- same reasoning as those three not sharing a
// key with each other (see main.js's header comments on each): wiping or overwriting a save must
// never touch lifetime totals, and finishing/losing a run must never touch save data. It is also
// independent of world.js's `world.finance` (a per-run budget ledger) and grading.js's live
// per-run Safety/Wellbeing/Sustainability/Cohesion score -- both of those die with the SimWorld on
// game-over/restart/quit-to-title; everything in this file is the opposite, it's what's left AFTER
// the SimWorld is gone.
//
// Two kinds of state:
//  - LIFETIME STATS: running totals that only ever grow, across every settlement ever played on
//    this browser (gamesPlayed, longestSurvivalTicks/Waves, mostCitizensAlive, lifetime kills,
//    lifetime scrap earned, the set of generator kinds ever built).
//  - ACHIEVEMENTS: a fixed list (see ACHIEVEMENTS below), each unlocked at most once and never
//    re-locked. `checked against real numbers in the game as of this writing -- see the doc
//    comment on each achievement below for where its threshold comes from (research.js's node
//    count, worldmap.js's region count, the five generator_* structure kinds, CitizenStore's
//    capacity).
//
// Hook points are event-driven, not polled every tick -- each check function below is called from
// an already-existing event/milestone site (world.js's wave-complete and game-over blocks,
// worldmap.js's region-owned flip, main.js's successful tryResearch(), jobs.js's taming
// completion, and main.js's onBuildComplete structure-finished hook), never from inside
// SimWorld.tick()'s main body itself.

const META_KEY = 'settlement-defense-meta';

// Five generator variants a colony can build (see research.js's 'scrap_power'/'alternative_power'/
// 'fission' nodes for where each unlocks) -- the full set as of this writing.
const GENERATOR_KINDS = ['generator', 'generator_coal', 'generator_wind', 'generator_solar', 'generator_nuclear'];

/** @type {{id:string,name:string,desc:string}[]} */
const ACHIEVEMENTS = [
  {
    id: 'survive_10k', name: 'Iron Grip',
    desc: 'Survive 10,000 ticks (~1000s at 1x speed) in a single settlement.',
  },
  {
    id: 'wave_20', name: 'Weathered the Storm',
    desc: 'Reach Wave 20 in a single settlement.',
  },
  {
    id: 'full_research', name: 'Master Engineers',
    // research.js's RESEARCH_NODES is 14 entries as of this writing (3 free "core" nodes shown
    // for legibility + 11 gated ones) -- "fully researched" means every one of them, not just the
    // gated tier, so the panel can legitimately say 100%.
    desc: 'Unlock every technology in the research tree.',
  },
  {
    id: 'conquest_3', name: 'Warlord',
    // worldmap.js's WorldMap is a fixed 4x4 = 16-region grid; 3 owned is an early-mid-campaign
    // milestone, not the whole map.
    desc: 'Control 3 regions on the Conquest Map.',
  },
  {
    id: 'conquest_all', name: 'One Wasteland, Under You',
    desc: 'Control all 16 regions on the Conquest Map.',
  },
  {
    id: 'tame_animal', name: 'Beast Tamer',
    desc: 'Successfully tame a wild animal.',
  },
  {
    id: 'all_generators', name: 'Power Broker',
    desc: 'Build every generator variant at least once, across any settlement (plain, coal, wind, solar, nuclear).',
  },
  {
    id: 'pop_30', name: 'Boomtown',
    desc: 'Have 30 citizens alive in one settlement at the same time.',
  },
  {
    id: 'games_10', name: 'Seasoned Settler',
    desc: 'Play 10 settlements to their end (game over or a fresh restart both count).',
  },
  {
    id: 'kills_100', name: 'Perimeter Held',
    desc: 'Kill 100 attackers, total, across every settlement.',
  },
  {
    id: 'scrap_5000', name: 'Scrap Baron',
    desc: 'Earn 5,000 scrap, total, across every settlement.',
  },
];
const ACHIEVEMENTS_BY_ID = Object.fromEntries(ACHIEVEMENTS.map(a => [a.id, a]));

function defaultMeta() {
  return {
    gamesPlayed: 0,
    longestSurvivalTicks: 0,
    longestSurvivalWaves: 0,
    mostCitizensAlive: 0,
    totalAttackersKilled: 0,
    totalScrapEarned: 0,
    builtGeneratorKinds: [], // lifetime set of GENERATOR_KINDS ever completed, any settlement
    achievements: {},        // id -> unix ms timestamp of unlock, absent/false = locked
  };
}

let meta = null;
// Set by main.js so an unlock can surface as a toast; left null so this module never assumes a
// UI exists (e.g. under a future headless/test harness).
let onUnlock = null;

function setAchievementUnlockedCallback(fn) { onUnlock = fn; }

function _loadMeta() {
  if (meta) return meta;
  try {
    const raw = localStorage.getItem(META_KEY);
    const parsed = raw ? JSON.parse(raw) : null;
    meta = { ...defaultMeta(), ...(parsed || {}) };
    meta.achievements = { ...(parsed && parsed.achievements) };
    meta.builtGeneratorKinds = Array.isArray(parsed && parsed.builtGeneratorKinds) ? parsed.builtGeneratorKinds : [];
  } catch (err) {
    console.error('[MetaProgress] Lifetime stats corrupt, resetting:', err);
    meta = defaultMeta();
  }
  return meta;
}

function _persistMeta() {
  try {
    localStorage.setItem(META_KEY, JSON.stringify(meta));
  } catch (err) {
    console.error('[MetaProgress] Failed to write lifetime stats (storage full?):', err);
  }
}

/** Read-only snapshot for the Statistics/Achievements panel. Always the live object -- callers
 *  must not mutate it directly, everything here goes through the functions below. */
function getMeta() { return _loadMeta(); }

function isAchievementUnlocked(id) { return !!_loadMeta().achievements[id]; }

function _unlockAchievement(id) {
  const m = _loadMeta();
  if (m.achievements[id]) return false; // never re-locked, never double-fires the toast
  if (!ACHIEVEMENTS_BY_ID[id]) return false;
  m.achievements[id] = Date.now();
  _persistMeta();
  onUnlock?.(ACHIEVEMENTS_BY_ID[id]);
  return true;
}

// ---------------------------------------------------------------- event-driven check functions
// Each of these is called from exactly the existing milestone/event site named in its comment --
// never from inside the tick loop's main body -- so an achievement is only ever evaluated at the
// moment something relevant actually happened.

/** world.js, the wave-complete milestone site (this.waveSpawner.waveNumber just incremented). */
function checkWaveAchievements(world) {
  if (world.currentTick >= 10000) _unlockAchievement('survive_10k');
  if (world.waveSpawner.waveNumber >= 20) _unlockAchievement('wave_20');
}

/** main.js, right after tryResearch() returns { ok: true } for a node. Takes the research state
 *  directly (not the whole world) so main.js's research-panel handler doesn't need an extra import. */
function checkResearchAchievements(researchState, researchNodes) {
  if (researchNodes.every(n => !!researchState.unlocked[n.id])) _unlockAchievement('full_research');
}

/** worldmap.js, the instant a region's control meter hits 100 and r.owned flips true. */
function checkConquestAchievements(worldMap) {
  const owned = worldMap.ownedCount();
  if (owned >= 3) _unlockAchievement('conquest_3');
  if (owned >= worldMap.regions.length) _unlockAchievement('conquest_all');
}

/** jobs.js, the instant a Taming job actually succeeds (animal moves from wildAnimals into dogs). */
function checkTameAchievement() {
  _unlockAchievement('tame_animal');
}

/** main.js's onBuildComplete hook (world.js fires this once per structure, the tick
 *  underConstruction flips false). Lifetime-cumulative: the five generator kinds don't all have
 *  to exist in the same settlement at once, just each be built at least once, ever. */
function noteStructureBuilt(kind) {
  if (!GENERATOR_KINDS.includes(kind)) return;
  const m = _loadMeta();
  if (!m.builtGeneratorKinds.includes(kind)) {
    m.builtGeneratorKinds.push(kind);
    _persistMeta();
  }
  if (GENERATOR_KINDS.every(k => m.builtGeneratorKinds.includes(k))) _unlockAchievement('all_generators');
}

/** world.js, called only when this run's peak alive-citizen count actually increases (guarded by
 *  the caller so this never fires on the common case of population holding steady or shrinking). */
function checkPopulationAchievement(peakAliveCitizens) {
  const m = _loadMeta();
  if (peakAliveCitizens > m.mostCitizensAlive) {
    m.mostCitizensAlive = peakAliveCitizens;
    _persistMeta();
  }
  if (peakAliveCitizens >= 30) _unlockAchievement('pop_30');
}

/** world.js, the instant world.gameOver flips true (the settlement has fallen). Rolls this run's
 *  final numbers into the lifetime totals. Deliberately NOT called on a quit-to-title or a
 *  mid-run restart -- see recordAbandonedGame() below for that path -- so "games played" only
 *  counts runs that actually concluded one way or another, matching the games_10 achievement's
 *  "play 10 settlements to their end" wording. */
function recordGameEnd(world) {
  const m = _loadMeta();
  m.gamesPlayed++;
  if (world.currentTick > m.longestSurvivalTicks) m.longestSurvivalTicks = world.currentTick;
  if (world.waveSpawner.waveNumber > m.longestSurvivalWaves) m.longestSurvivalWaves = world.waveSpawner.waveNumber;
  if (world.peakAliveCitizens > m.mostCitizensAlive) m.mostCitizensAlive = world.peakAliveCitizens;
  m.totalAttackersKilled += world.attackersKilled || 0;
  m.totalScrapEarned += world.scrapEarnedThisRun || 0;
  _persistMeta();
  if (m.gamesPlayed >= 10) _unlockAchievement('games_10');
  if (m.totalAttackersKilled >= 100) _unlockAchievement('kills_100');
  if (m.totalScrapEarned >= 5000) _unlockAchievement('scrap_5000');
}

/** main.js's confirmRestart()/quit-to-title/"New" path -- a run abandoned mid-game (not a real
 *  game-over) still deserves to count toward games_10 and bank its partial numbers, otherwise a
 *  player who never lets a settlement die would never accumulate lifetime stats at all. Same
 *  bookkeeping as recordGameEnd, just triggered from a different call site and guarded against
 *  double-counting a settlement that already game-overed (main.js only calls this for a world
 *  that's being discarded while still alive). */
function recordGameAbandoned(world) {
  if (world.gameOver) return; // already counted via recordGameEnd
  recordGameEnd(world);
}


// ---- world.js ----
// Ported from SD.Headless/SimWorld.cs -- the composition root that owns every store/system
// and advances them one fixed tick at a time (10 Hz, matching ARCHITECTURE.md section 2).






















// Exported: weather.js's wanderer-joins event draws from this same pool (via world._namePool)
// rather than importing it directly, to avoid a circular import (world.js already imports
// weather.js). Extended with 12 extra names beyond the starting 24 -- the default colony uses
// all 24 starter names immediately, so a wanderer event needs names past that to hand out,
// and a long soak test can see more than one join.
const STARTER_NAMES = [
  'Marlon', 'Aisling', 'Niamh', 'Reeli', 'Cascade', 'Orrery', 'Motoko',
  'Briar', 'Ansel', 'Sable', 'Quinn', 'Vesper', 'Rowan', 'Isolde', 'Callan',
  'Freya', 'Bram', 'Elowen', 'Tavish', 'Maren', 'Cormac', 'Sorcha', 'Declan', 'Aoife',
  'Fintan', 'Saoirse', 'Eamon', 'Niall', 'Grainne', 'Cian', 'Roisin', 'Tadhg',
  'Aileen', 'Cathal', 'Brigid', 'Ruairi',
];

const RECYCLING_WATER_BONUS = 1.4; // see the pump/pipe check in the pollution tick below

// Refugee Wagon (SEA:R's "Prisoner Bus" analog -- see FEATURE_RESEARCH.md's RETHINK/omit list:
// "Prisoner Bus (no equivalent, omit -- optional 'Refugee Wagon' analog if population-growth-
// via-arrivals is wanted)"). Distinct from weather.js's wanderer-joins event: that one is a flat
// rare roll regardless of population and adds one citizen near the core; this one is *reactive*
// -- it only turns on once losses have actually thinned the settlement below its starting size,
// arrives as a small group at the map edge (like a wave, but obviously friendly -- see siege.js's
// WaveSpawner edge-picking for the precedent), and has its own name pool (cycling with a numeric
// suffix once exhausted) so it never contends with the wanderer event's shared world._namePool.
const REFUGEE_NAMES = [
  'Torin', 'Wren', 'Iona', 'Faolan', 'Brynn', 'Saoirse', 'Eamon', 'Fintan',
  'Nessa', 'Cian', 'Aideen', 'Ruarc', 'Meara', 'Lorcan', 'Siobhan', 'Odhran',
];
const REFUGEE_GRACE_TICKS = 300;    // no wagon before the first wave's own grace period has passed
const REFUGEE_CHECK_INTERVAL = 500; // same order of magnitude as resources.js's maybeSpawnNode
const REFUGEE_CHANCE = 0.35;        // rolled once per check, only when the population gate below allows it
const REFUGEE_POP_FRACTION = 0.9;   // gate: only arrives while alive population is below this fraction of the starting count
const REFUGEE_MIN_GROUP = 1;
const REFUGEE_MAX_GROUP = 3;
const FINANCE_SNAPSHOT_INTERVAL = 300; // ticks between budget-report history snapshots, see finance comment below
const FINANCE_HISTORY_MAX = 20; // capped rolling window of finance snapshots kept for the trend sparkline

// Unrest (Prison Architect's riot state-machine, reframed genre-neutral): a COLONY-WIDE crisis
// distinct from an individual citizen's OnBreak (citizens.js -- that's a per-citizen speed/render
// state that fires whenever *one* citizen's own mood crashes). unrestLevel blends the fraction of
// the living population currently OnBreak with the Settlement Grading Wellbeing axis (grading.js
// -- reused rather than re-averaging mood a second time) and eases toward that blend each
// throttle step rather than snapping, same "slow trend, not a single bad tick" idea as
// citizens.js's mood easing. unrestActive only flips on once unrestLevel has sat at or above
// UNREST_TRIGGER_THRESHOLD for UNREST_SUSTAIN_TICKS running ticks (a genuine sustained crisis,
// not one bad reading) and resolves at a lower UNREST_RESOLVE_THRESHOLD (hysteresis, so it can't
// flicker on/off right at the boundary) -- there's no player action to "put it down", it resolves
// on its own once the same root causes an individual OnBreak already responds to (beds, food,
// room quality) improve. The actual penalty while active lives in jobs.js (UNREST_RATE_MULT),
// applied to every citizen's work/build/harvest/travel rate, not just the already-OnBreak ones --
// see that file's constant for the exact multiplier.
const UNREST_INTERVAL_TICKS = GRADING_INTERVAL_TICKS; // piggyback grading.js's own throttle cadence -- wellbeing only updates this often anyway
const UNREST_EASE = 0.15; // per UNREST_INTERVAL_TICKS step
const UNREST_TRIGGER_THRESHOLD = 0.55; // deliberately high -- this should be rare, not background noise
const UNREST_RESOLVE_THRESHOLD = 0.35;
const UNREST_SUSTAIN_TICKS = 600; // ~60s at 10Hz sustained at/above the trigger threshold before it actually flips on

class SimWorld {
  constructor(width, height, seed, aggression = AggressionPreset.Calm, startingCitizens = 24) {
    this.width = width;
    this.height = height;
    this.seed = seed;
    this.aggression = aggression;
    this.rng = makeRng(seed);
    this.currentTick = 0;
    this.timeOfDay = 0.3; // Duty Roster day/night cycle, 0-1 fraction; start mid-morning (Work block)
    this.paused = false;
    this.gameOver = false;
    this.milestoneLog = [];
    // power.js's overload mechanic: tick-over-tick diff set so the milestone below logs only the
    // first tick a given segment/nuclear-bucket actually crosses into overload, not every tick it
    // stays there. Purely transient bookkeeping -- deliberately not part of save/load state.
    this._prevOverloadedSupply = new Set();
    this.pollution = 0; // SEA:R's signature mechanic -- unmanaged waste makes waves worse, see director.js
    this.nuclearWaste = 0; // separate hazard resource from a nuclear generator, see siege.js's NUCLEAR_* comment
    this.ethanolPenaltyTimer = 0; // ethanol-fuel truck tradeoff (vehicles.js) -- counts down after a haul, halving Food zone refill meanwhile
    this.storyteller = 'Cassandra'; // Cassandra | Phoebe | Randy, see director.js STORYTELLERS
    this.rooms = []; // enclosed-room flood-fill, see rooms.js -- recomputed only when walls change
    this._roomsWallSignature = null;
    this._namePool = STARTER_NAMES; // weather.js's wanderer event draws unused names from here

    this.grid = new SettlementGrid(width, height);
    this.zones = new ZoneGrid(width, height);
    this.citizens = new CitizenStore(64);
    this.attackers = new AttackerStore(1024);
    this.roster = new StaffRoster();
    this.structures = [];
    this.waveSpawner = new WaveSpawner(this.grid);
    this.relationships = new RelationshipWeb();
    this.scrap = 50;
    // Tech-unlock progression (research.js): passive Research Points, plus the set of unlocked
    // nodes. The survival-core buildables are unlocked in createResearchState, so a brand new
    // colony can still wall up and put down turrets on tick 0.
    this.research = createResearchState();
    this._lastWaveLogged = 0;

    // Per-run counters feeding metaprogress.js's cross-run lifetime stats (see that module's
    // header comment) -- purely additive bookkeeping here, this world instance dies at
    // game-over/restart/quit-to-title same as everything else on it, but the numbers get folded
    // into localStorage's lifetime totals right before that happens (recordGameEnd/
    // recordGameAbandoned, called from this file's tick() and from main.js respectively).
    this.peakAliveCitizens = 0;   // highest alive-citizen count seen this run, updated in tick()
    this.attackersKilled = 0;     // count (not scrap) of attackers killed this run, see addScrap()
    this.scrapEarnedThisRun = 0;  // cumulative scrap EARNED this run, never decremented by spending -- distinct from this.scrap

    // Budget/finance ledger (Prison Architect's budget report, see FEATURE_RESEARCH.md): the
    // scrap economy itself is unchanged (still just world.scrap, a single running total) -- this
    // is purely a reporting layer on top, tallying WHERE scrap came from/went so a UI can show a
    // breakdown instead of just the bare number. Deliberately per-category running totals, not a
    // full itemized transaction log -- much cheaper to maintain given how many call sites feed
    // scrap in (siege.js kills, jobs.js harvesting, vehicles.js hauls, the recycling-center
    // trickle and conquest-layer trickle in this file, worldmap.js's supply lines) and plenty for
    // a budget report / trend sparkline.
    this.finance = {
      killScrap: 0,       // attacker kills: turrets, staff combat, traps, dogs (siege.js/security.js)
      harvestScrap: 0,    // citizens hand-harvesting resource nodes (jobs.js)
      haulScrap: 0,       // recycling/garbage truck completed hauls (vehicles.js)
      recyclingScrap: 0,  // passive Recycling Center trickle (this file, tick())
      conquestScrap: 0,   // held-region supply lines trickling scrap in (worldmap.js)
      otherScrap: 0,      // catch-all for any future/uncategorized income source
      buildSpend: 0,      // total scrap spent on construction (economy.js spend())
      history: [],        // rolling snapshots of net scrap change, one per FINANCE_SNAPSHOT_INTERVAL
                           // ticks, capped at FINANCE_HISTORY_MAX entries -- enough for a trend sparkline
    };
    this._financeLastIncome = 0; // sum of all *Scrap categories as of the last snapshot
    this._financeLastExpense = 0; // buildSpend as of the last snapshot

    // Settlement Grading (non-carceral reframe of Prison Architect's 4-axis Grading tab, see
    // grading.js's header comment): purely a read-only reporting layer, recomputed periodically
    // in tick() below. Seeded with an optimistic default so the UI has something sane to show
    // before the first GRADING_INTERVAL_TICKS elapses; computeGrading() is also called once here
    // so a fresh colony shows its real scores immediately rather than placeholder 100s.
    this.grading = { safety: 100, wellbeing: 100, sustainability: 100, cohesion: 100 };
    this._gradingPrevScrap = this.scrap;

    // Unrest (see the UNREST_* constants' doc comment above): starts calm/inactive, updated by
    // _updateUnrest() below every UNREST_INTERVAL_TICKS.
    this.unrestLevel = 0;
    this.unrestActive = false;
    this._unrestAboveTicks = 0; // running count of ticks unrestLevel has sat at/above UNREST_TRIGGER_THRESHOLD

    // Presentation-layer audio hooks (see audio.js) -- optional callbacks the host app (main.js)
    // can assign after construction. Left null by default so world.js/siege.js never need to
    // know audio.js exists; called via optional chaining everywhere below.
    this.onBuildComplete = null; // (structure) => void, fires once when a blueprint finishes
    this.onWaveIncoming = null;  // () => void, fires when a new wave's "incoming" milestone posts
    this.onTurretFire = null;    // (structure) => void, fires when a turret/tesla actually shoots
    this.onKill = null;          // () => void, fires whenever an attacker is killed
    this.onCitizenDowned = null; // () => void, fires when a citizen goes down or dies to an attacker
    this.onRandomEvent = null;   // (text) => void, fires on a weather change or a one-off random event (weather.js)

    initWeather(this); // sets this.weather / this._weatherTimer, see weather.js

    const count = Math.min(startingCitizens, STARTER_NAMES.length);
    this.startingCitizenCount = count; // Refugee Wagon's population gate below reacts to losses relative to this
    this._nextRefugeeNameIndex = 0;    // Refugee Wagon's own name-pool cursor, independent of _namePool above
    this._citizenIds = [];
    for (let n = 0; n < count; n++) {
      const x = 15 + (n % 8) * 2;
      const y = 15 + Math.floor(n / 8) * 2;
      const idx = this.citizens.spawn(STARTER_NAMES[n], x, y, this.rng);
      this._citizenIds.push(this.citizens.id[idx]);
    }

    this.dogs = [];
    this.wildAnimals = []; // untamed animals, distinct from world.dogs until jobs.js's Taming job succeeds -- see security.js
    if (count > 3) {
      // Small patrol loops (security.js's patrol-route support) rather than a single fixed
      // point -- each guard/sniper paces a couple tiles either side of their original post, still
      // well within GUARD_RANGE/SNIPER_RANGE (siege.js) so combat effectiveness is unchanged.
      this.roster.assign(this._citizenIds[0], StaffRoleKind.Sniper, [{ x: 12, y: 20 }, { x: 14, y: 20 }]);
      this.roster.assign(this._citizenIds[1], StaffRoleKind.Sniper, [{ x: 28, y: 20 }, { x: 30, y: 20 }]);
      this.roster.assign(this._citizenIds[2], StaffRoleKind.Guard, [{ x: 20, y: 13 }, { x: 22, y: 13 }]);
      this.roster.assign(this._citizenIds[3], StaffRoleKind.Guard, [{ x: 20, y: 27 }, { x: 22, y: 27 }]);
    }
    if (count > 4) {
      this.roster.assign(this._citizenIds[4], StaffRoleKind.K9Handler, { x: 21, y: 20 });
      this.dogs.push({ ownerId: this._citizenIds[4], x: 21, y: 20, cooldown: 0 });
    }

    for (const [tx, ty] of [[13, 20], [29, 20], [21, 13], [21, 27]]) {
      this.structures.push(new Structure('turret', tx, ty, { instant: true }));
    }

    // Default zones so the job system has somewhere to send citizens out of the box.
    for (let x = 17; x <= 20; x++) for (let y = 17; y <= 20; y++) this.zones.set(x, y, ZoneKind.Food);
    for (let x = 22; x <= 25; x++) for (let y = 17; y <= 20; y++) this.zones.set(x, y, ZoneKind.Bedroom);
    for (let x = 17; x <= 20; x++) for (let y = 22; y <= 23; y++) this.zones.set(x, y, ZoneKind.Recreation);

    this.resourceNodes = scatterNodes(this.grid, this.rng, 16, 14, this.width / 2, this.height / 2);
    this.vehicles = [];
    this._nextVehicleTick = 200;

    computeGrading(this); // real scores from tick 0, not the placeholder defaults set above
  }

  idOf(i) { return this.citizens.id[i]; }
  isStaffAt(i) { return this.roster.isStaff(this.citizens.id[i]); }
  // A staff member currently clocked off (security.js's fatigue cycle) isn't "on duty" for the
  // purposes of holding a post/patrol, the on-duty social-fulfillment bonus, or jobs.js's
  // staff-skip check -- they're on an Eat/Sleep trip like any citizen until they recover.
  isStaffOnDutyAt(i) { return this.isStaffAt(i) && !this.roster.isOffDuty(this.citizens.id[i]); }

  // "Manned" means a live, non-downed citizen with StaffRoleKind.Monitor is actually standing at
  // the Monitor Station post, not just assigned on paper -- same physical-presence requirement
  // as Guard/Sniper posts (tickStaffDuty walks them there each tick).
  _isMonitorStaffed(monitorStation) {
    for (let i = 0; i < this.citizens.count; i++) {
      if (!this.citizens.isAliveAt(i) || this.citizens.isDownedAt(i)) continue;
      if (this.roster.kindOf(this.idOf(i)) !== StaffRoleKind.Monitor) continue;
      const dx = this.citizens.x[i] - monitorStation.x;
      const dy = this.citizens.y[i] - monitorStation.y;
      if (Math.hypot(dx, dy) <= 1.5) return true;
    }
    return false;
  }

  // `kind` buckets the change into world.finance's running totals for the budget report (see the
  // constructor comment above) -- purely additive bookkeeping, never affects the actual amount
  // applied to world.scrap. Callers that don't care (or a negative/zero amount, which shouldn't
  // happen here but would double-count if it did) just fall through uncategorized.
  addScrap(amount, kind) {
    this.scrap += amount;
    if (amount > 0 && this.finance) {
      if (kind === 'kill') { this.finance.killScrap += amount; this.attackersKilled++; }
      else if (kind === 'harvest') this.finance.harvestScrap += amount;
      else if (kind === 'haul') this.finance.haulScrap += amount;
      else if (kind === 'recycling') this.finance.recyclingScrap += amount;
      else if (kind === 'conquest') this.finance.conquestScrap += amount;
      else this.finance.otherScrap += amount;
      this.scrapEarnedThisRun += amount; // metaprogress.js's lifetime scrap-earned stat, see recordGameEnd()
    }
  }

  build(kind, x, y) {
    this.structures.push(new Structure(kind, x, y));
  }

  // Refugee Wagon's own name-pool cursor: cycles REFUGEE_NAMES, appending " 2", " 3", etc. once
  // it wraps so a very long soak test still gets distinct names instead of exact repeats.
  _nextRefugeeName() {
    const idx = this._nextRefugeeNameIndex++;
    const base = REFUGEE_NAMES[idx % REFUGEE_NAMES.length];
    const cycle = Math.floor(idx / REFUGEE_NAMES.length);
    return cycle > 0 ? `${base} ${cycle + 1}` : base;
  }

  // Refugee Wagon (see the REFUGEE_* constants' doc comment above): periodic, reactive
  // population-growth-via-arrivals. Gated three ways so it can't spam or overflow --
  // (1) currentTick % REFUGEE_CHECK_INTERVAL, same cadence pattern as resources.js's
  // maybeSpawnNode; (2) alive population must actually be below REFUGEE_POP_FRACTION of the
  // starting count, so a healthy/growing colony just doesn't roll; (3) CitizenStore's fixed
  // capacity (see citizens.js) is checked before spawning and the group size is clamped down to
  // whatever room is actually left, rather than spawn() silently failing partway through.
  _maybeSpawnRefugeeWagon() {
    if (this.currentTick < REFUGEE_GRACE_TICKS) return;
    if (this.currentTick % REFUGEE_CHECK_INTERVAL !== 0) return;

    let alive = 0;
    for (let i = 0; i < this.citizens.count; i++) if (this.citizens.isAliveAt(i)) alive++;
    if (alive >= this.startingCitizenCount * REFUGEE_POP_FRACTION) return;
    if (this.rng() >= REFUGEE_CHANCE) return;

    const remainingCapacity = this.citizens.capacity - this.citizens.count;
    if (remainingCapacity <= 0) return; // at capacity -- skip this check entirely rather than overflow

    let groupSize = REFUGEE_MIN_GROUP + Math.floor(this.rng() * (REFUGEE_MAX_GROUP - REFUGEE_MIN_GROUP + 1));
    groupSize = Math.min(groupSize, remainingCapacity);

    // Arrive at a random map edge, clustered loosely like a small group walking in together --
    // same edge-picking idea as siege.js's WaveSpawner, just friendly and much smaller.
    const edge = Math.floor(this.rng() * 4);
    let ex, ey;
    if (edge === 0) { ex = 1; ey = this.rng() * this.height; }
    else if (edge === 1) { ex = this.width - 2; ey = this.rng() * this.height; }
    else if (edge === 2) { ex = this.rng() * this.width; ey = 1; }
    else { ex = this.rng() * this.width; ey = this.height - 2; }

    const arrivedNames = [];
    for (let n = 0; n < groupSize; n++) {
      const name = this._nextRefugeeName();
      const x = Math.max(1, Math.min(this.width - 2, ex + (this.rng() - 0.5) * 2));
      const y = Math.max(1, Math.min(this.height - 2, ey + (this.rng() - 0.5) * 2));
      // CitizenStore.spawn assigns trait/backstory/passions itself (see citizens.js), same as
      // every starting citizen in the constructor above -- nothing extra needed here for that.
      const idx = this.citizens.spawn(name, x, y, this.rng);
      if (idx < 0) break; // capacity hit mid-loop; shouldn't happen given the clamp above, but stay safe
      this._citizenIds.push(this.citizens.id[idx]);
      arrivedNames.push(name);
    }
    if (arrivedNames.length === 0) return;

    const text = arrivedNames.length === 1
      ? `Refugee Wagon arrives -- ${arrivedNames[0]} joins the settlement`
      : `Refugee Wagon arrives -- ${arrivedNames.join(', ')} join the settlement`;
    this.milestoneLog.push({ tick: this.currentTick, text });
    if (this.milestoneLog.length > 20) this.milestoneLog.shift();
    this.onRandomEvent?.(text);
  }

  // Unrest (see the UNREST_* constants' doc comment above the class): throttled to
  // UNREST_INTERVAL_TICKS, same cadence grading.js's Wellbeing axis already updates on, so this
  // reads a fresh value each time rather than a stale one. Eases unrestLevel toward a target
  // blend of "how many citizens are OnBreak right now" and "how bad is Wellbeing right now",
  // then applies the sustained-duration + hysteresis gate described above to flip unrestActive.
  _updateUnrest() {
    if (this.currentTick % UNREST_INTERVAL_TICKS !== 0) return;

    let aliveCount = 0, onBreakCount = 0;
    for (let i = 0; i < this.citizens.count; i++) {
      if (!this.citizens.isAliveAt(i)) continue;
      aliveCount++;
      if (this.citizens.isOnBreakAt(i)) onBreakCount++;
    }
    const onBreakFraction = aliveCount > 0 ? onBreakCount / aliveCount : 0;
    const wellbeingDeficit = 1 - (this.grading?.wellbeing ?? 100) / 100;
    const target = Math.max(0, Math.min(1, 0.65 * onBreakFraction + 0.35 * wellbeingDeficit));
    this.unrestLevel += (target - this.unrestLevel) * UNREST_EASE;
    this.unrestLevel = Math.max(0, Math.min(1, this.unrestLevel));

    if (this.unrestLevel >= UNREST_TRIGGER_THRESHOLD) {
      this._unrestAboveTicks += UNREST_INTERVAL_TICKS;
    } else if (this.unrestLevel < UNREST_RESOLVE_THRESHOLD) {
      this._unrestAboveTicks = 0;
    }
    // Between the resolve and trigger thresholds, _unrestAboveTicks is left alone -- neither
    // building nor reset -- so a value oscillating right at the boundary doesn't get its
    // sustained-duration progress wiped by a single throttle-step dip.

    if (!this.unrestActive && this._unrestAboveTicks >= UNREST_SUSTAIN_TICKS) {
      this.unrestActive = true;
      const text = 'Unrest is spreading through the settlement';
      this.milestoneLog.push({ tick: this.currentTick, text });
      if (this.milestoneLog.length > 20) this.milestoneLog.shift();
      this.onRandomEvent?.(text);
    } else if (this.unrestActive && this.unrestLevel < UNREST_RESOLVE_THRESHOLD) {
      this.unrestActive = false;
      this._unrestAboveTicks = 0;
      const text = 'The settlement has calmed';
      this.milestoneLog.push({ tick: this.currentTick, text });
      if (this.milestoneLog.length > 20) this.milestoneLog.shift();
      this.onRandomEvent?.(text);
    }
  }

  tick() {
    if (this.paused || this.gameOver) return;
    this.currentTick++;
    this.timeOfDay = (this.timeOfDay + 1 / DAY_NIGHT_CYCLE_TICKS) % 1; // Duty Roster clock, see schedule.js

    // Room stats (beauty/cleanliness/impressiveness -> quality, see rooms.js's computeRoomStats
    // doc comment): recomputed every tick against the *current* structures/pollution/fire state
    // -- unlike detectRooms' cell layout, a room's contents change far more often than its walls
    // do, so this can't be gated behind the wall-signature check below. Read by tickNeedsAndMood
    // just after, via roomContaining, to nudge a citizen's mood based on the room they're in.
    computeRoomStats(this.rooms, this.grid, this.structures, this, this.zones);

    tickNeedsAndMood(this.citizens, (i) => this.isStaffOnDutyAt(i), this.rng, this);
    // Off-duty check runs before tickJobs so a staff member whose fatigue/hunger just crossed
    // the threshold this tick immediately falls into jobs.js's normal Idle/SeekingFood/SeekingBed
    // handling below, rather than waiting a tick -- see security.js's tickStaffOffDuty doc comment.
    tickStaffOffDuty(this.citizens, this.roster, (i) => this.idOf(i), this.zones);
    tickJobs(this.citizens, this.zones, (i) => this.isStaffOnDutyAt(i), this.structures, this.resourceNodes,
      (i) => this.idOf(i), (amt) => this.addScrap(amt, 'harvest'), this);
    tickStaffDuty(this.citizens, this.roster, (i) => this.idOf(i));
    // Armory issuance (security.js): cheap (roster-size loop, not per-citizen-store-slot), so
    // just re-derive every tick rather than hooking build-complete/destroy events -- a built or
    // destroyed Armory (and a freshly-assigned Guard/Sniper) all propagate within one tick.
    tickArmoryIssuance(this.roster, this.structures);
    // Rain (weather.js): citizens amble a bit slower underfoot -- same wander-speed knob every
    // other build passes through already, just weather-scaled.
    tickWander(this.citizens, this.grid, this.rng, 0.04 * weatherWanderSpeedMult(this.weather),
      (i) => this.isStaffAt(i) || isOnJob(this.citizens, i));
    tickDogs(this.dogs, this.citizens, this.roster, this.attackers, (amt) => this.addScrap(amt, 'kill'));
    // Taming/breeding (RimWorld animals, see FEATURE_RESEARCH.md and security.js): wild animals
    // wander and occasionally spawn like resource nodes below; jobs.js's Taming job moves a tamed
    // one from wildAnimals into this.dogs, and tickDogBreeding occasionally grows the dogs list
    // on its own once there are at least two, capped so it can't spiral.
    tickWildAnimals(this.wildAnimals, this.grid, this.rng);
    tickDogBreeding(this.dogs, this.rng, this.currentTick);
    this.relationships.tick(this.citizens, (i) => this.citizens.name[i], this.currentTick);

    // Weather + one-off random events (RimWorld's "Events" list -- see weather.js's header
    // comment and FEATURE_RESEARCH.md's RimWorld section). Runs after rooms/needs so the
    // Cold/Heatwave indoor check sees this tick's room state, and after tickWander so a weather
    // *change* this tick still affects this tick's movement via the call above.
    tickWeather(this);
    tickRandomEvents(this);

    maybeSpawnNode(this.resourceNodes, this.grid, this.rng, this.currentTick, this.width / 2, this.height / 2);
    maybeSpawnWildAnimal(this.wildAnimals, this.grid, this.rng, this.currentTick, this.width / 2, this.height / 2);
    this._maybeSpawnRefugeeWagon(); // population-growth-via-arrivals, see the method's doc comment above
    tickVehicles(this);
    if (this.ethanolPenaltyTimer > 0) this.ethanolPenaltyTimer--; // see vehicles.js FUEL_TYPES.ethanol

    // Pollution: generators produce power at the cost of waste (SEA:R's core tradeoff, see
    // FEATURE_RESEARCH.md); it decays slowly on its own but climbs faster than that decay once
    // you have more than a couple of generators running, so a garbage-truck haul run matters.
    let activeGenerators = 0;
    let activeCoalGenerators = 0;
    let recyclingCapacity = 0;
    let activeUncontainedNuclear = 0;
    for (const s of this.structures) {
      // Solar array siting (SEA:R multi-source power economy, see power.js's isSource doc
      // comment): this codebase has no roof/indoor concept, so "needs open sky" is substituted
      // with "not built inside a detected enclosed room" -- the closest analog to "indoors" this
      // sim has (rooms.js's detectRooms). Stamped every tick, mirroring the s._staffed pattern
      // world.js already uses for monitor_station, and read back by power.js's isSource so a
      // solar array only acts as a power source while it's actually in the open.
      if (s.kind === 'generator_solar') s._openSky = !roomContaining(this.rooms, this.grid, s.x, s.y);
      // Wind turbine siting: power.js's isSource always recomputes this live off the current
      // structures list (no lag in what actually gets powered) -- this stamp is purely so
      // render.js can tint the turbine blades without importing power.js's internals directly.
      if (s.kind === 'generator_wind') s._windSited = isWindSited(s, this.structures);
      if (s.destroyed || s.underConstruction) continue;
      if (s.kind === 'generator') activeGenerators++;
      // Coal (SEA:R): the "worse plain generator" tradeoff -- cheaper to build (economy.js) but
      // dirtier per-tick than a plain generator, tracked separately so its pollution rate can
      // differ from GENERATOR_POLLUTION_RATE below rather than reusing activeGenerators' count.
      else if (s.kind === 'generator_coal') activeCoalGenerators++;
      else if (s.kind === 'recycling_center') {
        // Water grid payoff (water.js): a Recycling Center fed by a pump/pipe run processes
        // pollution faster -- water pressure washing down the sorting line, same "provisioned
        // beats unprovisioned" logic as the Food/Recreation refill bonus in jobs.js, applied to
        // this consumer instead since it has no refill rate of its own to boost.
        recyclingCapacity += isWateredAt(this.structures, s.x, s.y) ? 0.4 * RECYCLING_WATER_BONUS : 0.4;
      }
      else if (s.kind === 'generator_nuclear' && !isNuclearContained(this.structures, s)) activeUncontainedNuclear++;
    }
    // Recycling Center (SEA:R): a passive waste->resource sink distinct from garbage trucks --
    // trucks do one big haul-cycle drop, this trickles constantly in exchange for scrap, so both
    // remain worth building rather than one obsoleting the other.
    if (recyclingCapacity > 0) {
      const processed = Math.min(this.pollution, recyclingCapacity);
      this.pollution -= processed;
      this.addScrap(processed * 0.5, 'recycling');
    }
    // Coal's pollution-per-tick is deliberately worse than a plain generator's 0.03 (roughly
    // double) -- its whole tradeoff is "cheaper to build, dirtier to run", not a strict downgrade,
    // so the gap has to be big enough to matter. Wind/solar contribute nothing here at all --
    // their tradeoff is siting (power.js's isSource), not pollution.
    this.pollution = Math.max(0, this.pollution + activeGenerators * 0.03 + activeCoalGenerators * 0.07 - 0.01);

    // Nuclear waste (SEA:R): distinct from pollution above -- it only accrues while a nuclear
    // generator is uncontained, and it's not something a recycling center processes; the only
    // fix is a nearby waste_storage. tickNuclearHazard (siege.js) is what actually damages
    // citizens/structures in the meantime; this counter is the visible "how bad is it" readout.
    this.nuclearWaste = Math.max(0, this.nuclearWaste + activeUncontainedNuclear * NUCLEAR_WASTE_RATE - 0.02);
    tickNuclearHazard(this.structures, this.citizens);

    // Fire (Prison Architect/SEA:R crisis event, see FEATURE_RESEARCH.md and fire.js): active
    // generators can spark nearby flammable structures, which then burn and spread on their own.
    tickFireIgnition(this.structures, this.rng);
    tickFire(this.structures, this.rng);

    // Power grid overload (Prison Architect's overload/explosion-risk mechanic, power.js): too
    // many powered turrets/tesla/watchtowers wired to too few/weak generators strains a segment.
    // hasPoweredBonus (siege.js's turret/tesla boost, watchtower's warning-window boost above)
    // already stops applying the bonus on an overloaded segment on its own every tick it's read --
    // the two things left to do here are (a) log a milestone the first tick a segment/nuclear
    // radius actually crosses into overload, and (b) roll the rare fire-risk consequence, reusing
    // fire.js's igniteStructure directly rather than a parallel damage system.
    const overloadedNow = overloadedSupplyKeys(this.structures);
    for (const key of overloadedNow) {
      if (this._prevOverloadedSupply.has(key)) continue;
      this.milestoneLog.push({
        tick: this.currentTick,
        text: 'Power grid overloaded -- powered consumers on that line lose their boost, and it now risks catching fire',
      });
      if (this.milestoneLog.length > 20) this.milestoneLog.shift();
    }
    this._prevOverloadedSupply = overloadedNow;
    if (overloadedNow.size > 0) {
      for (const s of this.structures) {
        if (s.kind !== 'wire' && !s.kind.startsWith('generator')) continue;
        if (s.destroyed || s.underConstruction || s.onFire) continue;
        if (!isSegmentOverloadedAt(this.structures, s.x, s.y)) continue;
        if (this.rng() < OVERLOAD_FIRE_CHANCE_PER_TICK) igniteStructure(s);
      }
    }

    // Conquest layer (worldmap.js): advances THIS region's control meter based on how the
    // settlement is doing, and trickles scrap in from every other region you already hold.
    // Strictly additive on top of the scrap economy above -- it adds income, never gates it.
    tickWorldMap(this);

    // Research trickle (research.js): scaled by alive citizen count, so keeping people alive is
    // what advances the tech tree. Purely additive -- it gates nothing that already existed on
    // tick 0 and never touches scrap or the director's difficulty inputs.
    tickResearch(this);

    directWaveSpawner(this);
    // `this` is passed so WaveSpawner can read pollution/nuclearWaste when rolling the raid's
    // arrival method (edge walk-in vs. an interior tunnel breach) -- read-only, same
    // hazard-scales-danger pattern director.js uses.
    this.waveSpawner.tick(this.currentTick, this.attackers, this.rng, this);
    tickAttackers(this.attackers, this.structures, this.grid, this.width / 2, this.height / 2, this.citizens,
      (amt) => this.addScrap(amt, 'kill'), () => this.onKill?.());
    tickTurrets(this.structures, this.attackers, (amt) => this.addScrap(amt, 'kill'), (s) => this.onTurretFire?.(s), () => this.onKill?.());
    tickStaffCombat(this.citizens, this.roster, (i) => this.idOf(i), this.attackers, (amt) => this.addScrap(amt, 'kill'), () => this.onKill?.());
    tickAttackerVsCitizens(this.attackers, this.citizens, () => this.onCitizenDowned?.());

    // Wall blueprints live in this.structures like everything else (for the ghost render +
    // construction progress), but the actual passability/terrain effect lives on the grid --
    // apply it the tick a wall blueprint finishes, then drop the now-redundant entry. Garage
    // blueprints similarly hand off to a parked Vehicle the moment they finish, rather than
    // acting as a structure themselves once complete.
    this.structures = this.structures.filter(s => {
      // Build-complete audio cue: fires exactly once per structure, the tick underConstruction
      // flips false (instant/starter structures are pre-marked _builtNotified in the Structure
      // constructor so they never trigger this).
      if (!s.underConstruction && !s._builtNotified) {
        s._builtNotified = true;
        this.onBuildComplete?.(s);
      }
      if (s.kind === 'wall' && !s.underConstruction) {
        this.grid.setWall(Math.floor(s.x), Math.floor(s.y), 1);
        return false;
      }
      const garageKind = parseGarageKind(s.kind);
      if (garageKind && !s.underConstruction && !s._vehicleSpawned) {
        spawnParkedVehicle(this, garageKind.truckKind, s.x, s.y, garageKind.fuelType);
        s._vehicleSpawned = true;
      }
      return true;
    });

    let wallSum = 0;
    for (let i = 0; i < this.grid.wallThingId.length; i++) if (this.grid.wallThingId[i] !== 0) wallSum += i + 1;
    if (wallSum !== this._roomsWallSignature) {
      this._roomsWallSignature = wallSum;
      this.rooms = detectRooms(this.grid);
    }

    // Room-quality milestone (rooms.js's computeRoomStats): logged once per room object the tick
    // its quality first crosses a "genuinely nice" threshold, and re-armed if it later dips back
    // below so a room that's furnished, gutted, and re-furnished can log again. Room objects are
    // stable references between wall-layout changes (see the wallSum signature check below), so
    // a flag on the room itself is enough state -- no separate id-keyed tracking needed.
    const ROOM_QUALITY_MILESTONE_THRESHOLD = 0.75;
    for (const room of this.rooms) {
      if (room.quality >= ROOM_QUALITY_MILESTONE_THRESHOLD) {
        if (!room._loggedHighQuality) {
          room._loggedHighQuality = true;
          this.milestoneLog.push({
            tick: this.currentTick,
            text: `A room reached high quality (beauty ${room.beauty.toFixed(1)}, quality ${room.quality.toFixed(2)})`,
          });
          if (this.milestoneLog.length > 20) this.milestoneLog.shift();
        }
      } else {
        room._loggedHighQuality = false;
      }
    }

    if (this.waveSpawner.waveNumber > this._lastWaveLogged) {
      this._lastWaveLogged = this.waveSpawner.waveNumber;
      const tunnelled = this.waveSpawner.lastArrival === ArrivalMethod.Tunnel;
      this.milestoneLog.push({
        tick: this.currentTick,
        text: tunnelled
          ? `Wave ${this.waveSpawner.waveNumber} TUNNELLED IN -- breach inside the perimeter!`
          : `Wave ${this.waveSpawner.waveNumber} incoming`,
      });
      if (this.milestoneLog.length > 20) this.milestoneLog.shift();
      this.onWaveIncoming?.();
      // metaprogress.js's cross-run achievements (see that module's header comment) -- checked
      // right here rather than every tick, since a wave-complete is exactly the kind of milestone
      // event the survive-N-ticks / reach-wave-N thresholds should be evaluated against.
      checkWaveAchievements(this);
    }

    // Watchtowers (CCTV/early-warning analog, see FEATURE_RESEARCH.md) give advance notice of
    // an incoming wave before it actually spawns, rather than only finding out at spawn time.
    const watchtower = this.structures.find(s => s.kind === 'watchtower' && !s.destroyed && !s.underConstruction);
    // CCTV cameras (Prison Architect's "CCTV + manned-monitor bonus", see FEATURE_RESEARCH.md's
    // Prison Architect section) are a cheaper, shorter-range complement to the watchtower: an
    // unmanned camera sees less far ahead than even an unpowered watchtower, but a camera backed
    // by a staffed Monitor Station -- a citizen actually assigned to StaffRoleKind.Monitor and
    // physically holding that post, same "hold position" pattern tickStaffDuty already gives
    // Guard/Sniper -- closes most of that gap. That staffed-vs-unstaffed swing is the "manned
    // monitor bonus" the source material calls out specifically.
    const camera = this.structures.find(s => s.kind === 'camera' && !s.destroyed && !s.underConstruction);
    const monitorStation = this.structures.find(s => s.kind === 'monitor_station' && !s.destroyed && !s.underConstruction);
    const monitorStaffed = !!monitorStation && this._isMonitorStaffed(monitorStation);
    if (monitorStation) monitorStation._staffed = monitorStaffed; // render.js reads this for screen brightness

    // A powered watchtower (generator in range) sees further out in time, same pattern as the
    // powered-turret damage/range boost -- generators are now a real consumer-side upgrade
    // wherever they're built near, not just a pollution-producing decoration.
    let warningWindow = watchtower ? (hasPoweredBonus(this.structures, watchtower.x, watchtower.y) ? 90 : 50) : 0;
    let warningSource = watchtower ? 'watchtower' : null;
    if (camera) {
      const cameraWindow = monitorStaffed ? 70 : 30;
      if (cameraWindow > warningWindow) { warningWindow = cameraWindow; warningSource = monitorStaffed ? 'monitor' : 'camera'; }
    }

    if (warningSource && !this._warnedForWave &&
      this.waveSpawner.nextWaveTick - this.currentTick <= warningWindow && this.waveSpawner.nextWaveTick > this.currentTick) {
      this._warnedForWave = this.waveSpawner.waveNumber + 1;
      const text = warningSource === 'monitor'
        ? 'Manned monitor station spots raiders massing on CCTV -- wave incoming soon'
        : warningSource === 'camera'
          ? 'CCTV camera spots raiders massing -- wave incoming soon'
          : 'Watchtower spots raiders massing -- wave incoming soon';
      this.milestoneLog.push({ tick: this.currentTick, text });
      if (this.milestoneLog.length > 20) this.milestoneLog.shift();
    }
    if (this._warnedForWave && this._warnedForWave <= this.waveSpawner.waveNumber) this._warnedForWave = null;

    let aliveCitizens = 0;
    for (let i = 0; i < this.citizens.count; i++) if (this.citizens.isAliveAt(i)) aliveCitizens++;
    // metaprogress.js's "most citizens alive at once" lifetime stat + its Boomtown achievement --
    // only actually calls into that module when this run's peak just increased (population holds
    // steady or shrinks far more often than it grows), so this isn't a per-tick achievement check.
    if (aliveCitizens > this.peakAliveCitizens) {
      this.peakAliveCitizens = aliveCitizens;
      checkPopulationAchievement(this.peakAliveCitizens);
    }
    if (aliveCitizens === 0 && this.citizens.count > 0) {
      this.gameOver = true;
      this.milestoneLog.push({ tick: this.currentTick, text: 'GAME OVER -- the settlement has fallen' });
      // Roll this run's final numbers into metaprogress.js's lifetime totals right as the run ends
      // -- see that module's recordGameEnd doc comment for why this is the one authoritative
      // "did this settlement finish" call site (main.js's recordGameAbandoned covers the other
      // path, a run discarded while still alive).
      recordGameEnd(this);
    }

    // Finance history snapshot (budget report trend/sparkline, see the constructor's finance
    // comment): once per FINANCE_SNAPSHOT_INTERVAL ticks -- roughly one wave-cycle, matching the
    // 300-tick default wave spacing in siege.js's WaveSpawner -- record the net scrap change
    // (income minus expense) since the last snapshot, capped to the last FINANCE_HISTORY_MAX
    // entries so this can't grow unbounded over a long session.
    if (this.currentTick % FINANCE_SNAPSHOT_INTERVAL === 0) {
      const totalIncome = this.finance.killScrap + this.finance.harvestScrap + this.finance.haulScrap +
        this.finance.recyclingScrap + this.finance.conquestScrap + this.finance.otherScrap;
      const totalExpense = this.finance.buildSpend;
      const net = (totalIncome - this._financeLastIncome) - (totalExpense - this._financeLastExpense);
      this.finance.history.push({ tick: this.currentTick, net, scrap: Math.round(this.scrap) });
      if (this.finance.history.length > FINANCE_HISTORY_MAX) this.finance.history.shift();
      this._financeLastIncome = totalIncome;
      this._financeLastExpense = totalExpense;
    }

    // Settlement Grading (grading.js): read-only reporting layer, throttled the same way as
    // resources.js's maybeSpawnNode/security.js's breed check above -- a modulo gate on
    // currentTick rather than every tick, since nothing downstream needs sub-second freshness.
    if (this.currentTick % GRADING_INTERVAL_TICKS === 0) computeGrading(this);

    // Unrest (see UNREST_* constants above and the _updateUnrest doc comment): runs right after
    // grading so it reads this tick's freshly-recomputed Wellbeing axis rather than a stale one
    // from before the throttle window advanced.
    this._updateUnrest();
  }

  serialize() {
    return {
      width: this.width, height: this.height, seed: this.seed, aggression: this.aggression,
      currentTick: this.currentTick, scrap: this.scrap, gameOver: this.gameOver,
      finance: this.finance,
      startingCitizenCount: this.startingCitizenCount, nextRefugeeNameIndex: this._nextRefugeeNameIndex,
      pollution: this.pollution, nuclearWaste: this.nuclearWaste, ethanolPenaltyTimer: this.ethanolPenaltyTimer,
      storyteller: this.storyteller, timeOfDay: this.timeOfDay,
      unrestLevel: this.unrestLevel, unrestActive: this.unrestActive, unrestAboveTicks: this._unrestAboveTicks,
      peakAliveCitizens: this.peakAliveCitizens, attackersKilled: this.attackersKilled, scrapEarnedThisRun: this.scrapEarnedThisRun,
      research: serializeResearch(this.research),
      weather: this.weather, weatherTimer: this._weatherTimer,
      waveNumber: this.waveSpawner.waveNumber, nextWaveTick: this.waveSpawner.nextWaveTick,
      citizens: {
        count: this.citizens.count,
        id: Array.from(this.citizens.id.slice(0, this.citizens.count)),
        name: this.citizens.name.slice(0, this.citizens.count),
        x: Array.from(this.citizens.x.slice(0, this.citizens.count)),
        y: Array.from(this.citizens.y.slice(0, this.citizens.count)),
        hunger: Array.from(this.citizens.hunger.slice(0, this.citizens.count)),
        rest: Array.from(this.citizens.rest.slice(0, this.citizens.count)),
        social: Array.from(this.citizens.social.slice(0, this.citizens.count)),
        mood: Array.from(this.citizens.mood.slice(0, this.citizens.count)),
        health: Array.from(this.citizens.health.slice(0, this.citizens.count)),
        alive: Array.from(this.citizens.alive.slice(0, this.citizens.count)),
        flags: Array.from(this.citizens.flags.slice(0, this.citizens.count)),
        skillCombat: Array.from(this.citizens.skillCombat.slice(0, this.citizens.count)),
        skillConstruction: Array.from(this.citizens.skillConstruction.slice(0, this.citizens.count)),
        trait: this.citizens.trait.slice(0, this.citizens.count).map(t => t?.name ?? null),
      },
      roster: Array.from(this.roster._roleById.entries()).map(([id, kind]) => ({
        id, kind, post: this.roster._postById.get(id) || null,
      })),
      structures: this.structures.map(s => ({
        kind: s.kind, x: s.x, y: s.y, health: s.health, destroyed: s.destroyed,
        underConstruction: s.underConstruction, buildProgress: s.buildProgress,
        _vehicleSpawned: s._vehicleSpawned || false,
        onFire: s.onFire || false, fireTicks: s.fireTicks || 0,
      })),
      zones: Array.from(this.zones.kind),
      dogs: this.dogs.map(d => ({ ownerId: d.ownerId, x: d.x, y: d.y })),
      wildAnimals: this.wildAnimals.map(a => ({ x: a.x, y: a.y })),
      resourceNodes: this.resourceNodes.map(n => ({ x: n.x, y: n.y, amount: n.amount, maxAmount: n.maxAmount, depleted: n.depleted })),
      // targetNode isn't serialized (it's a live reference into resourceNodes) -- a vehicle
      // mid-haul on save resumes as if just-departed rather than mid-route. Acceptable: it's a
      // few seconds of game time, not a correctness bug like the duplicate-vehicle-on-load one
      // this was written alongside (garages need _vehicleSpawned persisted, see above).
      vehicles: this.vehicles.map(v => ({
        kind: v.kind, fuelType: v.fuelType, garageX: v.garageX, garageY: v.garageY, x: v.x, y: v.y,
        driverId: v.driverId, phase: v.driverId == null ? 'parked' : 'inbound', workTimer: 0,
      })),
    };
  }

  static deserialize(json) {
    const w = new SimWorld(json.width, json.height, json.seed, json.aggression, 0);
    w.currentTick = json.currentTick;
    w.scrap = json.scrap;
    w.gameOver = json.gameOver || false;
    // Refugee Wagon's population gate (see the REFUGEE_* constants' doc comment) needs the
    // *original* starting count, not the 0 passed to the constructor above (deserialize always
    // reconstructs citizens from json.citizens below rather than the constructor's own spawn
    // loop) -- without this a loaded save's gate compares against 0 and the wagon never fires.
    w.startingCitizenCount = json.startingCitizenCount || (json.citizens ? json.citizens.count : 0);
    w._nextRefugeeNameIndex = json.nextRefugeeNameIndex || 0;
    if (json.finance) {
      w.finance = { ...w.finance, ...json.finance };
      const totalIncome = w.finance.killScrap + w.finance.harvestScrap + w.finance.haulScrap +
        w.finance.recyclingScrap + w.finance.conquestScrap + w.finance.otherScrap;
      w._financeLastIncome = totalIncome;
      w._financeLastExpense = w.finance.buildSpend;
    }
    w.pollution = json.pollution || 0;
    w.nuclearWaste = json.nuclearWaste || 0;
    w.ethanolPenaltyTimer = json.ethanolPenaltyTimer || 0;
    w.unrestLevel = json.unrestLevel || 0;
    w.unrestActive = json.unrestActive || false;
    w._unrestAboveTicks = json.unrestAboveTicks || 0;
    w.peakAliveCitizens = json.peakAliveCitizens || 0;
    w.attackersKilled = json.attackersKilled || 0;
    w.scrapEarnedThisRun = json.scrapEarnedThisRun || 0;
    w.storyteller = json.storyteller || 'Cassandra';
    // Pre-research saves have no `research` key -- deserializeResearch falls back to a fresh
    // state, so an old save loads with the survival core unlocked and 0 points rather than
    // throwing or silently locking everything.
    w.research = deserializeResearch(json.research);
    w.timeOfDay = json.timeOfDay != null ? json.timeOfDay : 0.3;
    w.weather = json.weather || 'Clear';
    w._weatherTimer = json.weatherTimer != null ? json.weatherTimer : w._weatherTimer;
    w.waveSpawner.waveNumber = json.waveNumber || 0;
    w.waveSpawner.nextWaveTick = json.nextWaveTick || 300;
    const c = json.citizens;
    w.citizens.count = c.count;
    for (let i = 0; i < c.count; i++) {
      w.citizens.id[i] = c.id[i];
      w.citizens.name[i] = c.name[i];
      w.citizens.x[i] = c.x[i]; w.citizens.y[i] = c.y[i];
      w.citizens.targetX[i] = c.x[i]; w.citizens.targetY[i] = c.y[i];
      w.citizens.hunger[i] = c.hunger[i]; w.citizens.rest[i] = c.rest[i]; w.citizens.social[i] = c.social[i];
      w.citizens.mood[i] = c.mood[i]; w.citizens.health[i] = c.health[i]; w.citizens.alive[i] = c.alive[i];
      w.citizens.flags[i] = c.flags ? c.flags[i] : 0;
      w.citizens.skillCombat[i] = c.skillCombat ? c.skillCombat[i] : 0;
      w.citizens.skillConstruction[i] = c.skillConstruction ? c.skillConstruction[i] : 0;
      w.citizens.trait[i] = c.trait && c.trait[i] ? TRAITS.find(t => t.name === c.trait[i]) : null;
    }
    w.roster = new (Object.getPrototypeOf(w.roster).constructor)();
    for (const r of json.roster) w.roster.assign(r.id, r.kind, r.post);
    w.structures = json.structures.map(s => {
      const built = Object.assign(new Structure(s.kind, s.x, s.y, { instant: true }), s);
      // The constructor's instant:true default marks _builtNotified true regardless of the real
      // (restored) underConstruction value -- recompute it here so a structure that was still
      // mid-build at save time can still fire its build-complete cue once it actually finishes.
      built._builtNotified = !built.underConstruction;
      return built;
    });
    if (json.zones) w.zones.kind.set(json.zones);
    if (json.dogs) w.dogs = json.dogs.map(d => ({ ...d, cooldown: 0 }));
    if (json.wildAnimals) {
      w.wildAnimals = json.wildAnimals.map(a => ({ x: a.x, y: a.y, targetX: a.x, targetY: a.y, claimedBy: null, tameTicks: 0 }));
    }
    if (json.vehicles) {
      // Citizen jobState isn't persisted (arrays default back to Idle on the fresh SimWorld
      // above), so a vehicle can't come back mid-haul with a valid driver -- every vehicle
      // loads parked; whoever was driving just needs to be reassigned by the job system.
      w.vehicles = json.vehicles.map(v => ({
        kind: v.kind, fuelType: v.fuelType || 'gas', garageX: v.garageX, garageY: v.garageY, x: v.garageX, y: v.garageY,
        driverId: null, phase: 'parked', workTimer: 0, targetNode: null,
      }));
    }
    if (json.resourceNodes) {
      w.resourceNodes = json.resourceNodes.map(n => Object.assign(new ResourceNode(n.x, n.y, n.maxAmount), n));
    }
    return w;
  }
}


// ---- render.js ----
// Procedural renderer -- draws every sprite with Canvas 2D shape primitives instead of AI-
// generated images. Visual language borrows from RimWorld/Prison Architect: flat top-down
// grid, a visible floor grid, outlined silhouettes so units read clearly against the ground,
// and zone/room tints rather than photographic texture.







const CELL = 24; // px per grid cell at zoom 1
const OUTLINE = 'rgba(20,16,12,0.75)';

const ROLE_COLOR = {
  [StaffRoleKind.Guard]: '#f2c026',
  [StaffRoleKind.Sniper]: '#bf59d9',
  [StaffRoleKind.K9Handler]: '#f2c026',
  [StaffRoleKind.Monitor]: '#59a6d9',
  [StaffRoleKind.None]: '#d3cdbf',
};

const ZONE_BORDER = {
  [ZoneKind.Bedroom]: '#5a6fb0',
  [ZoneKind.Food]: '#c98a2e',
  [ZoneKind.Recreation]: '#4a9e5f',
};

// SEA:R truck fuel-type tradeoff (see vehicles.js FUEL_TYPES) -- a stripe color per fuel so the
// dirty/clean tradeoff reads at a glance in _drawVehicles below.
const FUEL_COLOR = {
  fossil: '#6b5334',
  gas: '#3d6fa8',
  ethanol: '#5fa83d',
  electric: '#3dd0d0',
};

// Blend a hex color toward gray -- used to give OnBreak citizens a visibly washed-out look
// distinct from the flat gray used for Downed citizens (see _drawCitizens).
function desaturate(hex, amount) {
  const n = parseInt(hex.slice(1), 16);
  const r = (n >> 16) & 0xff, g = (n >> 8) & 0xff, b = n & 0xff;
  const gray = (r + g + b) / 3;
  const mix = (c) => Math.round(c + (gray - c) * amount);
  return `rgb(${mix(r)},${mix(g)},${mix(b)})`;
}

// Deterministic per-cell noise so the ground doesn't need an image asset to avoid looking flat.
function cellNoise(x, y) {
  const n = Math.sin(x * 127.1 + y * 311.7) * 43758.5453;
  return n - Math.floor(n);
}

function lerp(a, b, t) { return a + (b - a) * t; }

// Smooth value noise: bilinearly interpolates between noise sampled at integer lattice points,
// so shading blends continuously across cell boundaries instead of a per-cell checkerboard --
// "one big piece" rather than visibly tiled squares.
function smoothNoise(x, y) {
  const x0 = Math.floor(x), y0 = Math.floor(y);
  const tx = x - x0, ty = y - y0;
  const n00 = cellNoise(x0, y0), n10 = cellNoise(x0 + 1, y0);
  const n01 = cellNoise(x0, y0 + 1), n11 = cellNoise(x0 + 1, y0 + 1);
  const sx = tx * tx * (3 - 2 * tx); // smoothstep, avoids visible diagonal creases from linear lerp
  const sy = ty * ty * (3 - 2 * ty);
  return lerp(lerp(n00, n10, sx), lerp(n01, n11, sx), sy);
}

const MIN_ZOOM = 0.3;
const MAX_ZOOM = 4;

class Renderer {
  constructor(canvas) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.camX = 0; this.camY = 0; this.zoom = 1;
    // Camera starts auto-framed every few seconds (main.js); once the player pans or zooms by
    // hand, auto-reframe stops fighting them for control until they click Recenter -- there was
    // previously no manual camera control at all, and re-snapping under the player mid-drag felt
    // broken.
    this.manualCamera = false;
    // Accessibility: scoped-down colorblind mode (see main.js's Settings panel). Rather than a
    // full palette redesign, this adds shape/pattern cues on top of the existing colors -- a
    // dashed orange ring under every attacker vs. a solid blue ring under every citizen (that
    // color pair stays distinguishable under the common red-green deficiencies), plus a distinct
    // dash pattern per zone kind in _drawZones -- so the citizen/attacker and zone-kind
    // distinctions no longer rely on hue alone. Toggled by main.js, not persisted here.
    this.highContrast = false;
  }

  panByScreenDelta(dxPx, dyPx, world) {
    this.camX -= dxPx / (CELL * this.zoom);
    this.camY -= dyPx / (CELL * this.zoom);
    this.manualCamera = true;
    if (world) this._clampCamToWorld(world);
  }

  zoomAt(screenX, screenY, factor, world) {
    const [wx, wy] = this.screenToWorld(screenX, screenY);
    this.zoom = Math.max(MIN_ZOOM, Math.min(MAX_ZOOM, this.zoom * factor));
    // keep the world point under the cursor stationary on screen rather than zooming toward camX/Y
    const [nx, ny] = this.screenToWorld(screenX, screenY);
    this.camX += wx - nx;
    this.camY += wy - ny;
    this.manualCamera = true;
    if (world) this._clampCamToWorld(world);
  }

  recenter(world) {
    this.manualCamera = false;
    this.frameOnContent(world);
  }

  resize() {
    // window.innerWidth/Height can briefly report 0 before layout settles in some embedding
    // contexts; falling back to a sane default avoids getting stuck with a 0x0 canvas forever
    // (nothing else would ever retry since main.js only calls this on the 'resize' event).
    const w = window.innerWidth || 1280;
    const h = window.innerHeight || 720;
    if (this.canvas.width === w && this.canvas.height === h) return;
    this.canvas.width = w;
    this.canvas.height = h;
  }

  frameOnContent(world) {
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    for (let i = 0; i < world.citizens.count; i++) {
      if (!world.citizens.isAliveAt(i)) continue;
      minX = Math.min(minX, world.citizens.x[i]); maxX = Math.max(maxX, world.citizens.x[i]);
      minY = Math.min(minY, world.citizens.y[i]); maxY = Math.max(maxY, world.citizens.y[i]);
    }
    for (const s of world.structures) {
      minX = Math.min(minX, s.x); maxX = Math.max(maxX, s.x);
      minY = Math.min(minY, s.y); maxY = Math.max(maxY, s.y);
    }
    if (!isFinite(minX)) { minX = 0; maxX = world.width; minY = 0; maxY = world.height; }
    const pad = 6;
    const w = (maxX - minX) + pad * 2;
    const h = (maxY - minY) + pad * 2;
    this.camX = (minX + maxX) / 2;
    this.camY = (minY + maxY) / 2;
    const zoomX = this.canvas.width / (w * CELL);
    const zoomY = this.canvas.height / (h * CELL);
    this.zoom = Math.max(0.4, Math.min(2.5, Math.min(zoomX, zoomY)));
    this._clampCamToWorld(world);
  }

  // Centering on the settlement's bounding box can point the camera at a spot close enough to
  // the map edge that the viewport shows raw off-map canvas background -- a stark dark void with
  // no ground, walls, or fog, since nothing is drawn there. Pull the camera back so the visible
  // area stays inside the map whenever the map is big enough to allow it (a map smaller than the
  // viewport still letterboxes evenly, which is fine).
  _clampCamToWorld(world) {
    const viewW = this.canvas.width / (CELL * this.zoom);
    const viewH = this.canvas.height / (CELL * this.zoom);
    this.camX = viewW >= world.width
      ? world.width / 2
      : Math.min(Math.max(this.camX, viewW / 2), world.width - viewW / 2);
    this.camY = viewH >= world.height
      ? world.height / 2
      : Math.min(Math.max(this.camY, viewH / 2), world.height - viewH / 2);
  }

  worldToScreen(x, y) {
    return [
      this.canvas.width / 2 + (x - this.camX) * CELL * this.zoom,
      this.canvas.height / 2 + (y - this.camY) * CELL * this.zoom,
    ];
  }

  screenToWorld(sx, sy) {
    return [
      this.camX + (sx - this.canvas.width / 2) / (CELL * this.zoom),
      this.camY + (sy - this.canvas.height / 2) / (CELL * this.zoom),
    ];
  }

  // World-space bounds of what's currently visible in the main viewport -- used by the minimap
  // to draw the "you are here" rectangle without duplicating the worldToScreen/screenToWorld math.
  getViewBounds() {
    const [x0, y0] = this.screenToWorld(0, 0);
    const [x1, y1] = this.screenToWorld(this.canvas.width, this.canvas.height);
    return { x0, y0, x1, y1 };
  }

  // Public entry point for jumping the camera to an arbitrary world point (e.g. a minimap
  // click) -- goes through the same manual-camera + clamp path as pan/zoom so it doesn't fight
  // the auto-reframe or walk the camera off the map edge.
  jumpTo(x, y, world) {
    this.camX = x;
    this.camY = y;
    this.manualCamera = true;
    this._clampCamToWorld(world);
  }

  draw(world, input) {
    const ctx = this.ctx;
    ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
    this._drawGround(world);
    this._drawZones(world);
    this._drawResourceNodes(world);
    this._drawNuclearHazards(world);
    this._drawStructures(world);
    this._drawFire(world);
    this._drawCitizens(world);
    this._drawDogs(world);
    this._drawWildAnimals(world);
    this._drawAttackers(world);
    this._drawVehicles(world);
    this._drawSmogHaze(world);
    if (input) {
      this._drawCursor(world, input);
      this._drawSelection(world, input);
      this._drawRoomLabel(world, input);
    }
  }

  // Fire crisis event (Prison Architect/SEA:R, see fire.js): burning structures get an animated
  // flame glyph -- a radial-gradient teardrop that flickers based on world.currentTick (fixed-
  // tick-driven, not wall-clock time, so it stays deterministic/pausable like everything else).
  _drawFire(world) {
    const ctx = this.ctx;
    for (const s of world.structures) {
      if (!s.onFire || s.destroyed) continue;
      const [sx, sy] = this.worldToScreen(s.x, s.y);
      const size = CELL * this.zoom * 0.85;
      const flicker = 0.7 + 0.3 * Math.sin(world.currentTick * 0.5 + s.x * 3 + s.y * 7);
      const h = size * (0.55 + 0.25 * flicker);

      ctx.save();
      ctx.globalAlpha = 0.88;
      const grad = ctx.createRadialGradient(sx, sy - h * 0.3, 1, sx, sy - h * 0.3, h * 0.65);
      grad.addColorStop(0, 'rgba(255,240,180,0.95)');
      grad.addColorStop(0.5, 'rgba(255,140,40,0.85)');
      grad.addColorStop(1, 'rgba(200,40,20,0)');
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.moveTo(sx, sy - h);
      ctx.quadraticCurveTo(sx + size * 0.28 * flicker, sy - h * 0.5, sx, sy + size * 0.1);
      ctx.quadraticCurveTo(sx - size * 0.28 * flicker, sy - h * 0.5, sx, sy - h);
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    }
  }

  // SEA:R's tonal hook (see FEATURE_RESEARCH.md): mismanaged waste is a visible, worsening
  // liability, not just a background number -- a sickly haze that thickens with pollution.
  _drawSmogHaze(world) {
    const pollution = world.pollution || 0;
    if (pollution < 40) return;
    const ctx = this.ctx;
    const alpha = Math.min(0.35, (pollution - 40) / 400);
    ctx.fillStyle = `rgba(120,140,60,${alpha})`;
    ctx.fillRect(0, 0, this.canvas.width, this.canvas.height);
  }

  // Nuclear waste hazard (SEA:R): unlike the global smog haze above, this is a literal
  // damage-dealing area around any nuclear generator that isn't guarded by a nearby
  // waste_storage (see siege.js's tickNuclearHazard, which is what actually applies the damage
  // this is only the visual for). Sickly green/yellow warning tint, distinct from the smog's
  // duller olive so a player can tell "background pollution" from "stand here and take damage"
  // at a glance. Pulses subtly so it doesn't just look like a locked deep decal.
  _drawNuclearHazards(world) {
    const ctx = this.ctx;
    for (const s of world.structures) {
      if (s.kind !== 'generator_nuclear' || s.destroyed || s.underConstruction) continue;
      if (isNuclearContained(world.structures, s)) continue;
      const [sx, sy] = this.worldToScreen(s.x, s.y);
      const r = NUCLEAR_HAZARD_RADIUS * CELL * this.zoom;
      const pulse = 0.75 + 0.25 * Math.sin(world.currentTick * 0.15);
      const grad = ctx.createRadialGradient(sx, sy, r * 0.15, sx, sy, r);
      grad.addColorStop(0, `rgba(200,230,60,${0.28 * pulse})`);
      grad.addColorStop(0.7, `rgba(170,210,40,${0.16 * pulse})`);
      grad.addColorStop(1, 'rgba(170,210,40,0)');
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(sx, sy, r, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = `rgba(210,235,90,${0.5 * pulse})`;
      ctx.lineWidth = Math.max(1, CELL * this.zoom * 0.04);
      ctx.setLineDash([CELL * this.zoom * 0.15, CELL * this.zoom * 0.1]);
      ctx.beginPath();
      ctx.arc(sx, sy, r, 0, Math.PI * 2);
      ctx.stroke();
      ctx.setLineDash([]);
    }
  }

  _drawSelection(world, input) {
    const ctx = this.ctx;
    const r = CELL * this.zoom * 0.5;
    const ids = new Set();
    if (input.selectedCitizen != null && input.selectedCitizen >= 0) ids.add(input.selectedCitizen);
    if (input.selectedCitizens) for (const i of input.selectedCitizens) ids.add(i);
    for (const sel of ids) {
      if (sel < 0 || sel >= world.citizens.count || !world.citizens.isAliveAt(sel)) continue;
      const [sx, sy] = this.worldToScreen(world.citizens.x[sel], world.citizens.y[sel]);
      ctx.strokeStyle = '#ffffff';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(sx, sy, r, 0, Math.PI * 2);
      ctx.stroke();
    }
    this._drawMarquee(input);
  }

  // RimWorld/Prison Architect-style rubber-band select: only ever active with the Select tool
  // (armed in InputController._onDown, see input.js), a dashed rectangle from drag-start to the
  // live cursor position so the player can see what they're about to sweep up.
  _drawMarquee(input) {
    if (!input.marqueeActive) return;
    const dx = input.marqueeEndWorldX - input.marqueeStartWorldX;
    const dy = input.marqueeEndWorldY - input.marqueeStartWorldY;
    if (Math.hypot(dx, dy) < 0.15) return; // below this it's still just a click settling, not a drag
    const ctx = this.ctx;
    const [x0, y0] = this.worldToScreen(input.marqueeStartWorldX, input.marqueeStartWorldY);
    const [x1, y1] = this.worldToScreen(input.marqueeEndWorldX, input.marqueeEndWorldY);
    const x = Math.min(x0, x1), y = Math.min(y0, y1);
    const w = Math.abs(x1 - x0), h = Math.abs(y1 - y0);
    ctx.save();
    ctx.fillStyle = 'rgba(127,215,255,0.12)';
    ctx.strokeStyle = '#7fd7ff';
    ctx.lineWidth = 1.5;
    ctx.setLineDash([5, 4]);
    ctx.fillRect(x, y, w, h);
    ctx.strokeRect(x, y, w, h);
    ctx.restore();
  }

  // Rooms/zones read as painted floor material (Prison Architect's zone-tint-with-border
  // look) rather than a flat translucent wash -- a visible border is what actually reads as
  // "this is a designated area" at a glance, the fill alone didn't.
  _drawZones(world) {
    const ctx = this.ctx;
    const size = CELL * this.zoom;
    for (let y = 0; y < world.height; y++) {
      for (let x = 0; x < world.width; x++) {
        const kind = world.zones.get(x, y);
        if (kind === ZoneKind.None) continue;
        const [px, py] = this.worldToScreen(x, y);
        ctx.fillStyle = ZONE_COLOR[kind];
        ctx.fillRect(px, py, size + 1, size + 1);

        // Border only on edges touching a non-matching cell, so a solid zone reads as one
        // outlined region instead of a grid of individually-outlined squares.
        ctx.strokeStyle = ZONE_BORDER[kind];
        ctx.lineWidth = Math.max(1, size * 0.05);
        // High-contrast mode (main.js Settings panel): a distinct dash pattern per zone kind, so
        // the three zones stay distinguishable by pattern, not just by hue, for players who can't
        // easily tell the blue/orange/green fills apart.
        if (this.highContrast) {
          ctx.lineWidth = Math.max(2, size * 0.09);
          const dash = kind === ZoneKind.Bedroom ? [] : kind === ZoneKind.Food ? [size * 0.3, size * 0.15] : [size * 0.08, size * 0.08];
          ctx.setLineDash(dash);
        } else {
          ctx.setLineDash([]);
        }
        ctx.beginPath();
        if (world.zones.get(x, y - 1) !== kind) { ctx.moveTo(px, py); ctx.lineTo(px + size, py); }
        if (world.zones.get(x, y + 1) !== kind) { ctx.moveTo(px, py + size); ctx.lineTo(px + size, py + size); }
        if (world.zones.get(x - 1, y) !== kind) { ctx.moveTo(px, py); ctx.lineTo(px, py + size); }
        if (world.zones.get(x + 1, y) !== kind) { ctx.moveTo(px + size, py); ctx.lineTo(px + size, py + size); }
        ctx.stroke();
      }
    }
    ctx.setLineDash([]); // don't leak the dash pattern into unrelated strokes drawn after this
  }

  _drawCursor(world, input) {
    const ctx = this.ctx;
    if (!input.hoverGridX && input.hoverGridX !== 0) return;
    const [px, py] = this.worldToScreen(input.hoverGridX, input.hoverGridY);
    const size = CELL * this.zoom;
    ctx.strokeStyle = input.tool ? '#ffffff' : 'rgba(255,255,255,0.3)';
    ctx.lineWidth = 2;
    ctx.strokeRect(px + 1, py + 1, size - 2, size - 2);
  }

  // Room-role hover label (rooms.js's computeRoomStats/classifyRoomRole, RimWorld/Prison
  // Architect's "hover a room to see what it is" convention): only shown while no build tool is
  // selected (so it doesn't fight with zone/structure placement feedback) and only when the
  // cursor is actually over an enclosed room detectRooms found. Shows the role name, and -- if
  // the room has a matching zone but is missing furniture -- what's missing, e.g.
  // "Bedroom (needs a bed)"; a room with no matching zone at all just doesn't get a label
  // (Unroofed Area is the quiet default, not something worth bannering over every plain room).
  _drawRoomLabel(world, input) {
    if (input.tool) return;
    if (!input.hoverGridX && input.hoverGridX !== 0) return;
    const room = roomContaining(world.rooms, world.grid, input.hoverGridX + 0.5, input.hoverGridY + 0.5);
    if (!room || !room.role || room.role === RoomRole.None) return;

    const label = ROOM_ROLE_LABEL[room.role] ?? 'Room';
    const text = room.roleValid
      ? label
      : `${label} (needs ${room.missingRequirements.join(', ')})`;

    const ctx = this.ctx;
    const [px, py] = this.worldToScreen(input.hoverGridX, input.hoverGridY);
    const size = CELL * this.zoom;
    const x = px + size / 2;
    const y = py - 6;
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'bottom';
    const padX = 6, padY = 3;
    const w = ctx.measureText(text).width;
    ctx.fillStyle = room.roleValid ? 'rgba(24,22,20,0.85)' : 'rgba(90,30,20,0.85)';
    ctx.fillRect(x - w / 2 - padX, y - 14 - padY, w + padX * 2, 14 + padY * 2);
    ctx.strokeStyle = room.roleValid ? '#4a9e5f' : '#d95a3a';
    ctx.lineWidth = 1;
    ctx.strokeRect(x - w / 2 - padX, y - 14 - padY, w + padX * 2, 14 + padY * 2);
    ctx.fillStyle = '#f0ece4';
    ctx.fillText(text, x, y);
    ctx.textAlign = 'left';
    ctx.textBaseline = 'alphabetic';
  }

  // Ground is pre-rendered once into an offscreen canvas with smooth (bilinearly-interpolated)
  // noise, so it reads as one continuous blended surface -- like a Minecraft grass block seen
  // from above, not a checkerboard of individually-colored tiles. Rebuilt only when the wall
  // layout changes (walls tint the ground dark), not every frame.
  _buildGroundCache(world) {
    const SUB = 4; // samples per cell edge in the cache -- enough to hide any per-cell seam
    const cw = world.width * SUB, ch = world.height * SUB;
    const cnv = document.createElement('canvas');
    cnv.width = cw; cnv.height = ch;
    const cctx = cnv.getContext('2d');
    const img = cctx.createImageData(cw, ch);

    for (let py = 0; py < ch; py++) {
      const gy = py / SUB;
      const cellY = Math.min(world.height - 1, Math.floor(gy));
      for (let px = 0; px < cw; px++) {
        const gx = px / SUB;
        const cellX = Math.min(world.width - 1, Math.floor(gx));
        const idx = world.grid.index(cellX, cellY);
        const kind = world.grid.terrain[idx];
        const hasWall = world.grid.wallThingId[idx] !== 0;

        let base = [0.5, 0.4, 0.28]; // dirt brown, matches the GDD's scavenged-settlement palette
        if (kind === TerrainKind.Soil) base = [0.4, 0.31, 0.20];
        else if (kind === TerrainKind.Rock) base = [0.47, 0.47, 0.49];
        else if (kind === TerrainKind.Water) base = [0.18, 0.35, 0.55];
        if (hasWall) base = [0.15, 0.14, 0.16];

        const n = smoothNoise(gx * 0.6, gy * 0.6); // low frequency -> broad soft blotches, not speckle
        const shade = 0.86 + n * 0.28;
        const o = (py * cw + px) * 4;
        img.data[o] = Math.round(base[0] * 255 * shade);
        img.data[o + 1] = Math.round(base[1] * 255 * shade);
        img.data[o + 2] = Math.round(base[2] * 255 * shade);
        img.data[o + 3] = 255;
      }
    }
    cctx.putImageData(img, 0, 0);
    this._groundCache = cnv;
    this._groundCacheWallSignature = this._wallSignature(world);
  }

  _wallSignature(world) {
    let sum = 0;
    for (let i = 0; i < world.grid.wallThingId.length; i++) if (world.grid.wallThingId[i] !== 0) sum += i + 1;
    return sum;
  }

  _drawGround(world) {
    const ctx = this.ctx;
    if (!this._groundCache || this._groundCacheWallSignature !== this._wallSignature(world)) {
      this._buildGroundCache(world);
    }
    const [x0, y0] = this.worldToScreen(0, 0);
    const size = CELL * this.zoom;
    ctx.imageSmoothingEnabled = true;
    ctx.drawImage(this._groundCache, x0, y0, world.width * size, world.height * size);
  }

  _drawHumanoid(x, y, scale, bodyColor, headColor, healthFrac, isAttacker) {
    const ctx = this.ctx;
    const [sx, sy] = this.worldToScreen(x, y);
    const s = CELL * this.zoom * scale;

    if (this.highContrast && isAttacker !== undefined) {
      // Shape/pattern cue independent of hue: solid blue ring = citizen, dashed orange ring =
      // attacker. Drawn under the shadow so it reads as a ground marker, not part of the body.
      ctx.save();
      ctx.strokeStyle = isAttacker ? '#ff9500' : '#33bbff';
      ctx.lineWidth = Math.max(1.5, s * 0.09);
      ctx.setLineDash(isAttacker ? [s * 0.14, s * 0.1] : []);
      ctx.beginPath();
      ctx.ellipse(sx, sy + s * 0.1, s * 0.34, s * 0.42, 0, 0, Math.PI * 2);
      ctx.stroke();
      ctx.restore();
    }

    ctx.fillStyle = 'rgba(0,0,0,0.3)';
    ctx.beginPath();
    ctx.ellipse(sx, sy + s * 0.44, s * 0.3, s * 0.13, 0, 0, Math.PI * 2);
    ctx.fill();

    ctx.lineWidth = Math.max(1, s * 0.06);
    ctx.strokeStyle = OUTLINE;

    // legs, drawn as two short stubs beneath the body so the silhouette doesn't read as one
    // flat blob (Prison Architect/RimWorld units both have a visible torso/leg break)
    ctx.fillStyle = bodyColor;
    ctx.beginPath(); ctx.rect(sx - s * 0.16, sy + s * 0.1, s * 0.12, s * 0.22); ctx.fill(); ctx.stroke();
    ctx.beginPath(); ctx.rect(sx + s * 0.04, sy + s * 0.1, s * 0.12, s * 0.22); ctx.fill(); ctx.stroke();

    ctx.beginPath();
    ctx.rect(sx - s * 0.19, sy - s * 0.12, s * 0.38, s * 0.28);
    ctx.fill();
    ctx.stroke();

    ctx.fillStyle = headColor;
    ctx.beginPath();
    ctx.arc(sx, sy - s * 0.3, s * 0.21, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();

    if (healthFrac !== undefined && healthFrac < 0.98) {
      const barW = s * 0.5, barY = sy - s * 0.58;
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(sx - barW / 2, barY, barW, s * 0.08);
      ctx.fillStyle = healthFrac > 0.5 ? '#5fd15f' : healthFrac > 0.25 ? '#e0c040' : '#e05050';
      ctx.fillRect(sx - barW / 2, barY, barW * Math.max(0, healthFrac), s * 0.08);
    }
  }

  _drawCitizens(world) {
    for (let i = 0; i < world.citizens.count; i++) {
      if (!world.citizens.isAliveAt(i)) continue;
      if (world.citizens.jobState[i] === JobState.Driving) continue; // riding inside a vehicle, drawn as part of it
      const id = world.citizens.id[i];
      const downed = world.citizens.isDownedAt(i);
      const onBreak = !downed && world.citizens.isOnBreakAt(i);
      const role = world.roster.isStaff(id) ? world.roster.kindOf(id) : StaffRoleKind.None;
      const baseColor = ROLE_COLOR[role] || ROLE_COLOR[StaffRoleKind.None];
      const color = downed ? '#6b6b6b' : onBreak ? desaturate(baseColor, 0.6) : baseColor;
      const headColor = downed ? '#8a8a8a' : onBreak ? desaturate('#e8c9a0', 0.6) : '#e8c9a0';
      const [sx, sy] = this.worldToScreen(world.citizens.x[i], world.citizens.y[i]);
      this._drawHumanoid(world.citizens.x[i], world.citizens.y[i], downed ? 0.5 : 0.7, color, headColor, world.citizens.health[i], false);
      if (onBreak) {
        // Small "zzz" tell above the head so low-mood citizens read clearly at a glance,
        // distinct from the flat-gray Downed silhouette.
        const s = CELL * this.zoom * 0.7;
        this.ctx.save();
        this.ctx.font = `${Math.max(8, s * 0.32)}px sans-serif`;
        this.ctx.fillStyle = 'rgba(140,150,200,0.9)';
        this.ctx.textAlign = 'center';
        this.ctx.fillText('z', sx + s * 0.32, sy - s * 0.62);
        this.ctx.restore();
      }
    }
  }

  // Tamed dogs (world.dogs, roster-assignable/combat-capable) get a warm coat + a gold collar
  // ring; wild untamed animals (world.wildAnimals, see security.js/jobs.js's Taming job) reuse
  // the same silhouette in a duller, uncollared coat so "this one isn't yours yet" reads clearly
  // at a glance without needing a whole separate sprite.
  _drawDogs(world) {
    this._drawAnimal(world.dogs, '#7a5230', '#f2c026');
  }

  _drawWildAnimals(world) {
    this._drawAnimal(world.wildAnimals, '#8f8a76', null);
  }

  _drawAnimal(list, coatColor, collarColor) {
    const ctx = this.ctx;
    for (const dog of list || []) {
      const [sx, sy] = this.worldToScreen(dog.x, dog.y);
      const s = CELL * this.zoom * 0.4;
      ctx.fillStyle = 'rgba(0,0,0,0.3)';
      ctx.beginPath(); ctx.ellipse(sx, sy + s * 0.22, s * 0.34, s * 0.1, 0, 0, Math.PI * 2); ctx.fill();
      ctx.lineWidth = Math.max(1, s * 0.08);
      ctx.strokeStyle = OUTLINE;
      ctx.fillStyle = coatColor;
      ctx.beginPath();
      ctx.ellipse(sx, sy, s * 0.32, s * 0.2, 0, 0, Math.PI * 2);
      ctx.fill(); ctx.stroke();
      ctx.beginPath();
      ctx.arc(sx + s * 0.28, sy - s * 0.05, s * 0.14, 0, Math.PI * 2);
      ctx.fill(); ctx.stroke();
      if (collarColor) {
        ctx.strokeStyle = collarColor;
        ctx.lineWidth = Math.max(1, s * 0.1);
        ctx.beginPath();
        ctx.arc(sx + s * 0.28, sy - s * 0.05, s * 0.19, 0, Math.PI * 2);
        ctx.stroke();
      }
    }
  }

  // Per-archetype silhouettes (see siege.js's ATTACKER_ARCHETYPES): size and palette both shift
  // so the roster is readable at a glance mid-siege without reading a single number.
  //   Grunt      -- the original small dark-red raider (unchanged, the baseline)
  //   Brute      -- noticeably larger, heavy slate-plated
  //   Skirmisher -- smaller and lighter/oranger, reads as "fast and flimsy"
  //   Boss       -- much larger, violet, plus a pulsing threat ring and a spiked crown
  static ATTACKER_STYLES = [
    { scale: 0.6,  body: '#8a1f1f', head: '#c76b4a' }, // Grunt
    { scale: 0.85, body: '#4a4438', head: '#8f7a5c' }, // Brute
    { scale: 0.48, body: '#b0521f', head: '#e0a06a' }, // Skirmisher
    { scale: 1.25, body: '#4a1f5e', head: '#c469e0' }, // Boss
  ];

  _drawAttackers(world) {
    const ctx = this.ctx;
    for (let i = 0; i < world.attackers.count; i++) {
      if (!world.attackers.isAliveAt(i)) continue;
      const kind = world.attackers.kind ? world.attackers.kind[i] : 0;
      const style = Renderer.ATTACKER_STYLES[kind] || Renderer.ATTACKER_STYLES[0];
      const isBoss = kind === 3;

      if (isBoss) {
        // Threat ring under the boss, pulsing off the wall clock so it's obvious even when the
        // sim is paused. Drawn before the body so it reads as ground marking, not an outline.
        const [bx, by] = this.worldToScreen(world.attackers.x[i], world.attackers.y[i]);
        const s = CELL * this.zoom * style.scale;
        const pulse = 0.75 + 0.25 * Math.sin(Date.now() / 220);
        ctx.save();
        ctx.strokeStyle = 'rgba(200,90,235,0.85)';
        ctx.lineWidth = Math.max(2, s * 0.09);
        ctx.beginPath();
        ctx.ellipse(bx, by + s * 0.42, s * 0.6 * pulse, s * 0.26 * pulse, 0, 0, Math.PI * 2);
        ctx.stroke();
        ctx.fillStyle = 'rgba(150,40,190,0.18)';
        ctx.fill();
        ctx.restore();
      }

      this._drawHumanoid(world.attackers.x[i], world.attackers.y[i], style.scale,
        style.body, style.head, world.attackers.health[i], true);

      if (isBoss) {
        // Spiked crown on top of the head so the boss is distinguishable even in a dense crowd
        // where the ground ring is occluded.
        const [bx, by] = this.worldToScreen(world.attackers.x[i], world.attackers.y[i]);
        const s = CELL * this.zoom * style.scale;
        ctx.save();
        ctx.fillStyle = '#f0c040';
        ctx.strokeStyle = OUTLINE;
        ctx.lineWidth = Math.max(1, s * 0.05);
        ctx.beginPath();
        const baseY = by - s * 0.46, w = s * 0.34;
        ctx.moveTo(bx - w / 2, baseY);
        for (let k = 0; k < 3; k++) {
          ctx.lineTo(bx - w / 2 + w * (k + 0.5) / 3, baseY - s * 0.22);
          ctx.lineTo(bx - w / 2 + w * (k + 1) / 3, baseY);
        }
        ctx.closePath();
        ctx.fill(); ctx.stroke();
        ctx.restore();
      }
    }
  }

  _drawStructures(world) {
    const ctx = this.ctx;
    this._structuresForPower = world.structures; // read back by the 'wire' shape for its lit/dark tint
    for (const s of world.structures) {
      if (s.destroyed && s.kind === 'trap') continue; // traps vanish once triggered
      const [sx, sy] = this.worldToScreen(s.x, s.y);
      const size = CELL * this.zoom * 0.85;

      if (s.kind !== 'fence' && s.kind !== 'wire' && s.kind !== 'pipe') {
        ctx.fillStyle = 'rgba(0,0,0,0.25)';
        ctx.beginPath();
        ctx.ellipse(sx, sy + size * 0.4, size * 0.35, size * 0.12, 0, 0, Math.PI * 2);
        ctx.fill();
      }

      ctx.save();
      if (s.underConstruction) ctx.globalAlpha = 0.4 + 0.3 * (s.buildProgress || 0);
      this._drawStructureShape(ctx, s, sx, sy, size);
      ctx.restore();

      if (s.underConstruction && (s.buildProgress || 0) > 0) {
        const barW = size * 0.9;
        ctx.fillStyle = 'rgba(0,0,0,0.5)';
        ctx.fillRect(sx - barW / 2, sy + size * 0.55, barW, size * 0.1);
        ctx.fillStyle = '#e0a336';
        ctx.fillRect(sx - barW / 2, sy + size * 0.55, barW * s.buildProgress, size * 0.1);
      }
    }
  }

  _drawStructureShape(ctx, s, sx, sy, size) {
    ctx.lineWidth = Math.max(1, size * 0.05);
    ctx.strokeStyle = OUTLINE;

    // Overload warning ring (power.js's overload mechanic): drawn underneath the tile's own
    // shape so it reads as a hazard glow around the wire/generator, not a replacement paint job.
    // Pulses off the wall clock (same pattern as the boss threat-ring above) so it's still
    // visible while the sim is paused.
    if ((s.kind === 'wire' || s.kind.startsWith('generator')) && !s.destroyed && !s.underConstruction &&
      isSegmentOverloadedAt(this._structuresForPower || [], s.x, s.y)) {
      const pulse = 0.5 + 0.5 * Math.sin(Date.now() / 180);
      ctx.save();
      ctx.strokeStyle = `rgba(230,40,30,${0.5 + 0.4 * pulse})`;
      ctx.lineWidth = Math.max(2, size * 0.14);
      ctx.beginPath();
      ctx.arc(sx, sy, size * 0.62, 0, Math.PI * 2);
      ctx.stroke();
      ctx.restore();
    }

    if (s.kind === 'wall') {
      ctx.fillStyle = '#413c34';
      ctx.fillRect(sx - size / 2, sy - size / 2, size, size);
      ctx.strokeRect(sx - size / 2, sy - size / 2, size, size);
      return;
    }
    if (s.kind === 'fence') {
      ctx.strokeStyle = s.destroyed ? 'rgba(80,60,40,0.4)' : '#a8825a';
      ctx.lineWidth = Math.max(2, size * 0.12);
      ctx.beginPath();
      ctx.moveTo(sx - size / 2, sy);
      ctx.lineTo(sx + size / 2, sy);
      ctx.stroke();
      return;
    }
    if (s.kind === 'trap') {
      ctx.fillStyle = 'rgba(140,20,20,0.55)';
      ctx.beginPath();
      ctx.arc(sx, sy, size * 0.3, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();
      return;
    }
    if (s.kind === 'bed') {
      ctx.fillStyle = '#5a6fb0';
      ctx.fillRect(sx - size * 0.4, sy - size * 0.3, size * 0.8, size * 0.6);
      ctx.strokeRect(sx - size * 0.4, sy - size * 0.3, size * 0.8, size * 0.6);
      ctx.fillStyle = '#8898cc';
      ctx.fillRect(sx - size * 0.4, sy - size * 0.3, size * 0.8, size * 0.18);
      return;
    }
    if (s.kind === 'table') {
      ctx.fillStyle = '#a87d4a';
      ctx.fillRect(sx - size * 0.4, sy - size * 0.28, size * 0.8, size * 0.56);
      ctx.strokeRect(sx - size * 0.4, sy - size * 0.28, size * 0.8, size * 0.56);
      return;
    }
    if (s.kind === 'door') {
      ctx.fillStyle = '#7a5a30';
      ctx.fillRect(sx - size * 0.35, sy - size * 0.42, size * 0.7, size * 0.84);
      ctx.strokeRect(sx - size * 0.35, sy - size * 0.42, size * 0.7, size * 0.84);
      return;
    }
    if (s.kind === 'garage_recycling' || s.kind === 'garage_garbage') {
      ctx.fillStyle = s.kind === 'garage_recycling' ? '#3a5a3f' : '#5a5030';
      ctx.fillRect(sx - size * 0.45, sy - size * 0.4, size * 0.9, size * 0.8);
      ctx.strokeRect(sx - size * 0.45, sy - size * 0.4, size * 0.9, size * 0.8);
      ctx.fillStyle = '#1a1a1a';
      ctx.fillRect(sx - size * 0.3, sy - size * 0.1, size * 0.6, size * 0.42); // garage door opening
      return;
    }
    if (s.kind === 'watchtower') {
      ctx.fillStyle = '#5a4a3a';
      ctx.fillRect(sx - size * 0.15, sy - size * 0.1, size * 0.3, size * 0.55); // support post
      ctx.fillStyle = '#8c949e';
      ctx.fillRect(sx - size * 0.4, sy - size * 0.5, size * 0.8, size * 0.35); // watch platform
      ctx.strokeRect(sx - size * 0.4, sy - size * 0.5, size * 0.8, size * 0.35);
      return;
    }
    if (s.kind === 'camera') {
      // Cheap CCTV camera: a mounting post + a small angled lens housing with a "lit lens" dot,
      // deliberately smaller/plainer than the watchtower platform (cheaper, shorter-range).
      ctx.fillStyle = '#4a4a4a';
      ctx.fillRect(sx - size * 0.06, sy - size * 0.05, size * 0.12, size * 0.4); // mounting post
      ctx.save();
      ctx.translate(sx, sy - size * 0.32);
      ctx.rotate(-0.4);
      ctx.fillStyle = '#2b2b2b';
      ctx.fillRect(-size * 0.28, -size * 0.14, size * 0.5, size * 0.24);
      ctx.strokeRect(-size * 0.28, -size * 0.14, size * 0.5, size * 0.24);
      ctx.fillStyle = s.destroyed ? '#5a1a1a' : '#59a6d9';
      ctx.beginPath();
      ctx.arc(size * 0.22, -size * 0.02, size * 0.07, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
      return;
    }
    if (s.kind === 'monitor_station') {
      // A desk with a bank of CCTV screens -- staffed/unstaffed reads via screen brightness so
      // the "manned monitor bonus" is visible on the map, not just in the milestone log.
      ctx.fillStyle = '#5a4630';
      ctx.fillRect(sx - size * 0.42, sy - size * 0.08, size * 0.84, size * 0.4); // desk
      ctx.strokeRect(sx - size * 0.42, sy - size * 0.08, size * 0.84, size * 0.4);
      ctx.fillStyle = '#2b2b2b';
      ctx.fillRect(sx - size * 0.4, sy - size * 0.48, size * 0.84, size * 0.4); // monitor bank
      ctx.strokeRect(sx - size * 0.4, sy - size * 0.48, size * 0.84, size * 0.4);
      ctx.fillStyle = s.destroyed ? '#3a3a3a' : (s._staffed ? '#7ad9a0' : '#3a5a6a');
      ctx.fillRect(sx - size * 0.34, sy - size * 0.42, size * 0.3, size * 0.28);
      ctx.fillRect(sx + size * 0.04, sy - size * 0.42, size * 0.3, size * 0.28);
      return;
    }
    if (s.kind === 'wire') {
      // Thin conduit run rather than a box (same visual logic as 'fence'), drawn as a cross so
      // a chain of them reads as continuous cable in any direction. Lit amber only when the
      // segment is actually carrying power back to a generator; dead segments stay dull grey.
      const live = !s.destroyed && !s.underConstruction && isTileEnergized(this._structuresForPower || [], s.x, s.y);
      ctx.strokeStyle = live ? '#e0a336' : 'rgba(110,105,95,0.75)';
      ctx.lineWidth = Math.max(1.5, size * 0.1);
      ctx.beginPath();
      ctx.moveTo(sx - size / 2, sy); ctx.lineTo(sx + size / 2, sy);
      ctx.moveTo(sx, sy - size / 2); ctx.lineTo(sx, sy + size / 2);
      ctx.stroke();
      ctx.fillStyle = live ? '#f5cf80' : '#57534b';
      ctx.beginPath(); ctx.arc(sx, sy, size * 0.12, 0, Math.PI * 2); ctx.fill();
      return;
    }
    if (s.kind === 'pipe') {
      // Water's answer to 'wire' above -- same thin cross-conduit shape so a chain reads as one
      // continuous run, but blue-tinted instead of wire's amber so the two grids never get
      // visually confused when they're laid side by side. Lit only when actually carrying water
      // back to a pump; dead segments stay a dull blue-grey.
      const flowing = !s.destroyed && !s.underConstruction && isTileWatered(this._structuresForPower || [], s.x, s.y);
      ctx.strokeStyle = flowing ? '#3ea0d9' : 'rgba(90,105,115,0.75)';
      ctx.lineWidth = Math.max(1.5, size * 0.1);
      ctx.beginPath();
      ctx.moveTo(sx - size / 2, sy); ctx.lineTo(sx + size / 2, sy);
      ctx.moveTo(sx, sy - size / 2); ctx.lineTo(sx, sy + size / 2);
      ctx.stroke();
      ctx.fillStyle = flowing ? '#9adcf5' : '#5f6d72';
      ctx.beginPath(); ctx.arc(sx, sy, size * 0.12, 0, Math.PI * 2); ctx.fill();
      return;
    }
    if (s.kind === 'pump') {
      // Small well/tower silhouette -- a squat cylindrical drum with a raised spout, distinct
      // from the generator's boxy housing so the two source buildings don't read as siblings.
      const running = !s.destroyed && !s.underConstruction;
      ctx.fillStyle = running ? '#2e5266' : 'rgba(46,60,68,0.6)';
      ctx.beginPath();
      ctx.ellipse(sx, sy, size * 0.36, size * 0.4, 0, 0, Math.PI * 2);
      ctx.fill(); ctx.stroke();
      ctx.fillStyle = running ? '#3ea0d9' : '#5a6a70'; // water-level band
      ctx.beginPath();
      ctx.ellipse(sx, sy + size * 0.08, size * 0.28, size * 0.16, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = running ? '#8c949e' : 'rgba(120,120,120,0.6)';
      ctx.fillRect(sx - size * 0.06, sy - size * 0.5, size * 0.12, size * 0.24); // spout
      return;
    }
    if (s.kind === 'generator') {
      const running = !s.destroyed && !s.underConstruction;
      ctx.fillStyle = running ? '#4a4a52' : 'rgba(60,60,64,0.6)';
      ctx.fillRect(sx - size * 0.42, sy - size * 0.42, size * 0.84, size * 0.84);
      ctx.strokeRect(sx - size * 0.42, sy - size * 0.42, size * 0.84, size * 0.84);
      ctx.fillStyle = running ? '#e0a336' : '#6a6250'; // core light goes dark when it isn't running
      ctx.beginPath();
      ctx.arc(sx, sy, size * 0.18, 0, Math.PI * 2);
      ctx.fill();
      return;
    }
    if (s.kind === 'generator_nuclear') {
      // Deliberately reads as heavier/more industrial than the plain generator (dark cooling-
      // tower silhouette) with a glowing sickly-green core instead of the plain generator's warm
      // amber -- the same green family as the hazard radius so the two visually associate.
      const running = !s.destroyed && !s.underConstruction;
      ctx.fillStyle = running ? '#2e3230' : 'rgba(40,44,42,0.6)';
      ctx.fillRect(sx - size * 0.46, sy - size * 0.46, size * 0.92, size * 0.92);
      ctx.strokeRect(sx - size * 0.46, sy - size * 0.46, size * 0.92, size * 0.92);
      // trefoil-ish radiation glyph: three wedges around a hot core
      ctx.fillStyle = running ? '#161816' : '#3a3e3c';
      ctx.beginPath(); ctx.arc(sx, sy, size * 0.3, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = running ? '#c8e63c' : '#5a6650';
      for (let k = 0; k < 3; k++) {
        const a = (k / 3) * Math.PI * 2 - Math.PI / 2;
        ctx.beginPath();
        ctx.moveTo(sx, sy);
        ctx.arc(sx, sy, size * 0.26, a - 0.35, a + 0.35);
        ctx.closePath();
        ctx.fill();
      }
      ctx.fillStyle = running ? '#e8ffb0' : '#7a8570';
      ctx.beginPath(); ctx.arc(sx, sy, size * 0.08, 0, Math.PI * 2); ctx.fill();
      return;
    }
    if (s.kind === 'generator_coal') {
      // "Worse plain generator": a squatter, dirtier housing than 'generator' -- a small coal pile
      // out front and a dull red (not amber) core light so it visually reads as the cheaper, more
      // polluting choice at a glance.
      const running = !s.destroyed && !s.underConstruction;
      ctx.fillStyle = running ? '#3a332c' : 'rgba(50,46,40,0.6)';
      ctx.fillRect(sx - size * 0.4, sy - size * 0.36, size * 0.8, size * 0.72);
      ctx.strokeRect(sx - size * 0.4, sy - size * 0.36, size * 0.8, size * 0.72);
      ctx.fillStyle = running ? '#1a1a1a' : '#3a3a3a'; // coal pile
      ctx.beginPath();
      ctx.moveTo(sx - size * 0.3, sy + size * 0.36);
      ctx.lineTo(sx - size * 0.05, sy + size * 0.12);
      ctx.lineTo(sx + size * 0.2, sy + size * 0.36);
      ctx.closePath();
      ctx.fill();
      ctx.fillStyle = running ? '#c0492e' : '#5a4a44'; // dull red core, not the plain generator's amber
      ctx.beginPath();
      ctx.arc(sx + size * 0.18, sy - size * 0.12, size * 0.13, 0, Math.PI * 2);
      ctx.fill();
      return;
    }
    if (s.kind === 'generator_wind') {
      // Turbine silhouette: a slim mast + three blades. _windSited (power.js's isWindSited,
      // recomputed live off the current structures list) tints the blades pale blue when actually
      // acting as a power source and rust-red when crowded/badly sited, so the siting tradeoff is
      // visible on the map, not just in a tooltip.
      const running = !s.destroyed && !s.underConstruction;
      const sited = s._windSited !== false;
      ctx.fillStyle = running ? '#5a5a5a' : 'rgba(70,70,70,0.6)';
      ctx.fillRect(sx - size * 0.05, sy - size * 0.05, size * 0.1, size * 0.55); // mast
      ctx.fillStyle = running ? (sited ? '#bfe6f5' : '#c76b4a') : '#6a6a6a';
      for (let k = 0; k < 3; k++) {
        const a = (k / 3) * Math.PI * 2;
        ctx.save();
        ctx.translate(sx, sy - size * 0.28);
        ctx.rotate(a);
        ctx.beginPath();
        ctx.ellipse(0, -size * 0.24, size * 0.07, size * 0.24, 0, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();
      }
      ctx.fillStyle = running ? '#3a3a3a' : '#5a5a5a';
      ctx.beginPath(); ctx.arc(sx, sy - size * 0.28, size * 0.06, 0, Math.PI * 2); ctx.fill();
      return;
    }
    if (s.kind === 'generator_solar') {
      // Flat panel array in a grid pattern, tilted slightly (a parallelogram, not a square) so it
      // reads as a solar panel rather than another generic box. Panel tint follows s._openSky
      // (world.js's tick(), read back by power.js's isSource) the same sited/unsited color logic
      // as the wind turbine above: bright blue when actually acting as a power source, dull grey
      // when stuck inside an enclosed room.
      const running = !s.destroyed && !s.underConstruction;
      const openSky = s._openSky !== false;
      ctx.fillStyle = running ? '#2a3038' : 'rgba(45,50,56,0.6)';
      ctx.beginPath();
      ctx.moveTo(sx - size * 0.45, sy + size * 0.3);
      ctx.lineTo(sx - size * 0.2, sy - size * 0.35);
      ctx.lineTo(sx + size * 0.45, sy - size * 0.35);
      ctx.lineTo(sx + size * 0.2, sy + size * 0.3);
      ctx.closePath();
      ctx.fill(); ctx.stroke();
      // Panel grid lines: interpolate between the bottom edge (bottomLeft -> bottomRight) and the
      // top edge (topLeft -> topRight) so the divider lines stay parallel to the panel's tilt.
      const blX = sx - size * 0.45, blY = sy + size * 0.3;
      const brX = sx + size * 0.2, brY = sy + size * 0.3;
      const tlX = sx - size * 0.2, tlY = sy - size * 0.35;
      const trX = sx + size * 0.45, trY = sy - size * 0.35;
      ctx.strokeStyle = running ? (openSky ? '#5aa0d9' : '#6a6e72') : 'rgba(90,95,100,0.5)';
      ctx.lineWidth = Math.max(1, size * 0.03);
      for (let k = 1; k < 3; k++) {
        const t = k / 3;
        ctx.beginPath();
        ctx.moveTo(blX + (brX - blX) * t, blY + (brY - blY) * t);
        ctx.lineTo(tlX + (trX - tlX) * t, tlY + (trY - tlY) * t);
        ctx.stroke();
      }
      return;
    }
    if (s.kind === 'waste_storage') {
      // Squat drum cluster, hazard-striped so it reads as "the thing that fixes the green zone"
      // at a glance, distinct from the recycling center's green triangle icon (that's a different
      // resource loop -- pollution, not nuclear waste).
      ctx.fillStyle = s.destroyed ? 'rgba(70,64,30,0.5)' : '#4a4626';
      ctx.fillRect(sx - size * 0.4, sy - size * 0.38, size * 0.8, size * 0.76);
      ctx.strokeRect(sx - size * 0.4, sy - size * 0.38, size * 0.8, size * 0.76);
      ctx.fillStyle = s.destroyed ? 'rgba(160,150,40,0.4)' : '#d9c93a';
      for (const dx of [-0.22, 0.22]) {
        ctx.beginPath();
        ctx.arc(sx + size * dx, sy, size * 0.16, 0, Math.PI * 2);
        ctx.fill();
        ctx.stroke();
      }
      return;
    }
    if (s.kind === 'recycling_center') {
      ctx.fillStyle = '#2e5a4a';
      ctx.fillRect(sx - size * 0.45, sy - size * 0.42, size * 0.9, size * 0.84);
      ctx.strokeRect(sx - size * 0.45, sy - size * 0.42, size * 0.9, size * 0.84);
      ctx.fillStyle = '#7ad9a0';
      ctx.beginPath();
      ctx.moveTo(sx, sy - size * 0.2); ctx.lineTo(sx + size * 0.16, sy); ctx.lineTo(sx, sy + size * 0.2);
      ctx.lineTo(sx - size * 0.16, sy); ctx.closePath();
      ctx.fill();
      return;
    }
    if (s.kind === 'floodlight') {
      if (!s.destroyed) {
        ctx.fillStyle = 'rgba(230,230,150,0.12)';
        ctx.beginPath(); ctx.arc(sx, sy, size * 1.4, 0, Math.PI * 2); ctx.fill();
      }
      ctx.fillStyle = '#8c8060';
      ctx.fillRect(sx - size * 0.08, sy - size * 0.1, size * 0.16, size * 0.5);
      ctx.fillStyle = s.destroyed ? '#5a5540' : '#f2eec0';
      ctx.beginPath(); ctx.arc(sx, sy - size * 0.22, size * 0.22, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
      return;
    }
    if (s.kind === 'tesla') {
      ctx.fillStyle = s.destroyed ? 'rgba(60,60,60,0.6)' : '#4a5a8c';
      ctx.beginPath(); ctx.arc(sx, sy + size * 0.15, size * 0.35, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
      ctx.strokeStyle = s.destroyed ? 'rgba(120,140,220,0.3)' : '#a0c0ff';
      ctx.lineWidth = Math.max(1, size * 0.06);
      ctx.beginPath(); ctx.arc(sx, sy - size * 0.15, size * 0.16, 0, Math.PI * 2); ctx.stroke();
      return;
    }
    if (s.kind === 'armory') {
      ctx.fillStyle = s.destroyed ? 'rgba(60,60,60,0.6)' : '#5a4a38';
      ctx.fillRect(sx - size * 0.45, sy - size * 0.42, size * 0.9, size * 0.84);
      ctx.strokeRect(sx - size * 0.45, sy - size * 0.42, size * 0.9, size * 0.84);
      // Crossed-rifles glyph -- reads as "weapons issued here" at a glance, same idea as the
      // recycling center's arrow icon just above.
      ctx.strokeStyle = s.destroyed ? 'rgba(150,150,150,0.4)' : '#d8cba0';
      ctx.lineWidth = Math.max(1, size * 0.07);
      ctx.beginPath();
      ctx.moveTo(sx - size * 0.2, sy - size * 0.18); ctx.lineTo(sx + size * 0.2, sy + size * 0.18);
      ctx.moveTo(sx - size * 0.2, sy + size * 0.18); ctx.lineTo(sx + size * 0.2, sy - size * 0.18);
      ctx.stroke();
      return;
    }
    // turret (default)
    ctx.fillStyle = s.destroyed ? 'rgba(60,60,60,0.6)' : '#8c949e';
    ctx.fillRect(sx - size / 2, sy - size / 2, size, size);
    ctx.strokeRect(sx - size / 2, sy - size / 2, size, size);
    if (!s.destroyed) {
      ctx.fillStyle = '#2b2b2b';
      ctx.fillRect(sx - size * 0.08, sy - size * 0.6, size * 0.16, size * 0.4);
    }
  }

  _drawResourceNodes(world) {
    const ctx = this.ctx;
    for (const n of world.resourceNodes || []) {
      if (n.depleted) continue;
      const [sx, sy] = this.worldToScreen(n.x, n.y);
      const s = CELL * this.zoom * (0.35 + 0.35 * (n.amount / n.maxAmount));
      ctx.lineWidth = Math.max(1, s * 0.06);
      ctx.strokeStyle = OUTLINE;
      ctx.fillStyle = '#8a8060';
      ctx.beginPath();
      ctx.moveTo(sx - s * 0.5, sy + s * 0.3);
      ctx.lineTo(sx - s * 0.15, sy - s * 0.35);
      ctx.lineTo(sx + s * 0.2, sy - s * 0.1);
      ctx.lineTo(sx + s * 0.5, sy + s * 0.35);
      ctx.closePath();
      ctx.fill();
      ctx.stroke();
      ctx.fillStyle = '#b5aa80';
      ctx.fillRect(sx - s * 0.1, sy - s * 0.15, s * 0.18, s * 0.18);
    }
  }

  _drawVehicles(world) {
    const ctx = this.ctx;
    for (const v of world.vehicles || []) {
      const parked = v.driverId == null;
      const [sx, sy] = this.worldToScreen(v.x, v.y);
      const s = CELL * this.zoom * 0.75;
      ctx.save();
      if (parked) ctx.globalAlpha = 0.55; // dimmed -- signals "needs a driver" at a glance
      ctx.fillStyle = 'rgba(0,0,0,0.3)';
      ctx.beginPath(); ctx.ellipse(sx, sy + s * 0.4, s * 0.55, s * 0.14, 0, 0, Math.PI * 2); ctx.fill();
      ctx.lineWidth = Math.max(1, s * 0.06);
      ctx.strokeStyle = OUTLINE;
      ctx.fillStyle = v.kind === 'recycling' ? '#3d7a4a' : '#7a6a3d';
      ctx.fillRect(sx - s * 0.5, sy - s * 0.32, s, s * 0.64);
      ctx.strokeRect(sx - s * 0.5, sy - s * 0.32, s, s * 0.64);
      // SEA:R fuel-type tradeoff (vehicles.js FUEL_TYPES): a colored fuel-tank stripe makes the
      // dirty/clean tradeoff visible at a glance without needing to inspect the truck --
      // fossil=sooty brown, gas=blue (the "best all-around" default), ethanol=green (clean but
      // food-cost), electric=cyan (cleanest, power-hungry).
      ctx.fillStyle = FUEL_COLOR[v.fuelType] || FUEL_COLOR.gas;
      ctx.fillRect(sx - s * 0.5, sy - s * 0.32, s, s * 0.12);
      ctx.fillStyle = '#222';
      ctx.beginPath(); ctx.arc(sx - s * 0.3, sy + s * 0.32, s * 0.14, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.arc(sx + s * 0.3, sy + s * 0.32, s * 0.14, 0, Math.PI * 2); ctx.fill();
      if (v.phase === 'working') {
        ctx.fillStyle = 'rgba(255,255,255,0.7)';
        ctx.fillRect(sx - s * 0.1, sy - s * 0.55, s * 0.2, s * 0.15);
      }
      ctx.restore();
      if (parked) {
        ctx.fillStyle = '#e0a336';
        ctx.font = `${Math.round(s * 0.4)}px sans-serif`;
        ctx.textAlign = 'center';
        ctx.fillText('?', sx, sy - s * 0.5);
      }
    }
  }

  // Low-detail top-down overview into a separate small canvas (see index.html #minimap) --
  // deliberately skips _buildGroundCache/_drawGround's noise shading (way more detail than a
  // handful of on-screen pixels can show) in favor of a flat fill plus dots/rects, so it stays
  // cheap to redraw every frame at a totally different scale than the main viewport.
  drawMinimap(world, mmCanvas) {
    const ctx = mmCanvas.getContext('2d');
    const W = mmCanvas.width, H = mmCanvas.height;
    const sx = W / world.width, sy = H / world.height;

    ctx.clearRect(0, 0, W, H);
    ctx.fillStyle = '#3a322a'; // flat ground tone, matches the canvas background elsewhere
    ctx.fillRect(0, 0, W, H);

    // structures -- small neutral squares, not trying to distinguish kind at this scale
    ctx.fillStyle = '#c9bfa8';
    for (const s of world.structures) {
      if (s.destroyed && s.kind === 'trap') continue;
      ctx.fillRect(s.x * sx - 1, s.y * sy - 1, 2, 2);
    }

    // citizens
    ctx.fillStyle = '#e8c9a0';
    for (let i = 0; i < world.citizens.count; i++) {
      if (!world.citizens.isAliveAt(i)) continue;
      ctx.fillRect(world.citizens.x[i] * sx - 1, world.citizens.y[i] * sy - 1, 2, 2);
    }

    // attackers -- the single most useful thing a minimap tells you during a siege is "where is
    // the wave coming from," so these get the loudest, most distinct color and a bigger dot.
    ctx.fillStyle = '#ff3b30';
    for (let i = 0; i < world.attackers.count; i++) {
      if (!world.attackers.isAliveAt(i)) continue;
      // Bosses get a fatter, brighter dot -- "there is a boss and it is HERE" is exactly the
      // kind of thing the minimap exists to tell you.
      const boss = world.attackers.kind && world.attackers.kind[i] === 3;
      if (boss) ctx.fillStyle = '#e05aff';
      const r = boss ? 3 : 1.5;
      ctx.fillRect(world.attackers.x[i] * sx - r, world.attackers.y[i] * sy - r, r * 2, r * 2);
      if (boss) ctx.fillStyle = '#ff3b30';
    }

    // viewport rectangle -- what the main camera currently frames
    const { x0, y0, x1, y1 } = this.getViewBounds();
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 1;
    ctx.strokeRect(
      Math.round(x0 * sx) + 0.5, Math.round(y0 * sy) + 0.5,
      Math.max(1, (x1 - x0) * sx), Math.max(1, (y1 - y0) * sy),
    );
  }

  /** Budget report sparkline (Prison Architect's finance ledger, see world.js's finance comment
   *  and FEATURE_RESEARCH.md's Prison Architect section): plain Canvas 2D bar chart of
   *  world.finance.history, one bar per snapshot, green for a net-positive wave-cycle and red for
   *  net-negative -- same "manual line/bar-plot in a small inline canvas" spirit as drawMinimap
   *  above, just DOM-driven (called from main.js only while the budget overlay is open) rather
   *  than every frame. */
  drawFinanceChart(world, chartCanvas) {
    const ctx = chartCanvas.getContext('2d');
    const W = chartCanvas.width, H = chartCanvas.height;
    ctx.clearRect(0, 0, W, H);
    ctx.fillStyle = '#241f1a';
    ctx.fillRect(0, 0, W, H);

    const history = world.finance?.history || [];
    if (history.length === 0) {
      ctx.fillStyle = '#a89e90';
      ctx.font = '11px sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText('No history yet -- first snapshot at tick 300', W / 2, H / 2);
      return;
    }

    const maxAbs = Math.max(1, ...history.map(h => Math.abs(h.net)));
    const midY = H / 2;
    const slot = W / history.length;
    const barW = Math.max(2, slot * 0.6);

    // zero line
    ctx.strokeStyle = '#4a4340';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(0, midY + 0.5);
    ctx.lineTo(W, midY + 0.5);
    ctx.stroke();

    history.forEach((h, i) => {
      const barH = (Math.abs(h.net) / maxAbs) * (H / 2 - 4);
      const cx = i * slot + slot / 2;
      ctx.fillStyle = h.net >= 0 ? '#6fbf6f' : '#d9534f';
      if (h.net >= 0) ctx.fillRect(cx - barW / 2, midY - barH, barW, barH);
      else ctx.fillRect(cx - barW / 2, midY, barW, barH);
    });
  }
}


// ---- input.js ----
// Player input: build palette, zone painting, pause/speed. This is what turns the sim into an
// actual game instead of a passive screensaver -- there was no player agency before this.



const TOOLS = [
  { key: '0', tool: null, label: 'Select', cost: null },
  { key: '1', tool: 'wall', label: 'Wall', cost: BUILD_COST.wall },
  { key: '2', tool: 'turret', label: 'Turret', cost: BUILD_COST.turret },
  { key: '3', tool: 'fence', label: 'Fence', cost: BUILD_COST.fence },
  { key: '4', tool: 'trap', label: 'Trap', cost: BUILD_COST.trap },
  { key: '5', tool: 'zone-food', label: 'Food Zone', cost: null },
  { key: '6', tool: 'zone-bedroom', label: 'Bedroom Zone', cost: null },
  { key: '7', tool: 'zone-recreation', label: 'Recreation Zone', cost: null },
  { key: 'b', tool: 'bed', label: 'Bed', cost: BUILD_COST.bed },
  { key: 't', tool: 'table', label: 'Table', cost: BUILD_COST.table },
  { key: 'y', tool: 'door', label: 'Door', cost: BUILD_COST.door },
  { key: 'g', tool: 'generator', label: 'Generator', cost: BUILD_COST.generator },
  { key: 'w', tool: 'wire', label: 'Wire', cost: BUILD_COST.wire },
  // Water/plumbing grid (water.js): mirrors the generator/wire pair exactly -- a pump is the
  // source, pipe is the conduit -- but feeds Food/Recreation zone refill rate and the Recycling
  // Center's pollution-processing rate instead of turrets/tesla/watchtower.
  { key: 'q', tool: 'pump', label: 'Water Pump', cost: BUILD_COST.pump },
  { key: 'z', tool: 'pipe', label: 'Pipe', cost: BUILD_COST.pipe },
  // SEA:R truck fuel-type tradeoff (vehicles.js FUEL_TYPES): each garage now comes in 4 fuel
  // variants instead of one -- fossil (cheap/dirty), gas (best all-around), ethanol (clean,
  // temporarily saps Food zone refill per haul), electric (cleanest, needs the garage powered
  // or hauls crawl). The bare 'garage_recycling'/'garage_garbage' kinds still exist in
  // economy.js/vehicles.js for save-compat but are no longer offered directly in the toolbar.
  { key: 'v', tool: 'garage_recycling_fossil', label: 'Recycling Garage (Fossil)', cost: BUILD_COST.garage_recycling_fossil },
  { key: 'i', tool: 'garage_recycling_gas', label: 'Recycling Garage (Gas)', cost: BUILD_COST.garage_recycling_gas },
  { key: 'e', tool: 'garage_recycling_ethanol', label: 'Recycling Garage (Ethanol)', cost: BUILD_COST.garage_recycling_ethanol },
  { key: 'l', tool: 'garage_recycling_electric', label: 'Recycling Garage (Electric)', cost: BUILD_COST.garage_recycling_electric },
  { key: 'n', tool: 'garage_garbage_fossil', label: 'Garbage Garage (Fossil)', cost: BUILD_COST.garage_garbage_fossil },
  { key: 'h', tool: 'garage_garbage_gas', label: 'Garbage Garage (Gas)', cost: BUILD_COST.garage_garbage_gas },
  { key: 'o', tool: 'garage_garbage_ethanol', label: 'Garbage Garage (Ethanol)', cost: BUILD_COST.garage_garbage_ethanol },
  { key: 'p', tool: 'garage_garbage_electric', label: 'Garbage Garage (Electric)', cost: BUILD_COST.garage_garbage_electric },
  { key: 'c', tool: 'watchtower', label: 'Watchtower', cost: BUILD_COST.watchtower },
  { key: 'f', tool: 'floodlight', label: 'Floodlight', cost: BUILD_COST.floodlight },
  { key: 'x', tool: 'tesla', label: 'Tesla Coil', cost: BUILD_COST.tesla },
  { key: 'r', tool: 'recycling_center', label: 'Recycling Center', cost: BUILD_COST.recycling_center },
  { key: 'k', tool: 'camera', label: 'CCTV Camera', cost: BUILD_COST.camera },
  { key: 'm', tool: 'monitor_station', label: 'Monitor Station', cost: BUILD_COST.monitor_station },
  { key: 'u', tool: 'generator_nuclear', label: 'Nuclear Generator', cost: BUILD_COST.generator_nuclear },
  { key: 'j', tool: 'waste_storage', label: 'Waste Storage', cost: BUILD_COST.waste_storage },
  // Armory (security.js WEAPON_TIERS/tickArmoryIssuance): once built, every Guard/Sniper on the
  // roster is automatically issued Rifle tier (a second Armory unlocks Heavy) -- no per-citizen
  // pick-a-tier UI, per FEATURE_RESEARCH.md's scoped version of the Prison Architect armory idea.
  { key: 'a', tool: 'armory', label: 'Armory', cost: BUILD_COST.armory },
  // SEA:R multi-source power economy (FEATURE_RESEARCH.md): coal/wind/solar generator variants,
  // each a real siting/tradeoff decision instead of a strict upgrade over plain 'generator' --
  // see economy.js's BUILD_COST comment and power.js's isSource for how each tradeoff is enforced.
  { key: 'd', tool: 'generator_coal', label: 'Coal Generator', cost: BUILD_COST.generator_coal },
  { key: 's', tool: 'generator_wind', label: 'Wind Turbine', cost: BUILD_COST.generator_wind },
  { key: '8', tool: 'generator_solar', label: 'Solar Array', cost: BUILD_COST.generator_solar },
];

const TOOL_KEYS = Object.fromEntries(TOOLS.map(t => [t.key, t.tool]));
TOOL_KEYS['Escape'] = null;

class InputController {
  constructor(canvas, renderer, getWorld, onSpeedChange, onToast) {
    this.canvas = canvas;
    this.renderer = renderer;
    this.getWorld = getWorld;
    this.onSpeedChange = onSpeedChange;
    this.onToast = onToast;
    this.tool = null;
    this.hoverGridX = null;
    this.hoverGridY = null;
    this.speedIndex = 1; // index into SPEEDS
    this.SPEEDS = [0, 1, 2, 4];
    this._painting = false;
    this.selectedCitizen = -1;
    // Multi-select via marquee drag (Select tool only, see _onDown/_onUp): a plain click still
    // goes through selectedCitizen above and is untouched by any of this.
    this.selectedCitizens = [];
    this.marqueeActive = false;
    this.marqueeStartWorldX = 0; this.marqueeStartWorldY = 0;
    this.marqueeEndWorldX = 0; this.marqueeEndWorldY = 0;

    canvas.addEventListener('mousemove', (e) => this._onMove(e));
    canvas.addEventListener('mousedown', (e) => this._onDown(e));
    canvas.addEventListener('mouseup', (e) => this._onUp(e));
    canvas.addEventListener('mouseleave', () => { this.hoverGridX = null; this.hoverGridY = null; this._painting = false; this._panning = false; this.marqueeActive = false; });
    canvas.addEventListener('contextmenu', (e) => e.preventDefault()); // right-drag is pan, not a context menu
    canvas.addEventListener('wheel', (e) => this._onWheel(e), { passive: false });
    window.addEventListener('keydown', (e) => this._onKey(e));

    // ---- Touch input (strictly additive; every mouse path above is untouched) ----------------
    // Touch is translated into the SAME internal state the mouse handlers use (_painting,
    // _panning, marquee*) by synthesizing {clientX, clientY, button} shims and feeding them to
    // _onDown/_onMove/_onUp -- so one-finger paint, one-finger marquee, tap-to-select and the
    // 0.5-world-unit click-vs-drag threshold all behave identically to mouse without a second
    // implementation. Only two-finger pan/pinch needs its own state, because there is no mouse
    // gesture that pans and zooms simultaneously.
    this._touchId = null;         // identifier of the single finger driving paint/marquee/tap
    this._touchTapX = 0; this._touchTapY = 0; this._touchTapT = 0;
    this._touchMoved = false;
    this._pinchDist = 0;          // distance between the two fingers on the previous move
    this._pinchMidX = 0; this._pinchMidY = 0;
    // passive:false on all four so preventDefault() actually suppresses the browser's native
    // scroll/pinch-zoom. These are bound to the canvas element only -- topbar/toolbar/panel DOM
    // buttons are outside it and keep their native tap->click behaviour untouched.
    canvas.addEventListener('touchstart', (e) => this._onTouchStart(e), { passive: false });
    canvas.addEventListener('touchmove', (e) => this._onTouchMove(e), { passive: false });
    canvas.addEventListener('touchend', (e) => this._onTouchEnd(e), { passive: false });
    canvas.addEventListener('touchcancel', (e) => this._onTouchCancel(e), { passive: false });
  }

  // Mouse-event shim: the existing handlers only ever read clientX/clientY/button/preventDefault,
  // so a Touch can stand in for a MouseEvent verbatim.
  _touchAsMouse(t, button = 0) {
    return { clientX: t.clientX, clientY: t.clientY, button, preventDefault() {} };
  }

  _findTouch(list, id) {
    for (let i = 0; i < list.length; i++) if (list[i].identifier === id) return list[i];
    return null;
  }

  // Drop whatever the single finger had armed, without committing it (used when a second finger
  // arrives and the gesture turns out to be a pan/pinch rather than a paint or marquee).
  _abortSingleTouch() {
    this._touchId = null;
    this._painting = false;
    this.marqueeActive = false;
  }

  _beginPinch(a, b) {
    this._pinchDist = Math.hypot(a.clientX - b.clientX, a.clientY - b.clientY);
    this._pinchMidX = (a.clientX + b.clientX) / 2;
    this._pinchMidY = (a.clientY + b.clientY) / 2;
    this._panning = true;
  }

  _onTouchStart(e) {
    e.preventDefault(); // suppress native scroll/zoom/double-tap on the game canvas
    if (e.touches.length >= 2) {
      // Two (or more) fingers: pan + pinch. Cancel anything the first finger armed so a
      // two-finger gesture never leaves a stray blueprint or half-drawn marquee behind.
      if (this._touchId !== null) this._abortSingleTouch();
      this._beginPinch(e.touches[0], e.touches[1]);
      return;
    }
    if (this._touchId !== null) return; // already tracking a finger
    const t = e.changedTouches[0];
    if (!t) return;
    this._touchId = t.identifier;
    this._touchTapX = t.clientX; this._touchTapY = t.clientY;
    this._touchTapT = (typeof performance !== 'undefined' ? performance.now() : Date.now());
    this._touchMoved = false;
    const shim = this._touchAsMouse(t, 0);
    // Seed the hover cell from THIS touch before dispatching. _onDown's build branch calls
    // _place() straight away and _place() reads hoverGridX/Y, which with a mouse is always fresh
    // because a mousedown is necessarily preceded by a mousemove over the canvas. A finger has no
    // such preamble, so without this the first tile of a touch-drag would be placed at whatever
    // the last mouse position happened to be (or nowhere at all on a touch-only device).
    this._updateHover(shim);
    // Left-button-down semantics: with a tool this starts painting and places immediately; with
    // the Select tool this runs _pickCitizen (so a tap already selects) and arms the marquee.
    this._onDown(shim);
  }

  _onTouchMove(e) {
    e.preventDefault();
    if (this._panning && e.touches.length >= 2) {
      const a = e.touches[0], b = e.touches[1];
      const dist = Math.hypot(a.clientX - b.clientX, a.clientY - b.clientY);
      const midX = (a.clientX + b.clientX) / 2, midY = (a.clientY + b.clientY) / 2;
      // Pan by the midpoint delta -- same call the right/middle-drag pan uses.
      this.renderer.panByScreenDelta(midX - this._pinchMidX, midY - this._pinchMidY, this.getWorld());
      // Pinch: change in finger separation since the last move is the zoom factor, anchored at
      // the midpoint in canvas-local coordinates -- same call the wheel handler uses.
      if (this._pinchDist > 0 && dist > 0) {
        const factor = dist / this._pinchDist;
        if (Math.abs(factor - 1) > 0.002) {
          const rect = this.canvas.getBoundingClientRect();
          this.renderer.zoomAt(midX - rect.left, midY - rect.top, factor, this.getWorld());
        }
      }
      this._pinchDist = dist; this._pinchMidX = midX; this._pinchMidY = midY;
      return;
    }
    if (this._touchId === null) return;
    const t = this._findTouch(e.changedTouches, this._touchId);
    if (!t) return;
    if (Math.hypot(t.clientX - this._touchTapX, t.clientY - this._touchTapY) > 8) this._touchMoved = true;
    this._onMove(this._touchAsMouse(t, 0));
  }

  _onTouchEnd(e) {
    e.preventDefault();
    if (this._panning) {
      // Keep panning only while two fingers remain down; otherwise end the gesture. A finger
      // left over after a pinch does NOT fall through into paint/marquee -- that would drop
      // buildings the player never asked for.
      if (e.touches.length >= 2) { this._beginPinch(e.touches[0], e.touches[1]); return; }
      if (e.touches.length === 0) { this._panning = false; this._pinchDist = 0; }
      return;
    }
    if (this._touchId === null) return;
    const t = this._findTouch(e.changedTouches, this._touchId);
    if (!t) return;
    const dt = (typeof performance !== 'undefined' ? performance.now() : Date.now()) - this._touchTapT;
    this._touchId = null;
    // Tap = short + no real movement. _onDown already ran _pickCitizen for the Select tool (so
    // the selection is done), but fingers are imprecise and at high zoom a couple of stray
    // pixels can exceed _onUp's 0.5-world-unit marquee threshold and turn a tap into a 1-citizen
    // box-select. Disarming the marquee here keeps a tap a pure single pick.
    if (!this._touchMoved && dt < 400) this.marqueeActive = false;
    this._onUp(this._touchAsMouse(t, 0));
    this.hoverGridX = null; this.hoverGridY = null; // no lingering hover ghost after lift-off
  }

  _onTouchCancel(e) {
    if (e.cancelable) e.preventDefault();
    this._abortSingleTouch();
    this._panning = false;
    this._pinchDist = 0;
    this.hoverGridX = null; this.hoverGridY = null;
  }

  setTool(tool) {
    this.tool = tool;
  }

  togglePause() {
    const w = this.getWorld();
    if (w) w.paused = !w.paused;
  }

  setSpeedIndex(i) {
    this.speedIndex = Math.max(0, Math.min(this.SPEEDS.length - 1, i));
    this.onSpeedChange?.(this.SPEEDS[this.speedIndex]);
  }

  _updateHover(e) {
    const rect = this.canvas.getBoundingClientRect();
    const [wx, wy] = this.renderer.screenToWorld(e.clientX - rect.left, e.clientY - rect.top);
    this.hoverWorldX = wx; this.hoverWorldY = wy;
    this.hoverGridX = Math.floor(wx);
    this.hoverGridY = Math.floor(wy);
  }

  _onMove(e) {
    if (this._panning) {
      this.renderer.panByScreenDelta(e.clientX - this._panLastX, e.clientY - this._panLastY, this.getWorld());
      this._panLastX = e.clientX; this._panLastY = e.clientY;
      return;
    }
    this._updateHover(e);
    if (this._painting) this._place();
    // Marquee only ever runs with the Select tool (see _onDown) and never overlaps painting.
    if (this.marqueeActive) { this.marqueeEndWorldX = this.hoverWorldX; this.marqueeEndWorldY = this.hoverWorldY; }
  }

  _onDown(e) {
    // Right-click and middle-click drag the camera; left-click keeps its build/select role.
    // There was previously no way to move the camera by hand at all -- it was 100% auto-framed.
    if (e.button === 2 || e.button === 1) {
      e.preventDefault();
      this._panning = true;
      this._panLastX = e.clientX; this._panLastY = e.clientY;
      return;
    }
    if (e.button !== 0) return;

    if (this.tool === null) {
      // Select tool: try an immediate single pick first (this is the existing plain-click path,
      // completely unchanged). Only if that pick lands on empty ground do we arm a possible
      // marquee drag -- if the mouseup never moves it stays a no-op deselect-click, exactly as
      // before this feature existed.
      this._updateHover(e);
      const world = this.getWorld();
      if (world) this._pickCitizen(world);
      this.selectedCitizens = [];
      if (this.selectedCitizen === -1 && world) {
        this.marqueeActive = true;
        this.marqueeStartWorldX = this.hoverWorldX; this.marqueeStartWorldY = this.hoverWorldY;
        this.marqueeEndWorldX = this.hoverWorldX; this.marqueeEndWorldY = this.hoverWorldY;
      }
      return;
    }

    this._painting = true;
    this._place();
  }

  _onUp(e) {
    if (e.button === 2 || e.button === 1) { this._panning = false; return; }
    this._painting = false;
    if (this.marqueeActive) {
      this.marqueeActive = false;
      const world = this.getWorld();
      const dx = this.marqueeEndWorldX - this.marqueeStartWorldX;
      const dy = this.marqueeEndWorldY - this.marqueeStartWorldY;
      // Below this distance it's a click, not a drag -- the single-pick from _onDown already
      // handled it (selected a citizen, or deselected on empty ground), so leave it alone.
      if (world && Math.hypot(dx, dy) > 0.5) {
        const x0 = Math.min(this.marqueeStartWorldX, this.marqueeEndWorldX);
        const x1 = Math.max(this.marqueeStartWorldX, this.marqueeEndWorldX);
        const y0 = Math.min(this.marqueeStartWorldY, this.marqueeEndWorldY);
        const y1 = Math.max(this.marqueeStartWorldY, this.marqueeEndWorldY);
        const picked = [];
        for (let i = 0; i < world.citizens.count; i++) {
          if (!world.citizens.isAliveAt(i)) continue;
          const cx = world.citizens.x[i], cy = world.citizens.y[i];
          if (cx >= x0 && cx <= x1 && cy >= y0 && cy <= y1) picked.push(i);
        }
        this.selectedCitizens = picked;
      }
    }
  }

  _onWheel(e) {
    e.preventDefault();
    const rect = this.canvas.getBoundingClientRect();
    const factor = e.deltaY < 0 ? 1.1 : 1 / 1.1;
    this.renderer.zoomAt(e.clientX - rect.left, e.clientY - rect.top, factor, this.getWorld());
  }

  recenter() {
    const world = this.getWorld();
    if (world) this.renderer.recenter(world);
  }

  _place() {
    const world = this.getWorld();
    if (!world || this.hoverGridX == null) return;

    if (!this.tool) {
      this._pickCitizen(world);
      return;
    }

    const x = this.hoverGridX, y = this.hoverGridY;
    if (x < 0 || y < 0 || x >= world.width || y >= world.height) return;

    if (this.tool.startsWith('zone-')) {
      const kind = { 'zone-food': ZoneKind.Food, 'zone-bedroom': ZoneKind.Bedroom, 'zone-recreation': ZoneKind.Recreation }[this.tool];
      world.zones.set(x, y, kind);
      return;
    }

    if (world.grid.wallThingId[world.grid.index(x, y)] !== 0) { this.onToast?.('Already occupied'); return; }
    for (const s of world.structures) {
      if (!s.destroyed && Math.floor(s.x) === x && Math.floor(s.y) === y) { this.onToast?.('Already occupied'); return; }
    }

    // Tech gate (research.js) -- checked BEFORE the scrap check so a locked buildable reports the
    // real reason rather than a misleading "Not enough scrap". Fails open for ungated tools.
    if (!isToolUnlocked(world.research, this.tool)) {
      const node = researchNodeForTool(this.tool);
      this.onToast?.(`Locked -- research "${node ? node.name : 'unknown'}" first`);
      return;
    }

    if (!canAfford(world, this.tool)) { this.onToast?.('Not enough scrap'); return; }
    spend(world, this.tool);
    // Every buildable -- including walls -- is placed as a blueprint that a citizen has to
    // walk over and actually construct (see jobs.js JobState.Building), not instant placement.
    world.build(this.tool, x + 0.5, y + 0.5);
  }

  _pickCitizen(world) {
    let bestI = -1, bestDist = 0.8; // pick radius in world units
    for (let i = 0; i < world.citizens.count; i++) {
      if (!world.citizens.isAliveAt(i)) continue;
      const d = Math.hypot(world.citizens.x[i] - this.hoverWorldX, world.citizens.y[i] - this.hoverWorldY);
      if (d < bestDist) { bestDist = d; bestI = i; }
    }
    this.selectedCitizen = bestI;
  }

  _onKey(e) {
    // No world means the title screen is up (main.js boots lazily) -- every shortcut below is a
    // gameplay shortcut, and none of them should fire over a menu. The typing guard is for the
    // New Game setup form's seed box, where letters like 'b'/'t'/'m' are just text.
    if (!this.getWorld()) return;
    const t = e.target;
    if (t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.tagName === 'SELECT' || t.isContentEditable)) return;
    // Conquest map overlay (worldmap.js). Bound to SHIFT+M, not plain 'm' -- lowercase 'm' is
    // already the Monitor Station buildable's hotkey in TOOLS, so this deliberately only claims
    // the uppercase variant and lets 'm' fall through to the tool table below. main.js supplies
    // onToggleMap.
    if (e.key === 'M') { this.onToggleMap?.(); return; }
    // Budget report overlay (world.js's finance ledger, surfaced in main.js). SHIFT+B for the
    // same reason as SHIFT+M above -- lowercase 'b' is already the Bed buildable's hotkey.
    if (e.key === 'B') { this.onToggleFinance?.(); return; }
    // Research/tech tree overlay (research.js, surfaced in main.js). SHIFT+T, same
    // uppercase-only convention -- lowercase 't' is the Table buildable's hotkey. Note SHIFT+R
    // is NOT available: main.js binds both 'r' and 'R' to restart().
    if (e.key === 'T') { this.onToggleResearch?.(); return; }
    // Onboarding reference panel (tutorial.js, surfaced in main.js). F1 and '?' are both free --
    // '?' is Shift+/ and appears in no TOOL_KEYS entry, and F1 collides with nothing here or in
    // main.js's F5/F9 save/load bindings. F1 needs preventDefault or the browser opens its own help.
    if (e.key === 'F1' || e.key === '?') { e.preventDefault(); this.onToggleHelp?.(); return; }
    if (e.key === 'Escape' && this.onToggleMap) { this.onCloseMap?.(); /* falls through to clear tool */ }
    if (e.key === 'Escape' && this.onToggleResearch) { this.onCloseResearch?.(); /* falls through to clear tool */ }
    if (e.key === 'Escape' && this.onToggleFinance) { this.onCloseFinance?.(); /* falls through to clear tool */ }
    if (e.key in TOOL_KEYS) { this.setTool(TOOL_KEYS[e.key]); return; }
    if (e.key === ' ') { e.preventDefault(); this.togglePause(); return; }
    if (e.key === '+' || e.key === '=') { this.setSpeedIndex(this.speedIndex + 1); return; }
    if (e.key === '-') { this.setSpeedIndex(this.speedIndex - 1); return; }
  }
}


// ---- tutorial.js ----
// Onboarding: a short first-run guided tour, plus a permanently-available reference panel.
//
// This game has accumulated a lot of systemic depth (needs/mood/traits, blueprint construction,
// zoning, power + water graphs, day/night, weather, fire, pollution + nuclear hazard, a wave
// siege with 4 archetypes and 3 damage types, vehicles + fuel types, a research tree, a grading
// panel, a finance ledger and a conquest layer) behind exactly one line of hint text. Two pieces
// close that gap:
//
//   1. GUIDED TOUR -- 8 lightweight floating callouts, each anchored to the REAL DOM element it
//      is talking about via getBoundingClientRect(). Deliberately not a modal: the point is that
//      you can see the toolbar/topbar/button being described while you read about it. Fires once,
//      automatically, the first time a player ever begins a new settlement (localStorage flag
//      TUTORIAL_SEEN_KEY), never on Continue/Load, and is skippable at every step.
//
//   2. REFERENCE PANEL -- a full-screen .panel modal (same convention as #research/#worldmap/
//      #finance) reachable forever after from the topbar "?" button, F1 or the '?' key. Short
//      scannable entries, not prose: how citizens choose jobs, how building actually works, what
//      the storyteller does, the scrap/pollution/research loop, the archetype/damage matchups,
//      and one line per building category.
//
// Nothing in here touches sim state -- it is purely presentation, and it reads no world.

const TUTORIAL_SEEN_KEY = 'settlement-defense-tutorial-seen';

